:root {
  --gold: #c9a45c;
  --gold-bright: #e7cd92;
  --gold-dim: #7c6438;
  --parchment: #e9dfc8;
  --parchment-dim: #a89f8c;
  --blood: #8f2f30;
  --blood-bright: #c94b45;
  --ink: #0a0a0d;
  --ink-soft: #121218;
  --hp: #a3352f;
  --stamina: #6d8a45;
  --focus: #466a8e;
  --shadow: 0 20px 80px rgba(0,0,0,.8);
  --serif: "Cinzel", "Trajan Pro", "Palatino Linotype", "Book Antiqua", Palatino, Georgia, serif;
  --body: "EB Garamond", "Palatino Linotype", Palatino, Georgia, serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; background: #060608; color: var(--parchment); font-family: var(--body); overflow: hidden; }
body { user-select: none; -webkit-user-select: none; }
#app { position: fixed; inset: 0; overflow: hidden; background: #060608; }
#game-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: none; }
.hidden { display: none !important; }

/* =============== generic screen =============== */
.screen { position: absolute; inset: 0; z-index: 60; }
.fade { position: absolute; inset: 0; background: #050506; opacity: 0; pointer-events: none; z-index: 90; transition: opacity .65s ease; }
.fade.on { opacity: 1; }
.fade.flash { background: #f7f0dc; opacity: 1; transition: opacity .12s ease; }

/* =============== HUD =============== */
#hud { position: absolute; inset: 0; z-index: 20; pointer-events: none; }
.hud-top-left { position: absolute; top: 26px; left: 30px; width: 390px; }
.vitals { width: 330px; filter: drop-shadow(0 3px 8px rgba(0,0,0,.9)); }
.bar-row { display: flex; align-items: center; gap: 8px; margin-bottom: 5px; }
.bar-ornament { width: 20px; height: 20px; border: 1px solid var(--gold-dim); transform: rotate(45deg); position: relative; background: linear-gradient(135deg,#413219,#0b0b0c); flex: 0 0 auto; }
.bar-ornament::after { content: ""; position: absolute; inset: 4px; border: 1px solid rgba(201,164,92,.35); }
.bar-ornament.small { width: 14px; height: 14px; }
.bar-shell { position: relative; height: 15px; flex: 1; background: rgba(4,4,6,.8); border: 1px solid rgba(201,164,92,.5); box-shadow: inset 0 0 12px #000, 0 0 0 1px rgba(0,0,0,.75); clip-path: polygon(0 0, 100% 0, calc(100% - 8px) 100%, 0 100%); overflow: hidden; }
.st-row .bar-shell { height: 10px; }
.fp-row .bar-shell { height: 8px; }
.bar-fill { position: absolute; inset: 0; width: 100%; transform-origin: left center; transition: transform .18s ease; }
.bar-lag { position: absolute; inset: 0; width: 100%; transform-origin: left center; background: #e7d9b4; opacity: .55; transition: transform .6s ease .15s; }
.bar-fill.hp { background: linear-gradient(90deg, #5c1817, var(--hp) 45%, #be4c40); }
.bar-fill.stamina { background: linear-gradient(90deg, #34491f, var(--stamina) 55%, #93ae5c); }
.bar-fill.focus { background: linear-gradient(90deg, #1e3347, var(--focus) 55%, #6f9bc4); }
.status-icons { display: flex; gap: 8px; margin-top: 10px; align-items: center; }
.status-pill { display: flex; align-items: center; gap: 8px; padding: 4px 11px 4px 8px; border: 1px solid rgba(201,164,92,.35); background: linear-gradient(180deg, rgba(25,22,16,.9), rgba(9,9,11,.85)); font-family: var(--serif); color: var(--gold-bright); font-size: 14px; letter-spacing: .08em; box-shadow: 0 4px 12px rgba(0,0,0,.5); }
.flask-glyph { font-size: 17px; color: #d9b56d; text-shadow: 0 0 8px rgba(217,181,109,.7); }
#buff-icons { display: flex; gap: 6px; }
.buff { border: 1px solid rgba(201,164,92,.3); background: rgba(10,10,13,.8); padding: 3px 7px; font-size: 10px; letter-spacing: .1em; color: var(--gold); font-family: var(--serif); }
.objective { margin-top: 22px; max-width: 330px; border-left: 1px solid rgba(201,164,92,.5); padding: 2px 0 2px 13px; text-shadow: 0 2px 8px #000; }
.objective-kicker { font-family: var(--serif); font-size: 9px; letter-spacing: .28em; color: var(--gold); opacity: .8; margin-bottom: 4px; }
#objective-text { font-size: 15px; color: #d9d2c1; font-style: italic; line-height: 1.35; }

.hud-top-right { position: absolute; top: 26px; right: 32px; text-align: right; }
.motes-display { display: inline-flex; align-items: baseline; gap: 9px; font-family: var(--serif); font-size: 23px; letter-spacing: .06em; color: var(--gold-bright); text-shadow: 0 0 12px rgba(201,164,92,.4), 0 2px 10px #000; }
.mote-glyph { font-size: 17px; color: var(--gold); animation: motePulse 3.2s ease-in-out infinite; }
@keyframes motePulse { 0%,100% { text-shadow: 0 0 4px rgba(201,164,92,.4); } 50% { text-shadow: 0 0 16px rgba(231,205,146,.9); } }
.equip-display { margin-top: 14px; display: flex; flex-direction: column; gap: 5px; align-items: flex-end; }
.equip-slot { display: flex; align-items: center; gap: 9px; font-size: 11px; letter-spacing: .08em; color: #b7ad99; }
.slot-label { font-family: var(--serif); font-size: 8px; letter-spacing: .2em; color: var(--gold-dim); border: 1px solid rgba(201,164,92,.25); padding: 2px 4px; }
.region-tag { margin-top: 20px; display: flex; flex-direction: column; gap: 2px; font-family: var(--serif); letter-spacing: .22em; }
#region-name { font-size: 12px; color: var(--gold); }
#region-sub { font-size: 9px; color: #7e7667; letter-spacing: .3em; }

.lock-reticle { position: fixed; width: 34px; height: 34px; transform: translate(-50%,-50%); z-index: 25; pointer-events: none; }
.reticle-dot { position: absolute; left: 50%; top: 50%; width: 4px; height: 4px; margin: -2px; background: var(--gold-bright); border-radius: 50%; box-shadow: 0 0 8px #fff; }
.reticle-ring { position: absolute; inset: 0; border: 1px solid rgba(231,205,146,.8); border-radius: 50%; animation: reticleSpin 7s linear infinite; }
.reticle-ring::before, .reticle-ring::after { content: ""; position: absolute; background: var(--gold); }
.reticle-ring::before { left: 50%; top: -3px; width: 1px; height: 8px; }
.reticle-ring::after { left: 50%; bottom: -3px; width: 1px; height: 8px; }
@keyframes reticleSpin { to { transform: rotate(360deg); } }

.enemy-bar { position: fixed; width: 96px; height: 5px; transform: translate(-50%,-50%); background: rgba(0,0,0,.7); border: 1px solid rgba(201,164,92,.25); z-index: 21; pointer-events: none; }
.enemy-bar .fill { height: 100%; background: linear-gradient(90deg,#6c1d1b,#b0453b); transition: width .15s; }
.enemy-bar .name { position: absolute; top: -15px; left: 50%; transform: translateX(-50%); font-family: var(--serif); font-size: 8px; letter-spacing: .12em; color: #cfc4a9; white-space: nowrap; text-shadow: 0 1px 3px #000; }

.interact-prompt { position: absolute; left: 50%; bottom: 19%; transform: translateX(-50%); display: flex; align-items: center; gap: 11px; z-index: 25; background: linear-gradient(90deg, rgba(8,8,10,.1), rgba(8,8,10,.85) 20%, rgba(8,8,10,.85) 80%, rgba(8,8,10,.1)); padding: 9px 30px; font-size: 15px; color: #ddd3bc; letter-spacing: .04em; }
.key { display: inline-flex; min-width: 25px; height: 25px; align-items: center; justify-content: center; border: 1px solid var(--gold); color: var(--gold-bright); font-family: var(--serif); font-size: 12px; padding: 0 5px; background: rgba(201,164,92,.08); box-shadow: inset 0 0 8px rgba(201,164,92,.12); }

.boss-bar { position: absolute; left: 50%; bottom: 56px; transform: translateX(-50%); width: min(760px, 68vw); z-index: 26; filter: drop-shadow(0 4px 16px #000); }
.boss-title { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 7px; padding: 0 2px; }
#boss-name { font-family: var(--serif); letter-spacing: .2em; font-size: 16px; color: #e5d6b4; }
#boss-sub { font-size: 11px; font-style: italic; color: #9d917b; letter-spacing: .06em; }
.boss-bar-shell { height: 12px; background: #08080a; border: 1px solid rgba(201,164,92,.55); padding: 2px; box-shadow: 0 0 0 1px #000, inset 0 0 12px #000; }
.boss-bar-fill { height: 100%; background: linear-gradient(90deg, #531211, #a43a2f 50%, #d0644c); transition: width .2s; }
.boss-bar-lag { position: absolute; height: 12px; margin-top: -12px; background: rgba(231,205,146,.45); transition: width .7s ease .2s; }
.boss-phase { position: absolute; right: -26px; top: 17px; font-family: var(--serif); font-size: 13px; color: var(--gold); }

.subtitle { position: absolute; left: 50%; bottom: 15%; transform: translateX(-50%); width: min(720px, 70vw); text-align: center; font-size: 20px; line-height: 1.5; color: #eadfc6; font-style: italic; text-shadow: 0 2px 12px #000, 0 0 30px #000; z-index: 30; }
.toasts { position: absolute; right: 32px; top: 42%; display: flex; flex-direction: column; align-items: flex-end; gap: 7px; z-index: 30; }
.toast { font-family: var(--serif); font-size: 12px; letter-spacing: .1em; color: var(--parchment); background: linear-gradient(90deg, transparent, rgba(10,10,13,.9)); padding: 7px 13px; border-right: 2px solid var(--gold); animation: toastIn .35s ease, toastOut .4s ease 2.6s forwards; text-shadow: 0 1px 4px #000; }
.toast.gold { color: var(--gold-bright); }
.toast.blood { color: #e59a8e; border-right-color: var(--blood); }
@keyframes toastIn { from { opacity: 0; transform: translateX(24px); } }
@keyframes toastOut { to { opacity: 0; transform: translateX(16px); } }

.damage-flash { position: absolute; inset: 0; pointer-events: none; opacity: 0; background: radial-gradient(circle at center, transparent 35%, rgba(120,10,10,.55) 100%); transition: opacity .25s; z-index: 22; }
.damage-flash.on { opacity: 1; transition: opacity .05s; }
.hint { position: absolute; left: 50%; bottom: 10%; transform: translateX(-50%); font-size: 13px; letter-spacing: .12em; color: #a99e88; font-family: var(--serif); text-shadow: 0 2px 8px #000; z-index: 24; }
.contextual { position: absolute; left: 50%; bottom: 26%; transform: translateX(-50%); font-size: 14px; color: var(--gold-bright); font-family: var(--serif); letter-spacing: .13em; text-shadow: 0 2px 8px #000; z-index: 24; }

/* =============== cinematic =============== */
.cinematic { position: absolute; inset: 0; z-index: 70; pointer-events: none; }
.letterbox { position: absolute; left: 0; width: 100%; height: 9vh; background: #030304; z-index: 2; }
.letterbox.top { top: 0; }
.letterbox.bottom { bottom: 0; }
.cinematic-title { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; z-index: 3; text-align: center; background: radial-gradient(circle, rgba(0,0,0,.15), rgba(0,0,0,.7)); }
.cinematic-title h1 { font-family: var(--serif); font-size: clamp(34px, 6vw, 82px); letter-spacing: .22em; font-weight: 400; margin: 0 0 18px; color: #e9dcc0; text-shadow: 0 0 40px rgba(201,164,92,.35); animation: titleReveal 2.5s ease both; }
.cinematic-title p { font-family: var(--serif); font-size: 12px; letter-spacing: .42em; color: var(--gold); text-transform: uppercase; }
@keyframes titleReveal { from { opacity: 0; letter-spacing: .4em; filter: blur(8px); } }
.cinematic-lines { position: absolute; left: 50%; bottom: 16%; transform: translateX(-50%); width: min(780px, 72vw); text-align: center; z-index: 3; }
.cine-line { font-size: clamp(18px, 2vw, 27px); font-style: italic; line-height: 1.55; color: #eee4ce; text-shadow: 0 2px 18px #000, 0 0 40px #000; animation: lineIn .9s ease both; margin-bottom: 8px; }
@keyframes lineIn { from { opacity: 0; transform: translateY(8px); } }
.skip-hint { position: absolute; right: 28px; bottom: 11vh; z-index: 4; font-family: var(--serif); font-size: 10px; letter-spacing: .18em; color: rgba(201,164,92,.55); }

/* =============== title =============== */
.title-screen { background: linear-gradient(180deg, rgba(4,5,7,.5), rgba(4,5,7,.15) 35%, rgba(5,5,7,.8) 100%); display: flex; flex-direction: column; align-items: center; justify-content: center; overflow: hidden; }
.title-vignette { position: absolute; inset: 0; background: radial-gradient(ellipse at 50% 42%, transparent 20%, rgba(3,3,5,.55) 75%, rgba(3,3,5,.95)); pointer-events: none; }
.title-content { position: relative; z-index: 2; text-align: center; display: flex; flex-direction: column; align-items: center; animation: fadeUp 2s ease both; max-width: 900px; padding: 0 20px; }
@keyframes fadeUp { from { opacity: 0; transform: translateY(18px); } }
.title-eyebrow { font-family: var(--serif); font-size: 10px; letter-spacing: .5em; color: var(--gold); opacity: .7; margin-bottom: 26px; }
.game-title { margin: 0; font-family: var(--serif); font-weight: 400; line-height: .93; display: flex; flex-direction: column; align-items: center; text-shadow: 0 4px 40px rgba(0,0,0,.8); }
.game-title .t-small { font-size: clamp(11px, 1.1vw, 15px); letter-spacing: .9em; margin-bottom: 9px; color: var(--gold); padding-left: .9em; }
.game-title .t-main { font-size: clamp(54px, 9.8vw, 138px); letter-spacing: .12em; color: #e7ddc8; }
.game-title .t-main.gold { color: var(--gold-bright); text-shadow: 0 0 60px rgba(201,164,92,.25), 0 6px 30px rgba(0,0,0,.9); }
.title-rule { display: flex; align-items: center; gap: 18px; width: min(480px, 65vw); margin: 25px 0 18px; color: var(--gold); }
.title-rule i { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, rgba(201,164,92,.6), transparent); }
.title-rule span { font-size: 12px; opacity: .8; }
.title-tagline { font-size: clamp(14px, 1.4vw, 18px); line-height: 1.7; color: #c2b8a4; font-style: italic; margin: 0 0 38px; text-shadow: 0 2px 14px #000; }
.title-menu { display: flex; flex-direction: column; gap: 9px; width: min(330px, 72vw); }
.menu-btn { position: relative; background: linear-gradient(180deg, rgba(22,21,19,.55), rgba(7,7,9,.75)); border: 1px solid rgba(201,164,92,.28); color: #c6bba4; padding: 14px 20px; font-family: var(--serif); font-size: 12px; letter-spacing: .26em; cursor: pointer; transition: all .2s ease; text-transform: uppercase; }
.menu-btn:hover { border-color: rgba(231,205,146,.75); color: #f0e6d0; background: linear-gradient(180deg, rgba(64,53,31,.55), rgba(13,12,12,.9)); letter-spacing: .29em; box-shadow: 0 0 30px rgba(201,164,92,.12), inset 0 0 20px rgba(201,164,92,.05); }
.menu-btn.primary { border-color: rgba(201,164,92,.6); color: var(--gold-bright); }
.menu-btn:disabled { opacity: .35; cursor: default; }
.title-saveinfo { margin-top: 16px; min-height: 18px; font-family: var(--serif); font-size: 9px; letter-spacing: .16em; color: #7d7567; }
.title-footer { position: absolute; bottom: 25px; left: 50%; transform: translateX(-50%); font-family: var(--serif); font-size: 9px; letter-spacing: .34em; color: rgba(201,164,92,.45); z-index: 2; }
.title-version { position: absolute; bottom: 25px; right: 28px; font-size: 9px; letter-spacing: .12em; color: rgba(150,143,128,.35); z-index: 2; }

/* =============== loading =============== */
.loading-screen { background: radial-gradient(circle at 50% 45%, #14131a, #060608 70%); display: flex; flex-direction: column; align-items: center; justify-content: center; z-index: 100; transition: opacity .7s ease; }
.loading-screen.done { opacity: 0; pointer-events: none; }
.load-sigil { font-size: 36px; color: var(--gold); animation: sigil 2.4s ease-in-out infinite; margin-bottom: 22px; }
@keyframes sigil { 0%,100% { opacity: .45; transform: rotate(0) scale(.95); text-shadow: 0 0 10px rgba(201,164,92,.3); } 50% { opacity: 1; transform: rotate(180deg) scale(1.05); text-shadow: 0 0 36px rgba(201,164,92,.8); } }
.load-title { font-family: var(--serif); font-size: 20px; letter-spacing: .42em; color: #d8cdb6; margin-bottom: 34px; }
.load-bar { width: 280px; height: 2px; background: #1e1c1a; overflow: hidden; }
#load-fill { height: 100%; width: 5%; background: linear-gradient(90deg, #5d4a28, var(--gold-bright)); transition: width .4s ease; box-shadow: 0 0 13px var(--gold); }
.load-status { margin-top: 15px; font-size: 11px; letter-spacing: .2em; color: #756d5e; font-family: var(--serif); }

/* =============== overlay menus =============== */
.overlay { background: rgba(3,3,5,.78); backdrop-filter: blur(7px); display: flex; align-items: center; justify-content: center; z-index: 65; }
.menu-frame { width: min(760px, 88vw); max-height: 86vh; display: flex; flex-direction: column; background: linear-gradient(160deg, rgba(20,19,17,.97), rgba(8,8,10,.98)); border: 1px solid rgba(201,164,92,.4); box-shadow: var(--shadow), inset 0 0 80px rgba(201,164,92,.03); position: relative; padding: 26px 30px 22px; animation: menuIn .25s ease; }
.menu-frame.wide { width: min(1000px, 92vw); }
@keyframes menuIn { from { opacity: 0; transform: scale(.985) translateY(8px); } }
