      const up = new THREE.Mesh(new THREE.CylinderGeometry(.085, .072, .4, 6), cfg.armored ? metal : skin); up.position.y = -.2; sh.add(up);
      const el = new THREE.Group(); el.position.y = -.4; sh.add(el);
