  buildHound(mkMat, eye) {
    const bodyM = mkMat(0x3e3a30, { roughness: .95 });
    const furM = mkMat(0x2e2a24, { roughness: 1 });
    const boneM = mkMat(0x99917c, { roughness: .8 });
    const eyeM = eye(0xff3a2e);
    const body = new THREE.Mesh(new THREE.BoxGeometry(.52, .48, 1.15), bodyM); body.position.y = .82; this.body.add(body);
    const chest = new THREE.Mesh(new THREE.BoxGeometry(.6, .56, .5), bodyM); chest.position.set(0, .88, .35); this.body.add(chest);
    const head = new THREE.Group(); head.position.set(0, .94, .72); this.body.add(head); this.head = head;
    const skull = new THREE.Mesh(new THREE.BoxGeometry(.34, .32, .45), furM); head.add(skull);
    const snout = new THREE.Mesh(new THREE.BoxGeometry(.2, .16, .35), boneM); snout.position.set(0, -.05, .32); head.add(snout);
    const jaw = new THREE.Mesh(new THREE.BoxGeometry(.19, .08, .3), boneM); jaw.position.set(0, -.17, .28); jaw.name = 'jaw'; head.add(jaw);
    for (const ex of [-.09, .09]) { const e = new THREE.Mesh(new THREE.SphereGeometry(.035, 6, 5), eyeM); e.position.set(ex, .06, .2); head.add(e); const gl = makeGlowSprite(0xff3a2e, .3); gl.position.set(ex, .06, .24); head.add(gl); this.eyeMats.push(gl.material); }
    for (let i = 0; i < 4; i++) { const spike = new THREE.Mesh(new THREE.ConeGeometry(.06, .25, 4), boneM); spike.position.set(rand(-.15, .15), .32, -.2 + i * .18); head.parent.add(spike); }
    // tail
    const tail = new THREE.Mesh(new THREE.CylinderGeometry(.03, .07, .8, 4), furM); tail.position.set(0, 1.0, -.7); tail.rotation.x = .8; this.body.add(tail);
    // legs
    const mk = (x, z) => {
      const g = new THREE.Group(); g.position.set(x, .68, z); this.body.add(g);
      const up = new THREE.Mesh(new THREE.CylinderGeometry(.07, .055, .4, 5), furM); up.position.y = -.2; g.add(up);
      const low = new THREE.Group(); low.position.y = -.4; g.add(low);
      const l2 = new THREE.Mesh(new THREE.CylinderGeometry(.05, .04, .34, 5), bodyM); l2.position.y = -.17; low.add(l2);
      const foot = new THREE.Mesh(new THREE.BoxGeometry(.12, .08, .22), boneM); foot.position.set(0, -.34, .05); low.add(foot);
      return { hip: g, knee: low };
    };
    this.legL = mk(-.2, .38); this.legR = mk(.2, .38);
    this.legL2 = mk(-.2, -.42); this.legR2 = mk(.2, -.42);
  }

  addTelegraph() {
    const mat = new THREE.MeshBasicMaterial({ color: 0xff4a2a, transparent: true, opacity: 0, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
    const ring = new THREE.Mesh(new THREE.RingGeometry(.55, .72, 24), mat);
    ring.rotation.x = -Math.PI / 2; ring.position.y = .04; this.root.add(ring); this.telegraph = ring;
  }
  addAlertIcon() {
    const c = document.createElement('canvas'); c.width = 64; c.height = 64;
    const ctx = c.getContext('2d');
    ctx.fillStyle = '#e8cf92'; ctx.font = 'bold 52px Georgia'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText('!', 32, 34);
    const tex = new THREE.CanvasTexture(c);
    const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false });
    const s = new THREE.Sprite(mat); s.position.y = 2.4; s.scale.setScalar(.45); s.visible = false; this.root.add(s); this.alertIcon = s;
  }

  /* ==================== UPDATE ==================== */
  update(dt, player) {
    if (!this.alive) { this.updateDeath(dt); return; }
    this.stateTime += dt;
    this.attackCooldown = Math.max(0, this.attackCooldown - dt);
    this.rangedCooldown = Math.max(0, this.rangedCooldown - dt);
    this.hitFlash = Math.max(0, this.hitFlash - dt);
    this.poise = Math.min(this.maxPoise, this.poise + dt * 9);
    if (this.alertIcon.visible && this.stateTime > 1.1) this.alertIcon.visible = false;

    const dist = Math.hypot(player.pos.x - this.pos.x, player.pos.z - this.pos.z);
    const dx = player.pos.x - this.pos.x, dz = player.pos.z - this.pos.z;
    const angToPlayer = Math.atan2(dx, dz);
    this.distToPlayer = dist;

    if (player.dead) { this.aggro = false; if (this.state !== 'return' && this.state !== 'patrol') this.setState('return'); }

    // detection
    if (!this.aggro && !player.dead && this.state !== 'stagger') {
      const facing = Math.cos(angleDelta(this.yaw, angToPlayer));
      const heard = player.sprinting && dist < 24;
      if ((dist < this.def.aggro && (dist < 4.5 || facing > .15 || player.sprinting)) || heard) {
        this.alert(player);
      }
    }
    this.alertLevel = this.aggro ? 1 : 0;

    switch (this.state) {
      case 'patrol': this.updatePatrol(dt); break;
      case 'idle': this.updateIdle(dt); break;
      case 'chase': this.updateChase(dt, player, dist, angToPlayer); break;
      case 'attack': this.updateAttack(dt, player, dist, angToPlayer); break;
      case 'stagger': this.updateStagger(dt); break;
      case 'return': this.updateReturn(dt); break;
    }

    // physics / collisions / ground
    this.pos.x += this.vel.x * dt;
    this.pos.z += this.vel.z * dt;
    this.vel.x = damp(this.vel.x, 0, 6, dt); this.vel.z = damp(this.vel.z, 0, 6, dt);
    this.resolveCollisions();
    this.pos.y = heightAt(this.pos.x, this.pos.z);
    this.root.position.copy(this.pos);
    this.root.rotation.y = this.yaw;
    this.updateAnimation(dt);
  }

  setState(s) { this.state = s; this.stateTime = 0; }

  alert(player) {
    if (this.aggro) return;
    this.aggro = true;
    this.setState('chase');
    this.alertIcon.visible = true;
    this.stateTime = 0;
    this.game.audio.roar?.(); // maybe not for all; use soft sting
    if (!this.def.elite) this.game.audio.tone?.({ freq: 180, type: 'triangle', dur: .25, gain: .025 });
    else this.game.audio.roar();
    if (this.isElite) this.game.showEliteBar(this);
    // alert nearby allies
    for (const e of this.game.enemies) {
      if (e === this || !e.alive || e.aggro) continue;
      if (e.pos.distanceTo(this.pos) < 12) { e.aggro = true; e.setState('chase'); }
    }
  }

  updatePatrol(dt) {
    if (this.patrolWait > 0) { this.patrolWait -= dt; return; }
    const dx = this.patrolTarget.x - this.pos.x, dz = this.patrolTarget.z - this.pos.z;
    const d = Math.hypot(dx, dz);
    if (d < .7) {
      this.patrolWait = rand(1.2, 3.4);
      this.patrolTarget = this.pickPatrol();
      return;
    }
    const sp = this.def.speed * .34;
    this.vel.x = (dx / d) * sp; this.vel.z = (dz / d) * sp;
    this.yaw = dampAngle(this.yaw, Math.atan2(dx, dz), 5, dt);
  }
  updateIdle(dt) {
    if (this.stateTime > 2) { this.setState('patrol'); this.patrolTarget = this.pickPatrol(); }
  }
  updateChase(dt, player, dist, angToPlayer) {
    const leashD = Math.hypot(this.pos.x - this.spawn.x, this.pos.z - this.spawn.z);
    if (leashD > this.leash || player.dead) { this.aggro = false; this.setState('return'); if (this.isElite) this.game.hideEliteBar(); return; }
    if (this.def.ranged) { this.updateArcherChase(dt, player, dist, angToPlayer); return; }
    this.yaw = dampAngle(this.yaw, angToPlayer, 6, dt);
    const attackRange = this.def.attackRange;
    if (dist > attackRange * .9) {
      const sp = this.def.speed * (dist > 8 ? 1.15 : 1);
      this.vel.x = (Math.sin(angToPlayer) * sp);
      this.vel.z = (Math.cos(angToPlayer) * sp);
    } else {
      // circle strafe / wait for opening
      const side = Math.sin(this.game.time * .8 + this.spawn.x) > 0 ? 1 : -1;
      this.vel.x = Math.cos(angToPlayer) * this.def.speed * .28 * side;
      this.vel.z = -Math.sin(angToPlayer) * this.def.speed * .28 * side;
      if (this.attackCooldown <= 0 && this.game.canEnemyAttack(this)) this.startAttack();
    }
    // separation
    this.separation();
  }
  updateArcherChase(dt, player, dist, angToPlayer) {
    this.yaw = dampAngle(this.yaw, angToPlayer, 6, dt);
    if (dist < 5) {
      this.vel.x = -Math.sin(angToPlayer) * this.def.speed; this.vel.z = -Math.cos(angToPlayer) * this.def.speed;
    } else if (dist > 16) {
      this.vel.x = Math.sin(angToPlayer) * this.def.speed; this.vel.z = Math.cos(angToPlayer) * this.def.speed;
    } else if (this.rangedCooldown <= 0 && this.game.canEnemyAttack(this)) {
      this.startAttack('ranged');
    }
    this.separation();
  }
  separation() {
    for (const e of this.game.enemies) {
      if (e === this || !e.alive) continue;
      const dx = this.pos.x - e.pos.x, dz = this.pos.z - e.pos.z;
      const d = Math.hypot(dx, dz);
      if (d < 1.3 && d > .01) { this.vel.x += dx / d * .8; this.vel.z += dz / d * .8; }
    }
  }

  startAttack(kind = 'melee') {
    this.state = 'attack'; this.stateTime = 0;
    this.attackCooldown = this.def.attackCooldown + rand(0, .5);
    const ranged = kind === 'ranged';
    const elite = this.def.elite;
    const atk = {
      kind,
      windup: ranged ? 1.15 : (elite ? .85 : (this.defId === 'knight' ? .9 : this.defId === 'goblin' ? .35 : .55)),
      active: ranged ? .1 : .18,
      recover: ranged ? .7 : (elite ? .75 : .55),
      damage: this.def.damage * (elite ? 1.15 : 1),
      range: ranged ? 30 : (elite ? 4.2 : this.def.attackRange + .55),
      cone: ranged ? .9 : (elite ? .95 : .72),
      fired: false,
      lunging: this.defId === 'hound' || (elite && kind === 'melee'),
    };
    if (elite && chance(.4)) { atk.kind = 'aoe'; atk.windup = 1.0; atk.damage = this.def.damage * 1.3; atk.range = 5.0; }
    this.attack = atk;
    this.faceLocked = this.yaw;
    this.game.audio.swing?.(elite);
    this.telegraph.visible = true;
    this.telegraph.material.opacity = 0;
    this.telegraph.scale.setScalar(.6);
    this.alertIcon.visible = false;
  }

  updateAttack(dt, player, dist, angToPlayer) {
    const a = this.attack;
    if (!a) { this.setState('chase'); return; }
    const t = this.stateTime;
    if (a.kind !== 'ranged') this.yaw = dampAngle(this.yaw, angToPlayer, 3.2, dt);
    // telegraph build
    if (t < a.windup) {
      const p = t / a.windup;
      this.telegraph.material.opacity = .18 + p * .55;
      const sc = .5 + p * (a.range / 1.4);
      this.telegraph.scale.setScalar(sc);
      this.telegraph.material.color.setHex(a.kind === 'aoe' ? 0xb44cff : 0xff4a2a);
      if (a.lunging) this.attackLunge = true;
    } else if (!a.fired) {
      a.fired = true;
      this.telegraph.material.opacity = 0;
      this.telegraph.visible = false;
      if (a.kind === 'ranged') {
        this.game.enemyFireArrow(this, player);
      } else if (a.kind === 'aoe') {
        this.game.enemyAoe(this, a);
      } else {
        const d = Math.hypot(player.pos.x - this.pos.x, player.pos.z - this.pos.z);
        const facing = Math.cos(angleDelta(this.yaw, Math.atan2(player.pos.x - this.pos.x, player.pos.z - this.pos.z)));
        if (d <= a.range + .6 && facing > (a.cone - .5) && !player.dead) {
          player.takeDamage(a.damage, this.pos, { source: this });
        }
        if (a.lunging) {
          const lunge = this.defId === 'hound' ? 7 : 4;
          this.vel.x += Math.sin(this.yaw) * lunge; this.vel.z += Math.cos(this.yaw) * lunge;
        }
      }
      this.game.spawnAttackArc(this, a.range, a.kind === 'aoe' ? 0xb44cff : 0xff6a3a);
    }
    if (t > a.windup + a.active + a.recover) {
      this.attack = null;
      this.setState('chase');
    }
  }

  updateStagger(dt) {
    if (this.stateTime > this.staggerTimer) {
      this.canBeCrit = false;
      this.setState('chase');
    }
  }
  updateReturn(dt) {
    const dx = this.spawn.x - this.pos.x, dz = this.spawn.z - this.pos.z;
    const d = Math.hypot(dx, dz);
    if (d < .8) {
      this.health = this.maxHealth; this.poise = this.maxPoise;
      this.setState('patrol'); this.patrolTarget = this.pickPatrol(); this.patrolWait = rand(.5, 2);
      this.root.visible = true;
      return;
    }
    const sp = this.def.speed * 1.3;
    this.vel.x = (dx / d) * sp; this.vel.z = (dz / d) * sp;
    this.yaw = dampAngle(this.yaw, Math.atan2(dx, dz), 8, dt);
  }

  resolveCollisions() {
    for (const c of this.game.world.colliders) {
      const dx = this.pos.x - c.x, dz = this.pos.z - c.z;
      const d = Math.hypot(dx, dz), min = this.radius + c.r;
      if (d < min && d > .001) { const p = min - d; this.pos.x += dx / d * p; this.pos.z += dz / d * p; }
    }
    // don't stack on player
    const pl = this.game.player;
    if (pl && !pl.dead) {
      const dx = this.pos.x - pl.pos.x, dz = this.pos.z - pl.pos.z;
      const d = Math.hypot(dx, dz), min = this.radius + .42;
      if (d < min && d > .001) { const p = min - d; this.pos.x += dx / d * p; this.pos.z += dz / d * p; }
    }
  }

  /* ==================== COMBAT ==================== */
  takeDamage(amount, fromPos, opts = {}) {
    if (!this.alive) return;
    let dmg = amount;
    const dx = fromPos ? this.pos.x - fromPos.x : 0;
    const dz = fromPos ? this.pos.z - fromPos.z : 0;
    const facing = Math.sin(this.yaw) * dx + Math.cos(this.yaw) * dz;
    const front = facing > -.1;
    if (this.def.shield && front && this.state !== 'stagger' && this.state !== 'attack' && !opts.critical) {
      dmg *= .4;
      this.game.spawnSparkBurst(this.pos.clone().add(new THREE.Vector3(0, 1.1, 0)), 8);
      this.game.audio.block();
      this.game.floatText(this.pos, 'GUARD', 'block');
    }
    if (opts.critical) dmg *= 1;
    this.health -= dmg;
    this.poise -= opts.poise ?? 18;
    this.hitFlash = .18;
    this.aggro = true;
    if (this.state === 'patrol' || this.state === 'idle') { this.alert(this.game.player); }
    this.game.floatText(this.pos, Math.round(dmg), 'enemy');
    this.game.audio.hit(this.def.armorType === 'metal');
    this.game.spawnBloodBurst(this.pos.clone().add(new THREE.Vector3(0, .9 * (this.def.scale || 1), 0)), Math.min(14, 4 + dmg * .15), this.def.armorType === 'metal' ? 0xffd27a : 0x7a1f1f);
    if (!opts.critical) this.game.shake(.1);
    // knockback
    if (!opts.noKnock && dmg > 20) {
      const l = Math.hypot(dx, dz) || 1;
      this.vel.x += dx / l * 2.2; this.vel.z += dz / l * 2.2;
    }
    if (this.isElite) this.game.showEliteBar(this);
    if (this.health <= 0) { this.die(opts); return; }
    if (this.poise <= 0) {
      this.poise = this.maxPoise;
      this.stagger(opts.critical ? 2.2 : 1.35, opts.source);
    }
  }

  stagger(duration, source) {
    if (!this.alive) return;
    this.setState('stagger');
    this.staggerTimer = duration;
    this.canBeCrit = true;
    this.attack = null;
    this.telegraph.visible = false;
    this.vel.set(0, 0, 0);
    this.game.floatText(this.pos, 'STAGGERED', 'crit');
    if (this.isElite) this.game.showEliteBar(this);
    this.game.audio.parry?.();
  }

  die(opts = {}) {
    if (!this.alive) return;
    this.alive = false;
    this.state = 'dead';
    this.deathTimer = 0;
    this.root.rotation.y = this.yaw;
    this.telegraph.visible = false;
    this.attack = null;
    this.game.audio.hit(false);
    this.game.audio.tone?.({ freq: 120, type: 'sawtooth', dur: .8, gain: .06, slide: 40 });
    this.game.spawnBloodBurst(this.pos.clone().add(new THREE.Vector3(0, .8, 0)), 22, 0x6e1515);
    this.game.spawnSoulBurst(this.pos.clone().add(new THREE.Vector3(0, .8, 0)), this.def.elite ? 36 : 14);
    const motes = Math.round(this.def.motes * rand(.85, 1.25));
    this.game.addMotes(motes, this.pos);
    this.game.addXP(this.def.xp);
    this.game.onEnemyKilled(this);
    if (this.isElite) { this.game.hideEliteBar(); this.game.showBanner('ELITE VANQUISHED', 'The Briar Warden has fallen.'); }
    // loot
    if (this.defId === 'briarWarden') this.game.giveLoot('spear', 'Briar Spear', this.pos);
    else if (this.defId === 'goblin' && chance(.09)) this.game.giveLoot('dagger', 'Glimmer Dagger', this.pos);
    else if (this.defId === 'archer' && chance(.12)) this.game.giveLoot('bow', 'Weeping Shortbow', this.pos);
    else if (this.defId === 'knight' && chance(.2)) this.game.giveLoot('knight', 'Rotten Knight Plate', this.pos, 'armor');
    else if (chance(.12)) this.game.giveItem('emberBomb', 1);
    // remove after animation
    setTimeout(() => {
      if (this.root && this.root.parent) this.root.parent.remove(this.root);
    }, 5200);
  }

  updateDeath(dt) {
    this.deathTimer += dt;
    const p = Math.min(1, this.deathTimer / .5);
    if (this.def.quadruped) this.root.rotation.z = lerp(0, 1.2, p);
    else this.root.rotation.x = lerp(0, -1.35, p);
    if (this.deathTimer > 3.8) this.root.position.y -= dt * .4;
  }

  /* ==================== ANIMATION ==================== */
  updateAnimation(dt) {
    const t = this.game.time;
    const speed = Math.hypot(this.vel.x, this.vel.z);
    const moving = speed > .25;
    const cycle = t * (5 + speed * 1.5) + this.spawn.x;
    const amount = clamp(speed / (this.def.speed || 1), 0, 1);
    this.walk += dt * (moving ? 6 + speed : 2);
    const sw = Math.sin(cycle) * (.45 + amount * .35);

    if (this.state === 'stagger') {
      this.body.rotation.x = damp(this.body.rotation.x, -.55, 10, dt);
      this.body.rotation.z = damp(this.body.rotation.z, .2, 10, dt);
      if (this.armL) { this.armL.sh.rotation.x = damp(this.armL.sh.rotation.x, .6, 8, dt); this.armR.sh.rotation.x = damp(this.armR.sh.rotation.x, .6, 8, dt); }
      if (this.legL) { this.legL.hip.rotation.x = damp(this.legL.hip.rotation.x, .3, 8, dt); this.legR.hip.rotation.x = damp(this.legR.hip.rotation.x, -.3, 8, dt); }
      return;
    }
    this.body.rotation.x = damp(this.body.rotation.x, 0, 8, dt);
    this.body.rotation.z = damp(this.body.rotation.z, 0, 8, dt);

    if (this.def.quadruped) {
      const legs = [this.legL, this.legR, this.legL2, this.legR2];
      legs.forEach((l, i) => {
        if (!l) return;
        const phase = sw * (i % 2 === 0 ? 1 : -1) * (i > 1 ? -1 : 1);
        l.hip.rotation.x = damp(l.hip.rotation.x, phase, 14, dt);
        l.knee.rotation.x = damp(l.knee.rotation.x, Math.max(0, -phase) * .8, 14, dt);
      });
      this.head.rotation.x = damp(this.head.rotation.x, this.state === 'attack' ? -.35 : Math.sin(t * 2) * .06, 8, dt);
      const jaw = this.head.getObjectByName('jaw');
      if (jaw) jaw.rotation.x = this.state === 'attack' ? damp(jaw.rotation.x, .55, 12, dt) : damp(jaw.rotation.x, 0, 8, dt);
      return;
    }

    // humanoid walk
    if (this.legL) {
      this.legL.hip.rotation.x = damp(this.legL.hip.rotation.x, sw, 12, dt);
      this.legR.hip.rotation.x = damp(this.legR.hip.rotation.x, -sw, 12, dt);
      this.legL.knee.rotation.x = damp(this.legL.knee.rotation.x, Math.max(0, -sw) * 1.1, 12, dt);
      this.legR.knee.rotation.x = damp(this.legR.knee.rotation.x, Math.max(0, sw) * 1.1, 12, dt);
    }
    if (this.armL) {
      if (this.state === 'attack' && this.attack) {
        const a = this.attack;
        const t2 = this.stateTime;
        const wind = a.windup;
        if (t2 < wind) {
          this.armR.sh.rotation.x = damp(this.armR.sh.rotation.x, -2.5, 9, dt);
          this.armR.sh.rotation.z = damp(this.armR.sh.rotation.z, -.4, 9, dt);
          this.torso.rotation.x = damp(this.torso.rotation.x, -.18, 8, dt);
          this.torso.rotation.y = damp(this.torso.rotation.y, .35, 8, dt);
          if (this.defId === 'archer') {
            this.armL.sh.rotation.x = damp(this.armL.sh.rotation.x, -1.5, 9, dt);
            this.armR.el.rotation.x = damp(this.armR.el.rotation.x, -.6, 9, dt);
          }
        } else {
          this.armR.sh.rotation.x = damp(this.armR.sh.rotation.x, .7, 18, dt);
          this.armR.sh.rotation.z = damp(this.armR.sh.rotation.z, .5, 18, dt);
          this.torso.rotation.x = damp(this.torso.rotation.x, .3, 14, dt);
          this.torso.rotation.y = damp(this.torso.rotation.y, -.4, 14, dt);
        }
        this.armL.sh.rotation.x = damp(this.armL.sh.rotation.x, -.4, 8, dt);
      } else {
        this.armL.sh.rotation.x = damp(this.armL.sh.rotation.x, -sw * .6, 10, dt);
        this.armR.sh.rotation.x = damp(this.armR.sh.rotation.x, sw * .5 - .18, 10, dt);
        this.armR.sh.rotation.z = damp(this.armR.sh.rotation.z, -.18, 8, dt);
        this.torso.rotation.x = damp(this.torso.rotation.x, 0, 6, dt);
        this.torso.rotation.y = damp(this.torso.rotation.y, -sw * .15, 8, dt);
      }
    }
    if (this.head) this.head.rotation.y = damp(this.head.rotation.y, Math.sin(t * .7 + this.spawn.z) * .15, 5, dt);
    this.body.position.y = moving ? Math.abs(Math.cos(cycle)) * .045 * amount : Math.sin(t * 2 + this.spawn.x) * .015;
    this.updateFlash();
  }

  updateFlash() {
    for (const m of this.mats) {
      if (this.hitFlash > 0) { m.emissive?.setHex(0x8a1a10); if (m.emissiveIntensity !== undefined) m.emissiveIntensity = .55; }
      else { m.emissive?.setHex(0x000000); if (m.emissiveIntensity !== undefined) m.emissiveIntensity = 0; }
    }
  }

  dispose() {
    if (this.root?.parent) this.root.parent.remove(this.root);
    if (this.barEl?.parentNode) this.barEl.parentNode.removeChild(this.barEl);
  }
}

import * as THREE from 'three';
import { clamp, lerp, damp, dampAngle, angleDelta, material, emissive, makeGlowSprite, rand, chance, choose } from '../core/utils.js';
import { heightAt } from '../world/terrain.js';
import { ARENA } from '../world/terrain.js';

export class HollowWoodsman {
  constructor(game) {
    this.game = game;
    this.name = 'THE HOLLOW WOODSMAN';
    this.sub = 'Keeper of the First Grove';
    this.center = new THREE.Vector3(ARENA.x, 0, ARENA.z);
    this.arenaRadius = ARENA.r - 1;
    this.spawn = new THREE.Vector3(0, 0, -111);
    this.pos = this.spawn.clone();
    this.yaw = Math.PI; // facing south toward the player
    this.radius = 2.0;
    this.maxHealth = 1500;
    this.health = this.maxHealth;
    this.maxPoise = 260;
    this.poise = this.maxPoise;
    this.active = false;
    this.dead = false;
    this.isBoss = true;
    this.state = 'dormant';
    this.stateTime = 0;
    this.cooldown = 2.5;
    this.phase = 1;
    this.attack = null;
    this.introActive = false;
    this.vel = new THREE.Vector3();
    this.hitFlash = 0;
    this.poiseBuildup = 0;
    this.staggerTimer = 0;
    this.deathTimer = 0;
    this.deathCinematic = false;
    this.alerted = false;
    this.rootHitOnce = false;
    this.armorType = 'bark';
    this.barEl = null;
    this.buildModel();
    this.root.position.copy(this.pos);
    this.scene = game.scene;
    this.scene.add(this.root);
  }

  buildModel() {
    const root = new THREE.Group();
    this.root = root;
    const body = new THREE.Group(); root.add(body); this.body = body;
    this.mats = [];
    const mk = (c, o = {}) => { const m = material(c, o); this.mats.push(m); return m; };
    const flannel = mk(0x6a2f2f, { roughness: .95 });
    const flannel2 = mk(0x4a2424, { roughness: .95 });
    const denim = mk(0x2e3440, { roughness: 1 });
    const leather = mk(0x4b3524, { roughness: .95 });
    const skin = mk(0x9b8b6d, { roughness: 1 });
    const bark = mk(0x4b3a27, { roughness: 1 });
    const bark2 = mk(0x3a2d1e, { roughness: 1 });
    const steel = mk(0x6c7075, { metalness: .7, roughness: .42 });
    const darkSteel = mk(0x3e4145, { metalness: .65, roughness: .5 });
    const leaf = mk(0x476b39, { roughness: 1 });
    const leaf2 = mk(0x5d7f45, { roughness: 1 });
    const eyeM = emissive(0xffb02e, 2.3);
    const heartM = emissive(0xff9a2e, 1.8);
    this.eyeMats = [eyeM, heartM];

    // legs
    const mkLeg = (side) => {
      const hip = new THREE.Group(); hip.position.set(side * .75, 3.0, 0); body.add(hip);
      const thigh = new THREE.Mesh(new THREE.CylinderGeometry(.46, .38, 1.55, 7), denim); thigh.position.y = -.75; hip.add(thigh);
      const knee = new THREE.Group(); knee.position.y = -1.5; hip.add(knee);
      const shin = new THREE.Mesh(new THREE.CylinderGeometry(.35, .3, 1.4, 7), denim); shin.position.y = -.7; knee.add(shin);
      const boot = new THREE.Mesh(new THREE.BoxGeometry(.75, .5, 1.25), leather); boot.position.set(0, -1.45, .28); knee.add(boot);
      const toe = new THREE.Mesh(new THREE.BoxGeometry(.72, .22, .35), darkSteel); toe.position.set(0, -1.6, .85); knee.add(toe);
      return { hip, knee };
    };
    this.legL = mkLeg(-1); this.legR = mkLeg(1);

    // torso
    const torso = new THREE.Group(); torso.position.y = 3.4; body.add(torso); this.torso = torso;
    const chest = new THREE.Mesh(new THREE.BoxGeometry(2.55, 2.5, 1.35), flannel); chest.position.y = .9; torso.add(chest);
    const belly = new THREE.Mesh(new THREE.BoxGeometry(2.2, .8, 1.2), flannel2); belly.position.y = -.35; torso.add(belly);
    const apron = new THREE.Mesh(new THREE.BoxGeometry(1.8, 1.9, .08), leather); apron.position.set(0, .1, .7); torso.add(apron);
    const belt = new THREE.Mesh(new THREE.BoxGeometry(2.45, .35, 1.32), leather); belt.position.y = -.55; torso.add(belt);
    const buckle = new THREE.Mesh(new THREE.BoxGeometry(.45, .45, .1), steel); buckle.position.set(0, -.55, .68); torso.add(buckle);
    // shoulder pads of bark
    for (const sx of [-1.35, 1.35]) {
      const pad = new THREE.Mesh(new THREE.DodecahedronGeometry(.48, 0), bark); pad.position.set(sx, 1.7, 0); pad.scale.set(1.1, .7, 1); torso.add(pad);
      for (let i = 0; i < 3; i++) { const sp = new THREE.Mesh(new THREE.ConeGeometry(.1, .5, 4), bark2); sp.position.set(sx + rand(-.25, .25), 1.95, rand(-.2, .2)); sp.rotation.z = rand(-.6, .6); torso.add(sp); }
    }
    // neck/head
    const head = new THREE.Group(); head.position.y = 2.35; torso.add(head); this.head = head;
    const skull = new THREE.Mesh(new THREE.BoxGeometry(.9, .9, .85), skin); head.add(skull);
    const brow = new THREE.Mesh(new THREE.BoxGeometry(.98, .2, .12), bark2); brow.position.set(0, .15, .44); head.add(brow);
    for (const ex of [-.22, .22]) {
      const eye = new THREE.Mesh(new THREE.SphereGeometry(.08, 6, 5), eyeM); eye.position.set(ex, .04, .44); head.add(eye);
      const gl = makeGlowSprite(0xffb02e, .7); gl.position.set(ex, .04, .5); head.add(gl); this.eyeMats.push(gl.material);
    }
    // beard of roots
    for (let i = 0; i < 9; i++) {
      const b = new THREE.Mesh(new THREE.ConeGeometry(.07, rand(.5, 1.0), 4), bark); b.position.set(rand(-.35, .35), -.45, rand(.25, .45)); b.rotation.x = Math.PI + rand(-.2, .2); head.add(b);
    }
    // huge antler-like branches
    for (const sx of [-1, 1]) {
      const ant = new THREE.Mesh(new THREE.CylinderGeometry(.06, .13, 1.5, 5), bark); ant.position.set(sx * .35, .65, 0); ant.rotation.z = sx * -.55; head.add(ant);
      const ant2 = new THREE.Mesh(new THREE.CylinderGeometry(.04, .07, .9, 4), bark); ant2.position.set(sx * .8, 1.15, 0); ant2.rotation.z = sx * .25; head.add(ant2);
    }
    // tree growing through chest
    const tree = new THREE.Group(); tree.position.set(.15, 1.2, -.1); torso.add(tree); this.tree = tree;
    const trunk = new THREE.Mesh(new THREE.CylinderGeometry(.3, .5, 3.0, 7), bark); trunk.position.y = 1.2; trunk.rotation.z = -.14; tree.add(trunk);
    for (let i = 0; i < 7; i++) {
      const a = (i / 7) * Math.PI * 2;
      const br = new THREE.Mesh(new THREE.CylinderGeometry(.07, .14, 1.7, 5), bark2);
      br.position.set(Math.cos(a) * .45, 2.2 + rand(-.4, .7), Math.sin(a) * .45);
      br.rotation.set(Math.cos(a) * .9, 0, Math.sin(a) * -.9);
      tree.add(br);
    }
    for (let i = 0; i < 9; i++) {
      const lf = new THREE.Mesh(new THREE.IcosahedronGeometry(rand(.35, .7), 0), chance(.5) ? leaf : leaf2);
      lf.position.set(rand(-1.4, 1.4), 2.4 + rand(0, 1.4), rand(-1.2, 1.2)); tree.add(lf);
    }
    const heart = new THREE.Mesh(new THREE.OctahedronGeometry(.26), heartM); heart.position.set(.15, 1.35, .35); torso.add(heart); this.heart = heart;
    const heartGlow = makeGlowSprite(0xff8a2e, 4.5); heartGlow.position.copy(heart.position); torso.add(heartGlow); this.heartGlow = heartGlow;

    // arms
    const mkArm = (side) => {
      const sh = new THREE.Group(); sh.position.set(side * 1.45, 1.55, 0); torso.add(sh);
      const upper = new THREE.Mesh(new THREE.CylinderGeometry(.3, .27, 1.45, 7), flannel); upper.position.y = -.72; sh.add(upper);
      const el = new THREE.Group(); el.position.y = -1.45; sh.add(el);
      const fore = new THREE.Mesh(new THREE.CylinderGeometry(.26, .23, 1.35, 7), skin); fore.position.y = -.68; el.add(fore);
      const hand = new THREE.Mesh(new THREE.SphereGeometry(.32, 8, 7), skin); hand.position.y = -1.4; el.add(hand);
      return { sh, el, hand };
    };
    this.armL = mkArm(-1); this.armR = mkArm(1);
    // axe mount
    const wm = new THREE.Group(); wm.position.y = -1.4; this.armR.el.add(wm); this.weaponMount = wm;
    const handle = new THREE.Mesh(new THREE.CylinderGeometry(.12, .17, 5.6, 7), bark); handle.position.y = 1.2; wm.add(handle);
    const axeHead = new THREE.Mesh(new THREE.BoxGeometry(2.4, 1.6, .3), darkSteel); axeHead.position.set(1.0, 3.6, 0); wm.add(axeHead);
    const blade = new THREE.Mesh(new THREE.BoxGeometry(.5, 1.9, .16), steel); blade.position.set(2.15, 3.6, 0); wm.add(blade);
    const beard = new THREE.Mesh(new THREE.BoxGeometry(.7, 1.9, .18), steel); beard.position.set(2.0, 3.6, 0); beard.rotation.z = .3; wm.add(beard);
    const rune = new THREE.Mesh(new THREE.TorusGeometry(.45, .05, 4, 10), heartM); rune.position.set(1.1, 3.6, .18); wm.add(rune);
    wm.rotation.set(-.4, 0, -.35);

    // roots around feet
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2;
      const r = new THREE.Mesh(new THREE.CylinderGeometry(.08, .2, rand(1.2, 2.2), 4), bark2);
      r.position.set(Math.cos(a) * 1.1, .1, Math.sin(a) * 1.1); r.rotation.set(Math.PI / 2, a, 0); root.add(r);
    }

    // aura (phase 2)
    const aura = new THREE.Mesh(new THREE.SphereGeometry(3.4, 16, 12), new THREE.MeshBasicMaterial({ color: 0xff7a2e, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, side: THREE.BackSide, depthWrite: false }));
    aura.position.y = 3.4; root.add(aura); this.aura = aura;
    const glow = makeGlowSprite(0xff6a2e, 12); glow.position.y = 3.6; glow.material.opacity = .12; root.add(glow); this.auraGlow = glow;

    // telegraph ring
    const tg = new THREE.Mesh(new THREE.RingGeometry(.8, 1.0, 32), new THREE.MeshBasicMaterial({ color: 0xff4a2a, transparent: true, opacity: 0, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending }));
    tg.rotation.x = -Math.PI / 2; tg.position.y = .06; root.add(tg); this.telegraph = tg;

    root.traverse(o => { if (o.isMesh && o.material) o.frustumCulled = false; });
  }

  /* ================= INTRO / ACTIVATION ================= */
  beginIntro() {
    this.introActive = true;
    this.state = 'intro';
    this.stateTime = 0;
    this.alerted = true;
    this.game.audio.roar();
    this.game.showBossBar(this);
  }
  activate() {
    this.active = true;
    this.introActive = false;
    this.state = 'idle';
    this.stateTime = 0;
    this.cooldown = 1.6;
    this.game.audio.setTheme('boss');
  }

  /* ================= UPDATE ================= */
  update(dt, player) {
    if (this.dead) { this.updateDeath(dt); return; }
    this.stateTime += dt;
    this.hitFlash = Math.max(0, this.hitFlash - dt);
    this.poise = Math.min(this.maxPoise, this.poise + dt * 7);

    if (!this.active) {
      this.idleAnim(dt);
      return;
    }
    if (this.introActive) {
      this.introAnim(dt);
      return;
    }
    if (this.state === 'phaseChange') {
      this.phaseChangeUpdate(dt);
      return;
    }
    if (this.state === 'stagger') {
      this.staggerTimer -= dt;
      this.body.rotation.x = damp(this.body.rotation.x, -.55, 8, dt);
      this.body.rotation.z = damp(this.body.rotation.z, .18, 8, dt);
      if (this.staggerTimer <= 0) { this.state = 'idle'; this.body.rotation.x = 0; this.body.rotation.z = 0; this.poise = this.maxPoise; this.game.hideContextual(); }
      this.root.position.copy(this.pos);
      return;
    }
    if (this.state === 'dead') return;

    const dx = player.pos.x - this.pos.x, dz = player.pos.z - this.pos.z;
    const dist = Math.hypot(dx, dz);
    const ang = Math.atan2(dx, dz);
    this.yaw = dampAngle(this.yaw, ang, 2.6, dt);
    this.cooldown = Math.max(0, this.cooldown - dt);
    this.dist = dist;

    if (this.attack) { this.updateAttack(dt, player, dist, ang); }
    else if (this.state !== 'charge') {
      if (this.attackCooldown !== undefined && this.state === 'attack') return;
      // reposition
      if (dist > 7.5) {
        const sp = (this.phase === 2 ? 2.6 : 1.8);
        this.vel.x = Math.sin(ang) * sp;
        this.vel.z = Math.cos(ang) * sp;
      } else if (dist < 4.2) {
        this.vel.x = -Math.sin(ang) * 1.1;
        this.vel.z = -Math.cos(ang) * 1.1;
      } else {
        const side = Math.sin(this.game.time * .6) > 0 ? 1 : -1;
        this.vel.x = Math.cos(ang) * .8 * side;
        this.vel.z = -Math.sin(ang) * .8 * side;
      }
      if (this.cooldown <= 0 && dist < 18) this.chooseAttack(dist);
    }

    // movement
    this.pos.x += this.vel.x * dt;
    this.pos.z += this.vel.z * dt;
    this.vel.x = damp(this.vel.x, 0, 4, dt);
    this.vel.z = damp(this.vel.z, 0, 4, dt);
    // arena clamp
    const cdx = this.pos.x - this.center.x, cdz = this.pos.z - this.center.z;
    const cd = Math.hypot(cdx, cdz);
    if (cd > this.arenaRadius - 2) { const k = (this.arenaRadius - 2) / cd; this.pos.x = this.center.x + cdx * k; this.pos.z = this.center.z + cdz * k; }
    this.pos.y = heightAt(this.pos.x, this.pos.z);
    this.root.position.copy(this.pos);
    this.root.rotation.y = this.yaw;
    this.walkAnim(dt, dist);
    this.updateAura(dt);

    if (this.health <= this.maxHealth * .5 && this.phase === 1) this.enterPhase2();
  }

  chooseAttack(dist) {
    const r = Math.random();
    if (this.phase === 1) {
      if (dist < 7) this.startAttack(r < .55 ? 'sweep' : 'slam');
      else this.startAttack(r < .6 ? 'charge' : 'sweep');
    } else {
      if (dist < 7) this.startAttack(r < .32 ? 'sweep' : r < .58 ? 'slam' : r < .8 ? 'roots' : 'summon');
      else this.startAttack(r < .42 ? 'charge' : r < .72 ? 'roots' : 'slam');
    }
  }

  startAttack(kind) {
    this.state = 'attack';
    this.attack = { kind, t: 0, hit: false, phase: 'windup' };
    this.attack.t = 0;
    const wind = {
      sweep: 1.05, slam: 1.25, charge: .8, roots: 1.15, summon: 1.1,
    }[kind] || 1;
    this.attack.windup = wind; this.attack.recover = kind === 'charge' ? .9 : .85;
    this.attack.range = kind === 'sweep' ? 8.2 : kind === 'slam' ? 6.8 : kind === 'roots' ? 30 : 8;
    this.attack.damage = { sweep: 34, slam: 42, charge: 30, roots: 27, summon: 0 }[kind] || 30;
    this.attack.kind = kind;
    this.attack.hit = false;
    this.cooldown = kind === 'summon' ? 5 : (this.phase === 2 ? 1.8 : 2.6);
    this.game.audio.swing(true);
    this.telegraph.visible = true;
    this.telegraph.material.opacity = 0;
    if (kind === 'roots' || kind === 'summon') this.telegraph.material.color.setHex(0x9c5cff);
    else this.telegraph.material.color.setHex(0xff4a2a);
    this.game.bossTelegraph(this, kind);
  }

  updateAttack(dt, player, dist, ang) {
    const a = this.attack;
    if (!a) return;
    a.t += dt;
    const t = a.t;
    if (t < a.windup) {
      const p = t / a.windup;
      this.telegraph.material.opacity = .2 + p * .5;
      this.telegraph.scale.setScalar(.8 + p * 8);
      this.telegraph.rotation.z += dt * (a.kind === 'roots' ? 2 : .6);
      // face player slowly during windup
      this.yaw = dampAngle(this.yaw, ang, 1.7, dt);
      this.windupAnim(dt, a, p);
    } else if (!a.hit) {
      a.hit = true;
      this.telegraph.visible = false;
      this.impact(a, player);
      this.impactAnim(a);
    } else if (t > a.windup + a.recover) {
      this.attack = null;
      this.state = 'idle';
      this.body.rotation.x = 0;
      this.body.rotation.z = 0;
      this.game.hideContextual();
    }
    if (a.kind === 'charge') {
      // charge state handled through velocity
      if (t > a.windup && t < a.windup + .85) {
        const sp = this.phase === 2 ? 14 : 10;
        this.vel.x = Math.sin(this.yaw) * sp;
        this.vel.z = Math.cos(this.yaw) * sp;
        if (!a.chargeHit && dist < 4.6) {
          a.chargeHit = true;
          player.takeDamage(a.damage, this.pos, { source: this });
          this.game.shake(.35);
        }
      }
    }
    this.root.position.copy(this.pos);
    this.root.rotation.y = this.yaw;
  }

  impact(a, player) {
    const dx = player.pos.x - this.pos.x, dz = player.pos.z - this.pos.z;
    const dist = Math.hypot(dx, dz);
    const facing = Math.cos(angleDelta(this.yaw, Math.atan2(dx, dz)));
    this.game.shake(a.kind === 'slam' ? .6 : .35);
    this.game.audio.hit(true);
    if (a.kind === 'sweep') {
      this.game.bossArcEffect(this.pos, this.yaw, 8, 0xff4a2a);
      if (dist < 8.2 && facing > .1) player.takeDamage(a.damage, this.pos, { source: this });
    } else if (a.kind === 'slam') {
      this.game.bossShockwave(this.pos, 0);
      if (dist < 7) player.takeDamage(a.damage, this.pos, { source: this });
      this.game.bossRootRing(this.pos, 0xff6a2a);
    } else if (a.kind === 'charge') {
      this.game.shake(.3);
    } else if (a.kind === 'roots') {
      this.game.bossRootEruption(this.pos, player.pos, this.phase === 2 ? 5 : 3, a.damage);
    } else if (a.kind === 'summon') {
      this.game.bossSummon(this, this.phase === 2 ? 3 : 2);
    }
  }

  windupAnim(dt, a, p) {
    if (a.kind === 'sweep') {
      this.torso.rotation.y = damp(this.torso.rotation.y, -1.0, 6, dt);
      this.armR.sh.rotation.x = damp(this.armR.sh.rotation.x, -.5, 6, dt);
      this.armR.sh.rotation.z = damp(this.armR.sh.rotation.z, -.7, 6, dt);
      this.body.rotation.z = damp(this.body.rotation.z, -.08, 5, dt);
    } else if (a.kind === 'slam') {
      this.armR.sh.rotation.x = damp(this.armR.sh.rotation.x, -2.9, 6, dt);
      this.torso.rotation.x = damp(this.torso.rotation.x, -.2, 6, dt);
      this.body.position.y = damp(this.body.position.y, -.2, 4, dt);
    } else if (a.kind === 'charge') {
      this.body.rotation.x = damp(this.body.rotation.x, .3, 6, dt);
      this.armR.sh.rotation.x = damp(this.armR.sh.rotation.x, -.9, 6, dt);
    } else if (a.kind === 'roots' || a.kind === 'summon') {
      this.armR.sh.rotation.x = damp(this.armR.sh.rotation.x, -2.6, 5, dt);
      this.armL.sh.rotation.x = damp(this.armL.sh.rotation.x, -2.2, 5, dt);
      this.torso.rotation.x = damp(this.torso.rotation.x, -.25, 5, dt);
      this.heartGlow.material.opacity = .5 + p * .5;
    }
  }
  impactAnim(a) {
    if (a.kind === 'sweep') {
      this.torso.rotation.y = 1.15;
      this.armR.sh.rotation.x = 0.4; this.armR.sh.rotation.z = 1.0;
    } else if (a.kind === 'slam') {
      this.armR.sh.rotation.x = .9;
      this.body.position.y = -.4;
    } else if (a.kind === 'roots' || a.kind === 'summon') {
      this.armR.sh.rotation.x = 0.2; this.armL.sh.rotation.x = 0.2;
    }
  }

  enterPhase2() {
    this.phase = 2;
    this.state = 'phaseChange';
    this.stateTime = 0;
    this.attack = null;
    this.telegraph.visible = false;
    this.game.audio.roar();
    this.game.shake(1.2);
    this.game.showBanner('THE GROVE REMEMBERS', 'The Hollow Woodsman has entered his second phase.');
    this.game.audio.setTheme('boss');
    this.game.setBossPhase(2);
    this.game.spawnSoulBurst(this.pos.clone().add(new THREE.Vector3(0, 4, 0)), 60);
  }
  phaseChangeUpdate(dt) {
    const p = clamp(this.stateTime / 2.4, 0, 1);
    this.body.position.y = -Math.sin(p * Math.PI) * .4;
    this.aura.material.opacity = .04 + p * .12;
    this.heartGlow.material.opacity = p;
    this.heartGlow.scale.setScalar(3 + p * 4);
    if (this.stateTime > 2.4) {
      this.state = 'idle';
      this.cooldown = .8;
    }
    this.root.position.copy(this.pos);
  }

  walkAnim(dt, dist) {
    const t = this.game.time;
    const speed = Math.hypot(this.vel.x, this.vel.z);
    const amount = clamp(speed / 2.4, 0, 1);
    const cycle = t * 2.4;
    const sw = Math.sin(cycle) * .4 * amount;
    this.legL.hip.rotation.x = damp(this.legL.hip.rotation.x, sw, 5, dt);
    this.legR.hip.rotation.x = damp(this.legR.hip.rotation.x, -sw, 5, dt);
    this.legL.knee.rotation.x = damp(this.legL.knee.rotation.x, Math.max(0, -sw) * .8, 5, dt);
    this.legR.knee.rotation.x = damp(this.legR.knee.rotation.x, Math.max(0, sw) * .8, 5, dt);
    this.body.position.y = damp(this.body.position.y, Math.abs(Math.cos(cycle)) * .07 * amount + Math.sin(t * 1.1) * .02, 4, dt);
    if (!this.attack) {
      this.torso.rotation.x = damp(this.torso.rotation.x, 0, 5, dt);
      this.torso.rotation.y = damp(this.torso.rotation.y, 0, 5, dt);
      this.body.rotation.z = damp(this.body.rotation.z, 0, 5, dt);
      this.body.rotation.x = damp(this.body.rotation.x, 0, 5, dt);
      this.armR.sh.rotation.x = damp(this.armR.sh.rotation.x, -sw * .3 - .2, 4, dt);
      this.armR.sh.rotation.z = damp(this.armR.sh.rotation.z, -.35, 4, dt);
      this.armL.sh.rotation.x = damp(this.armL.sh.rotation.x, sw * .25 - .1, 4, dt);
      this.heartGlow.material.opacity = .55 + Math.sin(t * 1.4) * .15;
    }
    for (const m of this.mats) {
      if (this.hitFlash > 0) { m.emissive?.setHex(0x7a1a0a); if (m.emissiveIntensity !== undefined) m.emissiveIntensity = .6; }
      else { m.emissive?.setHex(0x000000); if (m.emissiveIntensity !== undefined) m.emissiveIntensity = 0; }
    }
  }
  idleAnim(dt) {
    const t = this.game.time;
    this.body.position.y = Math.sin(t * .8) * .03;
    this.torso.rotation.x = Math.sin(t * .6) * .015;
    this.heartGlow.material.opacity = .5 + Math.sin(t * 1.6) * .15;
    this.aura.material.opacity = 0;
    this.root.position.copy(this.pos);
  }
  introAnim(dt) {
    const t = this.stateTime;
    this.body.position.y = Math.sin(t * 4) * .08;
    this.torso.rotation.x = damp(this.torso.rotation.x, t < 2.2 ? -.2 : 0, 4, dt);
    if (t > .6 && t < .9) this.game.shake(.4);
    this.root.position.copy(this.pos);
  }
  updateAura(dt) {
    if (this.phase === 2) {
      this.aura.material.opacity = .08 + Math.sin(this.game.time * 2.2) * .04;
      this.aura.rotation.y += dt * .2;
      this.auraGlow.material.opacity = .18 + Math.sin(this.game.time * 2.6) * .05;
    }
  }

  /* ================= DAMAGE ================= */
  takeDamage(amount, fromPos, opts = {}) {
    if (!this.active || this.dead || this.introActive) return;
    if (this.state === 'phaseChange') return;
    this.health -= amount;
    this.poiseBuildup += amount * .55;
    this.hitFlash = .15;
    this.game.updateBossBar();
    this.game.floatText(this.pos.clone().add(new THREE.Vector3(0, 6.2, 0)), Math.round(amount), 'enemy');
    this.game.spawnBloodBurst(this.pos.clone().add(new THREE.Vector3(0, 4.4, 0)), 10, 0xffb02e);
    this.game.spawnSparkBurst(this.pos.clone().add(new THREE.Vector3(0, 4.2, 0)), 6);
    this.game.audio.hit(true);
    if (this.poiseBuildup > this.maxPoise) {
      this.poiseBuildup = 0;
      this.stagger();
    }
    if (this.health <= 0) { this.health = 0; this.die(); }
  }
  stagger() {
    this.state = 'stagger';
    this.staggerTimer = 1.9;
    this.attack = null;
    this.telegraph.visible = false;
    this.game.showContextual('Press C to deliver a critical blow');
    this.game.audio.parry();
    this.game.floatText(this.pos.clone().add(new THREE.Vector3(0, 6.6, 0)), 'STAGGERED', 'crit');
  }
  canCrit() { return this.state === 'stagger'; }

  die() {
    this.dead = true;
    this.active = false;
    this.state = 'dead';
    this.deathTimer = 0;
    this.attack = null;
    this.telegraph.visible = false;
    this.game.audio.bossDeath();
    this.game.audio.setTheme('victory');
    this.game.slowmo(.45, 3.2);
    this.game.shake(1.4);
    this.game.hideBossBar();
    this.game.hideContextual();
    this.game.onBossDeath(this);
  }
  updateDeath(dt) {
    this.deathTimer += dt;
    const p = clamp(this.deathTimer / 2.8, 0, 1);
    this.body.rotation.z = lerp(0, 1.25, Math.min(1, p * 1.4));
    this.body.position.y = -p * .8;
    this.aura.material.opacity = Math.max(0, .2 - p * .2);
    this.heartGlow.material.opacity = Math.max(0, 1 - p);
  }

  dispose() {
    if (this.root?.parent) this.root.parent.remove(this.root);
  }
}

import * as THREE from 'three';
import { material, emissive, makeGlowSprite, rand, chance } from '../core/utils.js';
import { heightAt } from '../world/terrain.js';

export class NPC {
  constructor(game, id, name, x, z, yaw) {
    this.game = game;
    this.id = id;
    this.name = name;
    this.x = x; this.z = z; this.y = heightAt(x, z);
    this.yaw = yaw;
    this.radius = 2.8;
    this.scene = game.scene;
    this.bob = rand(0, 6);
    this.buildModel();
    this.root.position.set(x, this.y, z);
    this.root.rotation.y = yaw;
    game.scene.add(this.root);
  }

  buildModel() {
    this.root = new THREE.Group();
    const mk = (c, o = {}) => material(c, o);
    if (this.id === 'marrow') {
      const cloak = mk(0x40382e, { roughness: 1 });
      const scarf = mk(0x6b3a2e);
      const skin = mk(0x9c8164);
      const dark = mk(0x25231f);
      const wood = mk(0x4c3923);
      const brass = mk(0x9b7b3c, { metalness: .6, roughness: .4 });
      const body = new THREE.Mesh(new THREE.CylinderGeometry(.32, .46, 1.15, 7), cloak); body.position.y = .58; this.root.add(body);
      const shoulders = new THREE.Mesh(new THREE.SphereGeometry(.34, 8, 7), cloak); shoulders.position.y = 1.12; shoulders.scale.set(1.25, .55, .9); this.root.add(shoulders);
      const neck = new THREE.Mesh(new THREE.CylinderGeometry(.07, .09, .12, 5), skin); neck.position.y = 1.24; this.root.add(neck);
      const head = new THREE.Mesh(new THREE.SphereGeometry(.2, 9, 8), skin); head.position.y = 1.43; this.root.add(head);
      const nose = new THREE.Mesh(new THREE.ConeGeometry(.045, .13, 4), skin); nose.position.set(0, 1.41, .18); nose.rotation.x = Math.PI / 2; this.root.add(nose);
      for (const ex of [-.07, .07]) { const e = new THREE.Mesh(new THREE.SphereGeometry(.018, 5), dark); e.position.set(ex, 1.47, .18); this.root.add(e); }
      const brim = new THREE.Mesh(new THREE.CylinderGeometry(.42, .45, .045, 9), wood); brim.position.y = 1.57; brim.rotation.z = .08; this.root.add(brim);
      const cap = new THREE.Mesh(new THREE.CylinderGeometry(.17, .2, .28, 8), wood); cap.position.set(.02, 1.72, 0); cap.rotation.z = .08; this.root.add(cap);
      const beard = new THREE.Mesh(new THREE.ConeGeometry(.13, .35, 5), mk(0x7a6c56)); beard.position.set(0, 1.28, .12); beard.rotation.x = Math.PI; this.root.add(beard);
      const scarfM = new THREE.Mesh(new THREE.TorusGeometry(.19, .06, 5, 10), scarf); scarfM.position.y = 1.26; scarfM.rotation.x = Math.PI / 2; this.root.add(scarfM);
      // arms
      for (const sx of [-1, 1]) {
        const arm = new THREE.Mesh(new THREE.CylinderGeometry(.06, .05, .55, 5), cloak);
        arm.position.set(sx * .32, .85, .05); arm.rotation.z = sx * .25; this.root.add(arm);
      }
      // lantern
      const lg = new THREE.Group(); lg.position.set(.54, .55, .12); this.root.add(lg);
      const handle = new THREE.Mesh(new THREE.TorusGeometry(.11, .012, 4, 8), brass); handle.position.y = .2; lg.add(handle);
      const cage = new THREE.Mesh(new THREE.CylinderGeometry(.14, .14, .25, 6), brass); cage.position.y = .02; lg.add(cage);
      const light = makeGlowSprite(0xffb154, 1.8); light.position.y = .02; lg.add(light); this.lantern = light;
      const lpoint = new THREE.PointLight(0xffa94f, 1.2, 7, 2); lpoint.position.y = .02; lg.add(lpoint);
      // staff
      const staff = new THREE.Mesh(new THREE.CylinderGeometry(.025, .035, 1.8, 5), wood); staff.position.set(-.52, .8, .12); staff.rotation.z = -.08; this.root.add(staff);
      const orb = new THREE.Mesh(new THREE.SphereGeometry(.1, 7), emissive(0xffcf7a, 1.8)); orb.position.set(-.6, 1.68, .12); this.root.add(orb);
    } else if (this.id === 'wisp') {
      const cloak = mk(0x2d3f42, { roughness: 1, transparent: true, opacity: .75, side: THREE.DoubleSide });
      const body = new THREE.Mesh(new THREE.ConeGeometry(.38, 1.2, 7, 1, true), cloak); body.position.y = .65; this.root.add(body);
      const hood = new THREE.Mesh(new THREE.SphereGeometry(.26, 8, 7, 0, Math.PI * 2, 0, Math.PI * .6), cloak); hood.position.y = 1.24; this.root.add(hood);
      const core = new THREE.Mesh(new THREE.SphereGeometry(.13, 8, 7), emissive(0xa6ffec, 2.4)); core.position.y = 1.12; this.root.add(core); this.core = core;
      const glow = makeGlowSprite(0x89ffe0, 3.4); glow.position.y = 1.1; this.root.add(glow); this.glow = glow;
      const l = new THREE.PointLight(0x72ffd6, 1.2, 9, 2); l.position.y = 1.1; this.root.add(l);
      const tatters = [];
      for (let i = 0; i < 5; i++) { const t = new THREE.Mesh(new THREE.ConeGeometry(.08, rand(.4, .8), 4), cloak); t.position.set(rand(-.3, .3), rand(.25, .6), rand(-.2, .2)); t.rotation.z = rand(-.4, .4); this.root.add(t); tatters.push(t); }
      this.tatters = tatters;
      this.light = l;
    } else if (this.id === 'echo') {
      const cloak = mk(0x3a2550, { roughness: .7, transparent: true, opacity: .7, side: THREE.DoubleSide });
      const body = new THREE.Mesh(new THREE.ConeGeometry(.55, 2.2, 8, 1, true), cloak); body.position.y = 1.1; this.root.add(body);
      const hood = new THREE.Mesh(new THREE.SphereGeometry(.4, 9, 8, 0, Math.PI * 2, 0, Math.PI * .62), cloak); hood.position.y = 2.2; this.root.add(hood);
      for (const ex of [-.12, .12]) { const e = new THREE.Mesh(new THREE.SphereGeometry(.045, 6), emissive(0xc58aff, 2.5)); e.position.set(ex, 2.18, .3); this.root.add(e); }
      const staff = new THREE.Mesh(new THREE.CylinderGeometry(.035, .05, 2.6, 6), mk(0x271d30)); staff.position.set(.55, 1.3, .1); this.root.add(staff);
      const orb = new THREE.Mesh(new THREE.OctahedronGeometry(.2), emissive(0xbf8aff, 2.2)); orb.position.set(.55, 2.7, .1); this.root.add(orb); this.orb = orb;
      const glow = makeGlowSprite(0x9f6aff, 7); glow.position.y = 1.6; this.root.add(glow); this.glow = glow;
      const l = new THREE.PointLight(0x9d68ff, 1.6, 14, 2); l.position.y = 1.8; this.root.add(l);
    }
  }

  update(dt, t) {
    this.bob += dt;
    if (this.id === 'wisp' || this.id === 'echo') {
      this.root.position.y = this.y + .25 + Math.sin(t * .9 + (this.id === 'wisp' ? 0 : 2)) * .15;
      if (this.core) this.core.rotation.y += dt * 1.4;
      if (this.orb) { this.orb.rotation.y += dt * 1.6; this.orb.position.y = 2.7 + Math.sin(t * 1.3) * .1; }
      if (this.glow) this.glow.material.opacity = .6 + Math.sin(t * 1.6) * .2;
      if (this.tatters) this.tatters.forEach((tt, i) => { tt.rotation.z = Math.sin(t * 1.2 + i) * .3; });
    } else {
      this.root.position.y = this.y;
      if (this.lantern) this.lantern.material.opacity = .7 + Math.sin(t * 3.4) * .15;
      this.headBob = Math.sin(t * .8) * .01;
    }
    if (this.id === 'marrow') {
      // face the player when close, otherwise idle
      const p = this.game.player;
      if (p && p.pos.distanceTo(this.root.position) < 6) {
        const yaw = Math.atan2(p.pos.x - this.x, p.pos.z - this.z);
        this.root.rotation.y += (yaw - this.root.rotation.y) * Math.min(1, dt * 2.5);
      }
    }
  }

  dialogue() {
    const g = this.game;
    const s = g.state;
    if (this.id === 'marrow') {
      if (!s.flags.merchantMet) {
        return {
          nodes: {
            start: {
              text: 'You came out of the hill with a metal stick and a dead phone. I have seen a great many things in this shire, stranger, but never a man dressed like a folded bedsheet. Sit. Sit, before the woods notice you.',
              options: [
                { label: 'Where am I?', next: 'where' },
                { label: 'What happened to these people?', next: 'corruption' },
                { label: 'I need supplies.', action: 'shop' },
                { label: 'Not now.', action: 'close' },
              ],
            },
            where: {
              text: 'Eldoria. The Forgotten Shire, if you want the local name. It was a fairytale once. Probably still is, from a distance. The woodsman at the north end has a tree where his heart should be, and the tree is the least frightening thing in this valley.',
              options: [{ label: 'Who is the woodsman?', next: 'woodsman' }, { label: 'I need supplies.', action: 'shop' }, { label: 'I have to go.', action: 'close' }],
            },
            woodsman: {
              text: 'The Hollow Woodsman. He kept the First Grove before the rot came. Now he keeps the gate to the Weeping Wilds, and he does not distinguish between travelers and saplings. If you mean to leave this valley, you will have to put him down. I am sorry. He was kind, once.',
              options: [{ label: 'How do I kill him?', next: 'advice' }, { label: 'I need supplies.', action: 'shop' }, { label: 'I have to go.', action: 'close' }],
            },
            advice: {
              text: 'He is slow. Be patient. When the tree in his chest blazes orange, he is about to call the roots — that is when you should be somewhere else. And when you stagger him, strike the heartwood. That is the only honest part of him left.',
              options: [{ label: 'I need supplies.', action: 'shop' }, { label: 'Thank you.', action: 'close' }],
            },
            corruption: {
              text: 'The soil went sour seven winters ago. Then the knights came to collect the seed. Then the children stopped singing. It is not a plague, stranger. It is a hunger. It starts in the roots and ends in the teeth. Some of my neighbors still remember their names. Most do not.',
              options: [{ label: 'Is there a cure?', next: 'cure' }, { label: 'I need supplies.', action: 'shop' }, { label: 'I have to go.', action: 'close' }],
            },
            cure: {
              text: 'The old stories say seven crowns hold something under the kingdom. A mouth. A hunger with a name nobody says aloud. If the crowns fail, there is no cure — only a witness. Perhaps that is what you are. A witness with a metal stick.',
              options: [{ label: 'I need supplies.', action: 'shop' }, { label: 'I will find the woodsman.', action: 'close' }],
            },
          },
          startNode: 'start',
          onOpen: () => { s.flags.merchantMet = true; },
        };
      }
      if (s.quests.merchantQuest === 0) {
        return {
          nodes: {
            start: {
              text: 'Still breathing. Good. The woods have been quieter since you went up the road, and I do not trust quiet. Listen — I have a favor. My sister lived by the old graveyard west of the village. She wore a little silver locket, shaped like a bird. If you find it, bring it back. I will make it worth your while.',
              options: [
                { label: 'I will look for the locket.', action: 'quest_accept' },
                { label: 'Show me your wares.', action: 'shop' },
                { label: 'Not now.', action: 'close' },
              ],
            },
          },
          startNode: 'start',
        };
      }
      if (s.quests.merchantQuest === 1) {
        return {
          nodes: {
            start: {
              text: 'The locket was by the graves, near the leaning stone. Silver bird. My sister\'s name was Wren. She would have liked you, I think. You have the same look — like you are not sure whether you are lost or exactly where you are meant to be.',
              options: [
                { label: 'I found the locket.', action: 'quest_complete', condition: () => g.hasLocket },
                { label: 'Still looking.', action: 'close' },
                { label: 'Show me your wares.', action: 'shop' },
              ],
            },
          },
          startNode: 'start',
        };
      }
      if (s.flags.bossDefeated) {
        return {
          nodes: {
            start: {
              text: 'The grove is quiet. I walked up to the gate this morning, and the fog was gone. You did that. I do not know what you are, stranger, but the shire owes you a debt it can never pay. Take the road north. The Weeping Wilds are waiting, and they are worse.',
              options: [{ label: 'Show me your wares.', action: 'shop' }, { label: 'What waits in the Wilds?', next: 'wilds' }, { label: 'Goodbye, Marrow.', action: 'close' }],
            },
            wilds: {
              text: 'Mushrooms the size of houses. Spiders that weave their webs out of dreams. A queen in the roots who loves her children very much. Keep your blade close and your torch closer. And stranger — if you find a woman made of mycelium, do not let her touch your face.',
              options: [{ label: 'Show me your wares.', action: 'shop' }, { label: 'I will be careful.', action: 'close' }],
            },
          },
          startNode: 'start',
        };
      }
      return {
        nodes: {
          start: {
            text: 'The road north is still closed. The woodsman waits in the old grove. If you are going to face him, spend your motes first — the dead do not need shopping money.',
            options: [{ label: 'Show me your wares.', action: 'shop' }, { label: 'Tell me about the locket.', action: 'locket_hint' }, { label: 'I will return.', action: 'close' }],
          },
          locket_hint: {
            text: 'West of the village. Past the well, past the flowers, into the leaning stones. Look for a bird made of silver. My sister would have wanted it found by someone who still remembers how to be gentle.',
            options: [{ label: 'I will find it.', action: 'close' }, { label: 'Show me your wares.', action: 'shop' }],
          },
        },
        startNode: 'start',
      };
    }

    if (this.id === 'wisp') {
      const loreCount = s.lore.length;
      if (s.flags.bossDefeated && loreCount >= 3) {
        return {
          nodes: {
            start: {
              text: 'You found the pages. The ones the wizard tried to burn. Then you already know what waits at the end of the road — and what he means to do with you. There is a third door, hollow one. It is not on any map. When the time comes, look for the seam in the world.',
              options: [{ label: 'Who are you?', next: 'who' }, { label: 'I understand.', action: 'close' }],
            },
            who: {
              text: 'I was the first thing Malgraven summoned. He was younger then, and kinder, and he still believed he could save everyone. I am what is left of that belief. Go north. The Weeping Wilds will try to eat your name. Do not let them.',
              options: [{ label: 'I will remember.', action: 'close' }],
            },
          },
          startNode: 'start',
        };
      }
      return {
        nodes: {
          start: {
            text: 'A little flame in a dead wood. You are colder than the others. Cleaner. The wizard\'s summoning left no rot on you — that is why the trees are afraid. Find the scattered pages, hollow one. Three truths will open the third door.',
            options: [
              { label: 'Who is Malgraven?', next: 'malgraven' },
              { label: 'What is the Devourer?', next: 'devourer' },
              { label: 'I have pages to find.', action: 'close' },
            ],
          },
          malgraven: {
            text: 'The Last Seer of Eldoria. He pulled you across the veil because your soul is untouched by the curse. He will call it salvation. It is a ritual, and you are the final ingredient. Do not trust the voice that sounds like help.',
            options: [{ label: 'What is the Devourer?', next: 'devourer' }, { label: 'I will be careful.', action: 'close' }],
          },
          devourer: {
            text: 'The thing beneath the seven crowns. Not a demon — a wound. The kings stitched it shut with their kingdoms, and the stitches are failing one by one. Malgraven thinks he can use you to cut it out. The demon thinks it can use you to open wider. Both of them are wrong about what you are.',
            options: [{ label: 'What am I?', next: 'whatami' }, { label: 'I have pages to find.', action: 'close' }],
          },
          whatami: {
            text: 'A person from a place with no magic, standing in a fairytale with a piece of pipe. That is the most dangerous thing in Eldoria. Now go and find the pages before the forest forgets how to whisper.',
            options: [{ label: 'I will find them.', action: 'close' }],
          },
        },
        startNode: 'start',
      };
    }

    if (this.id === 'echo') {
      return {
        nodes: {
          start: {
            text: 'You killed the woodsman. Good. The gate will open now, and the Weeping Wilds will sing to you with a thousand wet mouths. But before you go — look. I left a thread of fate in the grove. Touch it, and see the three endings that wait at the bottom of the world. Consider it a courtesy. I am not often courteous.',
            options: [
              { label: 'Show me the threads of fate.', action: 'endings' },
              { label: 'Why did you bring me here?', next: 'why' },
              { label: 'I am not ready.', action: 'close' },
            ],
          },
          why: {
            text: 'Because you are unbroken. Because every soul in this kingdom is already food, and you are still a knife. Because I am old, and frightened, and I have run out of better ideas. That is the truth, hero. I hope you can forgive me. I doubt it.',
            options: [{ label: 'Show me the threads of fate.', action: 'endings' }, { label: 'I will never forgive you.', action: 'close' }],
          },
        },
        startNode: 'start',
      };
    }
    return null;
  }
}

import * as THREE from 'three';
import { ENDINGS, CONTROLS, LORE, WEAPONS, ARMOR, ITEMS, REGION_INFO } from '../game/data.js';
import { PATH, ARENA } from '../world/terrain.js';
import { formatTime } from '../core/utils.js';

const _v = new THREE.Vector3();

export class UI {
  constructor(game) {
    this.game = game;
    this.el = {};
    const ids = [
      'hud', 'hp-fill', 'hp-lag', 'st-fill', 'fp-fill', 'flask-count', 'motes-count', 'objective-text',
      'weapon-name', 'armor-name', 'lock-reticle', 'enemy-bars', 'interact-prompt', 'interact-text',
      'boss-bar', 'boss-name', 'boss-sub', 'boss-fill', 'boss-lag', 'boss-phase', 'subtitle', 'toasts',
      'damage-flash', 'hint', 'contextual', 'cinematic', 'cinematic-title', 'cinematic-lines',
      'title-screen', 'btn-new', 'btn-continue', 'btn-controls', 'btn-credits', 'title-saveinfo',
      'loading', 'load-fill', 'load-status', 'menu-overlay', 'menu-title', 'menu-body', 'menu-footer', 'menu-close',
      'dialogue', 'dialogue-name', 'dialogue-text', 'dialogue-options', 'dialogue-portrait', 'dialogue-hint',
      'death-screen', 'death-line', 'death-motes', 'btn-respawn', 'victory-banner', 'victory-title', 'victory-sub',
      'ending-screen', 'ending-kicker', 'ending-title', 'ending-text', 'ending-flavor', 'btn-ending-continue',
      'controls-screen', 'controls-grid', 'controls-close', 'fade', 'lowhp', 'region-name', 'region-sub',
    ];
    for (const id of ids) this.el[id] = document.getElementById(id);
    this.toastQueue = [];
    this.dialogueState = null;
    this.currentMenu = null;
    this.subtitleTimer = 0;
    this.floatPool = [];
    this.bossRef = null;
    this.eliteRef = null;
    this.deathShown = false;
    this._lastEnemyBars = new Map();
    this.bind();
    this.buildControls();
  }

  bind() {
    this.el['btn-new'].addEventListener('click', () => { this.game.audio.init(); this.game.audio.ui(); this.game.startNewGame(); });
    this.el['btn-continue'].addEventListener('click', () => { this.game.audio.init(); this.game.audio.ui(); this.game.continueGame(); });
    this.el['btn-controls'].addEventListener('click', () => { this.game.audio.ui(); this.showControls(); });
    this.el['btn-credits'].addEventListener('click', () => { this.game.audio.ui(); this.showCredits(); });
    this.el['controls-close'].addEventListener('click', () => { this.hideControls(); });
    this.el['menu-close'].addEventListener('click', () => { this.game.closeMenu(); });
    this.el['btn-respawn'].addEventListener('click', () => { this.game.respawn(); });
    this.el['btn-ending-continue'].addEventListener('click', () => { this.game.returnToThreshold(); });
    window.addEventListener('keydown', (e) => this.onKeyDown(e));
    document.getElementById('game-canvas').addEventListener('click', () => { if (this.game.state.started && !this.game.uiBlocking && !this.game.cinematic) this.game.audio.resume(); });
  }

  buildControls() {
    this.el['controls-grid'].innerHTML = CONTROLS.map(([a, b]) => `<div class="control-row"><span>${a}</span><span class="control-key">${b}</span></div>`).join('');
  }

  onKeyDown(e) {
    if (this.dialogueState) {
      if (e.code === 'Escape') { e.preventDefault(); this.closeDialogue(); return; }
      if (/^Digit[1-9]$/.test(e.code)) {
        const idx = +e.code.slice(5) - 1;
        const btn = this.el['dialogue-options'].children[idx];
        if (btn) { e.preventDefault(); btn.click(); }
        return;
      }
      if (e.code === 'KeyE' || e.code === 'Enter') {
        e.preventDefault();
        if (this.dialogueState.node.options?.length) {
          const first = this.el['dialogue-options'].querySelector('.dialogue-option');
          if (first) first.click();
        } else this.closeDialogue();
      }
    }
  }

  /* ==================== TITLE / LOADING ==================== */
  setLoading(p, text) {
    this.el['load-fill'].style.width = `${Math.round(p * 100)}%`;
    if (text) this.el['load-status'].textContent = text;
  }
  finishLoading() {
    this.el.loading.classList.add('done');
    setTimeout(() => this.el.loading.classList.add('hidden'), 800);
  }
  updateTitleSlot(hasSave, summary) {
    this.el['btn-continue'].classList.toggle('hidden', !hasSave);
    if (hasSave && summary) {
      this.el['title-saveinfo'].textContent = `Level ${summary.level} · ${summary.motes} motes · ${summary.deaths} deaths · ${formatTime(summary.playtime)}`;
    } else if (hasSave) this.el['title-saveinfo'].textContent = 'A journey awaits.';
    else this.el['title-saveinfo'].textContent = '';
  }
  showTitle() {
    this.el['title-screen'].classList.remove('hidden');
    this.el.hud.classList.add('hidden');
    this.el['menu-overlay'].classList.add('hidden');
    this.el['ending-screen'].classList.add('hidden');
    this.el['death-screen'].classList.add('hidden');
    this.el['dialogue'].classList.add('hidden');
    this.el.dialogue.classList.add('hidden');
  }
  hideTitle() { this.el['title-screen'].classList.add('hidden'); }
  showHUD() { this.el.hud.classList.remove('hidden'); }
  hideHUD() { this.el.hud.classList.add('hidden'); }

  /* ==================== CINEMATIC ==================== */
  showCinematic() { this.el.cinematic.classList.remove('hidden'); this.hideHUD(); }
  hideCinematic() { this.el.cinematic.classList.add('hidden'); this.el['cinematic-lines'].innerHTML = ''; this.el['cinematic-title'].classList.add('hidden'); }
  showCinematicTitle(show = true) { this.el['cinematic-title'].classList.toggle('hidden', !show); }
  setCinematicLine(text) {
    this.el['cinematic-lines'].innerHTML = text ? `<div class="cine-line">${text}</div>` : '';
  }
  subtitle(text, dur = 4) {
    this.el.subtitle.textContent = text;
