  drawMap(cv) {
    const g = this.game;
    const rect = cv.getBoundingClientRect();
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    cv.width = rect.width * dpr; cv.height = rect.height * dpr;
    const ctx = cv.getContext('2d');
    ctx.scale(dpr, dpr);
    const w = rect.width, h = rect.height;
    const toMap = (x, z) => [w * .5 + x / 250 * w * .9, h * .5 + z / 250 * h * .9];
    // parchment bg
    const grad = ctx.createRadialGradient(w * .45, h * .4, 10, w * .5, h * .5, w * .7);
    grad.addColorStop(0, '#231f18'); grad.addColorStop(1, '#0c0b0d');
    ctx.fillStyle = grad; ctx.fillRect(0, 0, w, h);
    // noise
    for (let i = 0; i < 240; i++) { ctx.fillStyle = `rgba(201,164,92,${Math.random() * .035})`; ctx.fillRect(Math.random() * w, Math.random() * h, 1, 1); }
    // forest blobs
    ctx.fillStyle = 'rgba(52,68,45,.5)';
    for (const [cx, cz, r] of [[-48, 25, 36], [-60, -20, 32], [40, 10, 30], [55, 55, 26], [-40, 70, 22], [48, -45, 30]]) {
      const [x, y] = toMap(cx, cz);
      ctx.beginPath(); ctx.arc(x, y, r / 250 * w, 0, Math.PI * 2); ctx.fill();
    }
    // arena
    const [ax, ay] = toMap(ARENA.x, ARENA.z);
    ctx.strokeStyle = 'rgba(156,92,255,.4)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(ax, ay, ARENA.r / 250 * w, 0, Math.PI * 2); ctx.stroke();
    ctx.fillStyle = 'rgba(90,44,120,.18)'; ctx.fill();
    // path
    ctx.strokeStyle = 'rgba(201,164,92,.5)'; ctx.lineWidth = 2.2; ctx.setLineDash([5, 7]);
    ctx.beginPath();
    PATH.forEach(([x, z], i) => { const [mx, my] = toMap(x, z); i ? ctx.lineTo(mx, my) : ctx.moveTo(mx, my); });
    ctx.stroke(); ctx.setLineDash([]);
    // landmarks
    const dot = (x, z, color, r = 3, label = '') => {
      const [mx, my] = toMap(x, z);
      ctx.fillStyle = color; ctx.beginPath(); ctx.arc(mx, my, r, 0, Math.PI * 2); ctx.fill();
      if (label) { ctx.font = '9px Georgia'; ctx.fillStyle = 'rgba(220,210,190,.6)'; ctx.textAlign = 'center'; ctx.fillText(label, mx, my - 7); }
    };
    for (const sh of g.world.shrines) dot(sh.x, sh.z, '#c9a45c', 3.5, sh.id === 'tree' ? 'SHRINE' : '');
    for (const ch of g.world.chests) { const [mx, my] = toMap(ch.x, ch.z); ctx.fillStyle = '#b0733d'; ctx.fillRect(mx - 2, my - 2, 4, 4); }
    for (const npc of g.npcs) dot(npc.x, npc.z, '#8fb0d8', 2.5, npc.id === 'marrow' ? 'MARROW' : '');
    const [gx, gy] = toMap(0, -102); ctx.fillStyle = 'rgba(160,60,60,.9)'; ctx.font = '13px Georgia'; ctx.textAlign = 'center'; ctx.fillText('☠', gx, gy);
    // player
    const [px, py] = toMap(g.player.pos.x, g.player.pos.z);
    ctx.save(); ctx.translate(px, py); ctx.rotate(-g.player.yaw);
    ctx.fillStyle = '#f0e6d0'; ctx.beginPath(); ctx.moveTo(0, -7); ctx.lineTo(4.5, 5); ctx.lineTo(0, 3); ctx.lineTo(-4.5, 5); ctx.closePath(); ctx.fill();
    ctx.restore();
    ctx.strokeStyle = 'rgba(231,205,146,.35)'; ctx.beginPath(); ctx.arc(px, py, 10, 0, Math.PI * 2); ctx.stroke();
    // compass
    ctx.fillStyle = 'rgba(201,164,92,.65)'; ctx.font = '10px Georgia'; ctx.textAlign = 'center'; ctx.fillText('N', w / 2, 16);
    ctx.beginPath(); ctx.moveTo(w / 2, 20); ctx.lineTo(w / 2 - 3, 28); ctx.lineTo(w / 2 + 3, 28); ctx.closePath(); ctx.fill();
  }

  showEndings(available) {
    const body = `
      <p style="font-size:15px;line-height:1.7;color:#b9ae9a;font-style:italic;margin-top:0">The seer's echo splits into three threads. Each is a choice you have not yet made — a shape the future might take if you reach the bottom of the world.</p>
      <div class="ending-choice">
        <button class="menu-btn" data-ending="dawn">A NEW DAWN<small>Destroy the Devourer. Open the way home. Save Eldoria.</small></button>
        <button class="menu-btn" data-ending="crown">THE HOLLOW CROWN<small>Take the Devourer's power. Rule what remains.</small></button>
        <button class="menu-btn" data-ending="veil" ${available.veil ? '' : 'disabled'}>BEYOND THE VEIL ${available.veil ? '' : '<small style="color:#6d6558">Locked — find three pages of Eldoria\'s truth.</small>'}<small>Reject both. Walk through the door that was never meant to open.</small></button>
      </div>`;
    this.openMenu('THE THREE THREADS', body, `<span>An echo is not a promise.</span><span>${available.veil ? 'All threads visible' : `Pages recovered: ${this.game.state.lore.length} / 3`}</span>`, true);
    this.el['menu-body'].querySelectorAll('[data-ending]').forEach(b => b.addEventListener('click', () => { if (b.disabled) return; this.game.chooseEnding(b.dataset.ending); }));
  }

  showEnding(ending) {
    this.closeMenuUI();
    this.hideHUD();
    this.el['ending-screen'].classList.remove('hidden');
    this.el['ending-kicker'].textContent = ending.kicker;
    this.el['ending-title'].textContent = ending.title;
    this.el['ending-text'].textContent = ending.text;
    this.el['ending-flavor'].textContent = ending.flavor;
  }
  hideEnding() { this.el['ending-screen'].classList.add('hidden'); }

  showControls() {
    this.el['controls-screen'].classList.remove('hidden');
    this.game.audio.ui();
  }
  hideControls() { this.el['controls-screen'].classList.add('hidden'); }
  showCredits() {
    this.openMenu('CREDITS', `
      <div style="line-height:1.9;font-size:14px;color:#b7ac97">
        <p style="font-style:italic;color:#d8cdb6">THE HOLLOW CROWN</p>
        <p>A playable dark-fairytale vertical slice.</p>
        <p style="margin-top:18px;font-size:12px;color:#8c8373">Design, code, procedural world, characters, animation, music and sound — generated for this build.<br/>
        Built with Three.js and the Web Audio API. No external art assets.<br/>
        Keyboard + mouse and Xbox-style controller supported.</p>
        <p style="margin-top:18px;font-size:12px;color:#6f685b">“An ordinary human. A kingdom devoured from within. The only way home is through the dark.”</p>
      </div>`, '<span>Thank you for playing.</span><span>ESC to close</span>');
  }

  /* ==================== DIALOGUE ==================== */
  openDialogue(npc) {
    const data = npc.dialogue();
    if (!data) return;
    this.dialogueState = { npc, data, node: data.nodes[data.startNode] };
    this.el.dialogue.classList.remove('hidden');
    this.el['dialogue-name'].textContent = npc.name;
    this.el['dialogue-portrait'].textContent = npc.id === 'marrow' ? '☾' : npc.id === 'wisp' ? '✦' : '◉';
    this.el['dialogue-hint'].textContent = '[E] continue · [1-4] choose · [ESC] leave';
    this.renderDialogue();
  }
  renderDialogue() {
    const st = this.dialogueState;
    if (!st) return;
    const node = st.node;
    this.el['dialogue-text'].textContent = node.text;
    const opts = this.el['dialogue-options'];
    opts.innerHTML = '';
    if (node.options && node.options.length) {
      node.options.forEach((o, i) => {
        if (o.condition && !o.condition()) return;
        const b = document.createElement('button');
        b.className = 'dialogue-option';
        b.textContent = `${i + 1}. ${o.label}`;
        b.addEventListener('click', () => this.chooseDialogue(o));
        opts.appendChild(b);
      });
    } else {
      const b = document.createElement('button');
      b.className = 'dialogue-option';
      b.textContent = 'Continue';
      b.addEventListener('click', () => this.closeDialogue());
      opts.appendChild(b);
    }
  }
  chooseDialogue(option) {
    const st = this.dialogueState;
    if (!st) return;
    this.game.audio.ui();
    if (option.next) { const n = st.data.nodes[option.next]; if (n) { st.node = n; this.renderDialogue(); return; } }
    if (option.action) { this.game.dialogueAction(option.action, st.npc); return; }
  }
  closeDialogue() {
    this.dialogueState = null;
    this.el.dialogue.classList.add('hidden');
    this.game.closeDialogue();
  }

  /* ==================== misc ==================== */
  setBossVisible(v) { this.el['boss-bar'].classList.toggle('hidden', !v); }
}

const ENDING_TITLES = { dawn: 'A NEW DAWN', crown: 'THE HOLLOW CROWN', veil: 'BEYOND THE VEIL' };

import * as THREE from 'three';
import { mergeColored, material, emissive, makeGlowSprite, rand, seededRandom } from '../core/utils.js';

const BOX = new THREE.BoxGeometry(1, 1, 1);

function pushBox(arr, color, sx, sy, sz, x, y, z, ry = 0) {
  const m = new THREE.Matrix4().compose(new THREE.Vector3(x, y, z), new THREE.Quaternion().setFromEuler(new THREE.Euler(0, ry, 0)), new THREE.Vector3(sx, sy, sz));
  arr.push({ geometry: BOX, color, matrix: m });
}

export class IntroCinematic {
  constructor(game) {
    this.game = game;
    this.time = 0;
    this.duration = 24;
    this.done = false;
    this.shake = 0;
    this.flash = 0;
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x07080d);
    this.scene.fog = new THREE.FogExp2(0x090a12, .045);
    this.camera = new THREE.PerspectiveCamera(48, 16 / 9, .1, 300);
    this.camera.position.set(7, 2.6, 14);
    this.camera.lookAt(0, 1.8, 0);
    this.build();
    this.captions = [
      [1.2, 'November 14, 2026. 3:17 AM.'],
      [4.5, 'The city was asleep.'],
      [7.0, 'The sky was not.'],
      [11.0, 'Something on the other side had been waiting.'],
      [15.5, 'It knew his name.'],
      [19.0, 'Then the rain stopped.'],
    ];
    this.captionIndex = 0;
    this.lightning = 0;
  }

  build() {
    const S = 160;
    // wet asphalt
    const road = new THREE.Mesh(new THREE.PlaneGeometry(S, S), new THREE.MeshStandardMaterial({ color: 0x0b0c10, roughness: .28, metalness: .55 }));
    road.rotation.x = -Math.PI / 2; this.scene.add(road);
    // sidewalk patches
    const walkMat = material(0x14151a, { roughness: .55, metalness: .2 });
    for (const [x, z, w, d] of [[0, 6, 18, 5], [0, -6, 18, 5], [12, 0, 5, 30], [-12, 0, 5, 30]]) {
      const m = new THREE.Mesh(new THREE.BoxGeometry(w, .22, d), walkMat); m.position.set(x, .11, z); this.scene.add(m);
    }
    // buildings both sides
    const parts = [], winParts = [];
    const rnd = seededRandom(2026);
    for (let i = 0; i < 26; i++) {
      const side = i % 2 === 0 ? -1 : 1;
      const z = -38 + (i / 26) * 82 + rnd() * 3;
      const x = side * (13 + rnd() * 16);
      const h = 12 + rnd() * 34;
      const w = 7 + rnd() * 9, d = 7 + rnd() * 9;
      pushBox(parts, new THREE.Color().setHSL(.6, .08, .07 + rnd() * .05), w, h, d, x, h / 2, z);
      // rooftop
      pushBox(parts, new THREE.Color(0x0c0d10), w * .3, 1.2, d * .3, x, h + .6, z);
      // windows
      const cols = Math.max(2, Math.floor(w / 2.2));
      const rows = Math.max(3, Math.floor(h / 3.2));
      for (let c = 0; c < cols; c++) {
        for (let r = 0; r < rows; r++) {
          if (rnd() < .62) continue;
          const col = rnd() < .18 ? 0xffd28a : rnd() < .5 ? 0x9fc8e8 : 0xd8b46a;
          pushBox(winParts, new THREE.Color(col), .5, .7, .06, x - w / 2 + 1.2 + c * (w - 2.4) / Math.max(1, cols - 1), 2 + r * 3, z - d / 2 - .04);
          pushBox(winParts, new THREE.Color(col), .5, .7, .06, x - w / 2 + 1.2 + c * (w - 2.4) / Math.max(1, cols - 1), 2 + r * 3, z + d / 2 + .04);
        }
      }
      // neon signs near street level
      if (rnd() < .45) {
        const neon = [0xff3d6e, 0x38d6ff, 0xffa23d, 0x9a5bff][Math.floor(rnd() * 4)];
        pushBox(winParts, new THREE.Color(neon), .12, 2.2, 1.1, x - side * (w / 2 + .1), 2.2 + rnd() * 2, z);
        const l = new THREE.PointLight(neon, 2.2, 16, 2); l.position.set(x - side * 3, 3.2, z); this.scene.add(l);
      }
    }
    // distant skyline
    for (let i = 0; i < 18; i++) {
      const x = (rnd() * 2 - 1) * 90, z = -80 - rnd() * 40;
      pushBox(parts, new THREE.Color(0x090a0e), 8 + rnd() * 14, 20 + rnd() * 60, 10, x, 10 + rnd() * 30, z);
    }
    const geo = mergeColored(parts);
    const mesh = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ vertexColors: true, roughness: .8, metalness: .15 }));
    this.scene.add(mesh);
    const winGeo = mergeColored(winParts);
    const winMesh = new THREE.Mesh(winGeo, new THREE.MeshBasicMaterial({ vertexColors: true }));
    this.scene.add(winMesh);
    this.winMesh = winMesh;

    // streetlights
    for (const [x, z] of [[-6, 5], [6, -5], [-6, -18], [6, 18]]) {
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(.08, .12, 6, 5), material(0x1b1c20, { metalness: .6, roughness: .4 }));
      pole.position.set(x, 3, z); this.scene.add(pole);
      const arm = new THREE.Mesh(new THREE.BoxGeometry(1.5, .1, .1), pole.material); arm.position.set(x + (x < 0 ? .7 : -.7), 5.9, z); this.scene.add(arm);
      const lamp = new THREE.Mesh(new THREE.SphereGeometry(.16, 6), emissive(0xffc27a, 2.2)); lamp.position.set(x + (x < 0 ? 1.4 : -1.4), 5.85, z); this.scene.add(lamp);
      const l = new THREE.PointLight(0xffb168, 4, 18, 2); l.position.copy(lamp.position); this.scene.add(l);
    }
    // protagonist
    this.buildProtagonist();
    // rain
    const rainCount = 1800;
    const rainPos = new Float32Array(rainCount * 3);
    for (let i = 0; i < rainCount; i++) {
      rainPos[i * 3] = (rnd() * 2 - 1) * 60;
      rainPos[i * 3 + 1] = rnd() * 40;
      rainPos[i * 3 + 2] = (rnd() * 2 - 1) * 60;
    }
    const rainGeo = new THREE.BufferGeometry();
    rainGeo.setAttribute('position', new THREE.BufferAttribute(rainPos, 3));
    const rainMat = new THREE.PointsMaterial({ color: 0x9fb4c8, size: .045, transparent: true, opacity: .55, depthWrite: false });
    this.rain = new THREE.Points(rainGeo, rainMat); this.scene.add(this.rain);
    // ground puddles
    for (let i = 0; i < 12; i++) {
      const p = new THREE.Mesh(new THREE.CircleGeometry(rand(.8, 2.6), 12), new THREE.MeshBasicMaterial({ color: 0x1c2431, transparent: true, opacity: .4 }));
      p.rotation.x = -Math.PI / 2; p.position.set(rand(-9, 9), .235, rand(-15, 15)); this.scene.add(p);
    }
    // rift
    this.rift = new THREE.Group();
    const riftPlane = new THREE.Mesh(new THREE.PlaneGeometry(4, 7), new THREE.MeshBasicMaterial({ color: 0x8b4cff, transparent: true, opacity: .4, blending: THREE.AdditiveBlending, side: THREE.DoubleSide }));
    this.rift.add(riftPlane); this.riftPlane = riftPlane;
    const riftTorus = new THREE.Mesh(new THREE.TorusGeometry(2.6, .08, 6, 40), emissive(0xc48aff, 2.5));
    riftTorus.scale.set(1, 1.35, 1); this.rift.add(riftTorus); this.riftTorus = riftTorus;
    const riftGlow = makeGlowSprite(0x9a5bff, 18); this.rift.add(riftGlow); this.riftGlow = riftGlow;
    const riftLight = new THREE.PointLight(0x8b4cff, 0, 30, 2); this.rift.add(riftLight); this.riftLight = riftLight;
    this.rift.position.set(0, 4.5, -9); this.rift.scale.setScalar(.01); this.scene.add(this.rift);
    // debris
    this.debris = [];
    for (let i = 0; i < 20; i++) {
      const d = new THREE.Mesh(new THREE.BoxGeometry(rand(.1, .4), rand(.1, .4), rand(.1, .4)), material(0x2a2b30, { roughness: .8 }));
      d.position.set(rand(-3, 3), rand(1, 5), rand(-2, 2)); d.visible = false; this.scene.add(d);
      this.debris.push({ mesh: d, speed: rand(.3, 1.2), phase: rand(0, 6) });
    }
    // lights
    this.scene.add(new THREE.HemisphereLight(0x33415c, 0x0a0a0e, .45));
    this.dir = new THREE.DirectionalLight(0x9fb7dc, .35); this.dir.position.set(-10, 30, 20); this.scene.add(this.dir);
    this.street = new THREE.PointLight(0xffb168, 2.4, 26, 2); this.street.position.set(0, 5, 2); this.scene.add(this.street);
  }

  buildProtagonist() {
    const root = new THREE.Group(); this.protagonist = root;
    const skin = material(0xb98b69);
    const hoodie = material(0x31465c, { roughness: .95 });
    const jeans = material(0x2a2f3a, { roughness: .95 });
    const shoe = material(0xd0c9bb);
    const hair = material(0x231b17);
    const torso = new THREE.Mesh(new THREE.BoxGeometry(.5, .62, .3), hoodie); torso.position.y = 1.2; root.add(torso);
    const hood = new THREE.Mesh(new THREE.TorusGeometry(.17, .08, 5, 10), hoodie); hood.position.y = 1.52; hood.rotation.x = Math.PI / 2; root.add(hood);
    const head = new THREE.Mesh(new THREE.SphereGeometry(.19, 10, 8), skin); head.position.y = 1.68; root.add(head);
    const hairM = new THREE.Mesh(new THREE.SphereGeometry(.2, 9, 7), hair); hairM.position.y = 1.75; hairM.scale.set(1, .65, 1); root.add(hairM);
    for (const sx of [-1, 1]) {
      const arm = new THREE.Mesh(new THREE.CylinderGeometry(.07, .06, .55, 6), hoodie); arm.position.set(sx * .32, 1.05, .02); arm.rotation.z = sx * .1; root.add(arm);
      const hand = new THREE.Mesh(new THREE.SphereGeometry(.07, 6), skin); hand.position.set(sx * .36, .76, .04); root.add(hand);
      const leg = new THREE.Mesh(new THREE.CylinderGeometry(.09, .075, .58, 6), jeans); leg.position.set(sx * .14, .5, 0); root.add(leg);
      const shoeM = new THREE.Mesh(new THREE.BoxGeometry(.16, .12, .3), shoe); shoeM.position.set(sx * .14, .17, .05); root.add(shoeM);
    }
    // phone in hand
    const phone = new THREE.Mesh(new THREE.BoxGeometry(.09, .17, .02), emissive(0x8fbcd8, 1.2)); phone.position.set(.36, .78, .1); phone.rotation.set(-.3, .3, 0); root.add(phone);
    const phoneGlow = makeGlowSprite(0x9fd6ff, 1.6); phoneGlow.position.set(.36, .8, .16); root.add(phoneGlow);
    const phoneLight = new THREE.PointLight(0x9fd6ff, .8, 4, 2); phoneLight.position.set(.36, .85, .3); root.add(phoneLight);
    root.position.set(0, 0, 0); root.rotation.y = Math.PI;
    this.scene.add(root);
    this.phoneGlow = phoneGlow; this.phoneLight = phoneLight;
  }

  update(dt) {
    if (this.done) return;
    this.time += dt;
    const t = this.time;

    // rain
    const rp = this.rain.geometry.attributes.position;
    for (let i = 0; i < rp.count; i++) {
      let y = rp.getY(i) - dt * (22 + (i % 7));
      if (y < 0) { y = 40; rp.setX(i, (Math.random() * 2 - 1) * 60); rp.setZ(i, (Math.random() * 2 - 1) * 60); }
      rp.setY(i, y);
    }
    rp.needsUpdate = true;

    // camera timeline
    const cam = this.camera;
    let pos, look;
    if (t < 5) {
      const k = t / 5;
      pos = new THREE.Vector3(8 - k * 1.5, 2.6 - k * .4, 15 - k * 3);
      look = new THREE.Vector3(0, 1.6, 0);
    } else if (t < 9) {
      const k = (t - 5) / 4;
      pos = new THREE.Vector3(6.5 - k * 4.5, 2.2 - k * .35, 12 - k * 6);
      look = new THREE.Vector3(0, 1.55 + k * .2, 0);
    } else if (t < 15) {
      const k = (t - 9) / 6;
      pos = new THREE.Vector3(2 - k * 1, 1.85 + k * .5, 6 - k * 3.5);
      look = new THREE.Vector3(0, 1.6 + k * .9, 0);
    } else {
      const k = Math.min(1, (t - 15) / 6);
      pos = new THREE.Vector3(1 - k * .2, 2.35 + k * 1.2, 2.5 + k * 5);
      look = new THREE.Vector3(0, 2.0 + k * 2.2, -1);
    }
    // shake
    this.shake = Math.max(0, this.shake - dt * 2);
    if (this.shake > 0) { pos.x += (Math.random() - .5) * this.shake; pos.y += (Math.random() - .5) * this.shake; }
    cam.position.lerp(pos, 1 - Math.exp(-3.2 * dt));
    cam.lookAt(look);

    // lightning
    this.lightning = Math.max(0, this.lightning - dt * 6);
    if (Math.random() < dt * .08) this.lightning = 1;
    if (this.lightning > 0) { this.dir.intensity = .35 + this.lightning * 4; }
    else this.dir.intensity = .35;

    // rift timeline
    if (t > 8) {
      const k = Math.min(1, (t - 8) / 5);
      this.rift.scale.setScalar(.01 + k * 1);
      this.rift.rotation.z = Math.sin(t * .3) * .1;
      this.riftPlane.material.opacity = .25 + k * .45 + Math.sin(t * 8) * .08;
      this.riftTorus.rotation.z += dt * .25;
      this.riftGlow.material.opacity = .2 + k * .5;
      this.riftLight.intensity = k * 5;
      this.rift.position.x = Math.sin(t * .7) * .2;
      if (t > 10) this.shake = Math.max(this.shake, .06 + k * .1);
    }
    // protagonist lift / turn
    if (t > 12) {
      const k = Math.min(1, (t - 12) / 5);
      this.protagonist.position.y = k * k * 2.4;
      this.protagonist.rotation.y = Math.PI + k * 1.2;
      this.protagonist.rotation.z = Math.sin(t * 2) * .1 * k;
      this.phoneGlow.material.opacity = 1 - k * .7;
      for (const d of this.debris) { d.mesh.visible = true; const a = t * d.speed + d.phase; d.mesh.position.set(Math.cos(a) * (2 + d.speed * 2), 1 + (a * .4 % 4), Math.sin(a) * (2 + d.speed * 2)); d.mesh.rotation.x += dt * 3; d.mesh.rotation.y += dt * 2; }
    }
    // whiteout
    if (t > 17 && t < 18.2) {
      const k = (t - 17) / 1.2;
      this.game.ui.el.fade.classList.add('flash');
      this.game.ui.el.fade.style.opacity = String(k);
    } else if (t >= 18.2 && t < 20.5) {
      this.game.ui.el.fade.classList.add('on');
      this.game.ui.el.fade.style.opacity = '1';
      this.game.ui.setCinematicLine('');
    } else if (t >= 20.5) {
      this.game.ui.el.fade.classList.remove('flash');
      this.game.ui.el.fade.classList.remove('on');
      this.game.ui.el.fade.style.opacity = '0';
    }

    // captions
    while (this.captionIndex < this.captions.length && t >= this.captions[this.captionIndex][0]) {
      const c = this.captions[this.captionIndex++];
      if (c[1] && t < 18.2) this.game.ui.setCinematicLine(c[1]);
      if (this.captionIndex === 4) this.game.ui.showCinematicTitle(false);
    }
    if (t > 18.2 && this.captionIndex < this.captions.length) { this.captionIndex = this.captions.length; this.game.ui.setCinematicLine(''); }

    if (t > this.duration) this.finish();
  }

  finish() {
    if (this.done) return;
    this.done = true;
    this.game.ui.el.fade.classList.remove('flash');
    this.game.ui.el.fade.classList.remove('on');
    this.game.ui.el.fade.style.opacity = '0';
    this.game.endIntro();
  }

  dispose() {
    this.scene.traverse(o => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        const ms = Array.isArray(o.material) ? o.material : [o.material];
        for (const m of ms) { m.map?.dispose(); m.dispose?.(); }
      }
    });
  }
}

import * as THREE from 'three';
import { rand, choose, makeGlowSprite } from '../core/utils.js';
import { heightAt } from '../world/terrain.js';

const SPHERE = new THREE.SphereGeometry(.09, 5, 4);
const SHARD = new THREE.TetrahedronGeometry(.1);
const CUBE = new THREE.BoxGeometry(.12, .12, .12);

export class Effects {
  constructor(game, scene) {
    this.game = game;
    this.scene = scene;
    this.particles = [];
    this.rings = [];
    this.arcs = [];
    this.telegraphs = [];
    this.spikes = [];
  }

  spawnParticles(pos, count, color, opts = {}) {
    const { speed = 3, life = .7, size = 1, gravity = 6, spread = 1, shape = 'sphere', glow = false } = opts;
    if (this.particles.length > 380) {
      for (let i = 0; i < count; i++) { const old = this.particles.shift(); if (old) this.scene.remove(old.mesh); }
    }
    for (let i = 0; i < count; i++) {
      const geo = shape === 'shard' ? SHARD : shape === 'cube' ? CUBE : SPHERE;
      const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1, blending: glow ? THREE.AdditiveBlending : THREE.NormalBlending, depthWrite: false });
      const m = new THREE.Mesh(geo, mat);
      m.position.set(pos.x + rand(-.3, .3), pos.y + rand(-.2, .4), pos.z + rand(-.3, .3));
      const s = (0.4 + Math.random() * .9) * size;
      m.scale.setScalar(s);
      this.scene.add(m);
      const a = rand(0, Math.PI * 2), up = rand(.2, 1.4) * speed;
      const v = new THREE.Vector3(Math.cos(a) * rand(.2, 1) * speed * spread, up, Math.sin(a) * rand(.2, 1) * speed * spread);
      this.particles.push({ mesh: m, mat, v, life: life * rand(.7, 1.3), maxLife: life, gravity, size: s });
    }
  }
  blood(pos, count = 10, color = 0x7a1f1f) { this.spawnParticles(pos, count, color, { speed: 3.2, life: .65, gravity: 12, shape: 'sphere' }); }
  sparks(pos, count = 8) { this.spawnParticles(pos, count, 0xffd88a, { speed: 4.4, life: .35, gravity: 8, size: .8, glow: true, shape: 'cube' }); }
  souls(pos, count = 18) { this.spawnParticles(pos, count, 0x9fe8d0, { speed: 1.6, life: 1.3, gravity: -1.5, size: 1.1, glow: true, shape: 'sphere' }); }
  heal(pos) { this.spawnParticles(pos.clone().add(new THREE.Vector3(0, 1, 0)), 18, 0xffc46a, { speed: 1.2, life: 1.1, gravity: -2, glow: true }); }

  ring(pos, color = 0xff7a3a, opts = {}) {
    const { radius = 8, duration = .7, height = .08, width = .18, inner = 0 } = opts;
    const geo = new THREE.RingGeometry(.7, 1, 48);
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .85, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
    const m = new THREE.Mesh(geo, mat);
    m.rotation.x = -Math.PI / 2;
    m.position.set(pos.x, heightAt(pos.x, pos.z) + height, pos.z);
    this.scene.add(m);
    this.rings.push({ mesh: m, mat, t: 0, duration, radius });
  }
  swirl(pos, color = 0x9c5cff, radius = 7) {
    this.ring(pos, color, { radius, duration: 1.1, width: .35 });
  }

  arc(pos, yaw, range = 8, color = 0xff4a2a) {
    const geo = new THREE.RingGeometry(.8, 1, 32, 1, 0, Math.PI * 1.15);
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .8, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
    const m = new THREE.Mesh(geo, mat);
    m.rotation.x = -Math.PI / 2;
    m.rotation.z = -yaw - Math.PI * .575 + Math.PI / 2;
    m.position.set(pos.x, heightAt(pos.x, pos.z) + .1, pos.z);
    m.scale.setScalar(range);
    this.scene.add(m);
    this.arcs.push({ mesh: m, mat, t: 0, duration: .45, range });
  }

  telegraph(pos, radius, duration, color, onDone) {
    const y = heightAt(pos.x, pos.z) + .07;
    const disc = new THREE.Mesh(new THREE.CircleGeometry(radius, 30), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .18, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending }));
    disc.rotation.x = -Math.PI / 2; disc.position.set(pos.x, y, pos.z); this.scene.add(disc);
    const ring = new THREE.Mesh(new THREE.RingGeometry(radius * .9, radius, 32), new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .8, side: THREE.DoubleSide, depthWrite: false }));
    ring.rotation.x = -Math.PI / 2; ring.position.set(pos.x, y + .01, pos.z); this.scene.add(ring);
    this.telegraphs.push({ disc, ring, t: 0, duration, radius, color, onDone, pos: pos.clone() });
  }
  spikes(pos, color = 0x9c5cff, radius = 2.1) {
    const y = heightAt(pos.x, pos.z);
    for (let i = 0; i < 7; i++) {
      const a = (i / 7) * Math.PI * 2 + rand(-.3, .3);
      const r = rand(.2, radius * .7);
      const h = rand(1.4, 3.4);
      const spike = new THREE.Mesh(new THREE.ConeGeometry(rand(.14, .32), h, 5), new THREE.MeshStandardMaterial({ color: 0x3b2d3e, emissive: color, emissiveIntensity: .5, roughness: .8 }));
      spike.position.set(pos.x + Math.cos(a) * r, y + h / 2, pos.z + Math.sin(a) * r);
      spike.rotation.z = rand(-.2, .2);
      spike.scale.y = .02;
      this.scene.add(spike);
      this.spikes.push({ mesh: spike, t: 0, duration: .9, targetScale: 1 });
      this.sparks(new THREE.Vector3(spike.position.x, y + .4, spike.position.z), 3);
    }
  }
  rootRing(pos, color = 0xff7a3a) {
    const y = heightAt(pos.x, pos.z);
    for (let i = 0; i < 14; i++) {
      const a = (i / 14) * Math.PI * 2;
      const r = rand(4, 9);
      const spike = new THREE.Mesh(new THREE.ConeGeometry(.18, rand(1.2, 2.8), 4), new THREE.MeshStandardMaterial({ color: 0x3c2b20, emissive: color, emissiveIntensity: .25, roughness: 1 }));
      spike.position.set(pos.x + Math.cos(a) * r, y + .8, pos.z + Math.sin(a) * r);
      spike.rotation.z = rand(-.6, .6); spike.scale.y = .02;
      this.scene.add(spike); this.spikes.push({ mesh: spike, t: 0, duration: 1.0, targetScale: 1 });
    }
  }

  update(dt) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      p.v.y -= p.gravity * dt;
      p.mesh.position.addScaledVector(p.v, dt);
      p.v.multiplyScalar(1 - dt * .8);
      p.mat.opacity = Math.max(0, p.life / p.maxLife);
      p.mesh.scale.setScalar(p.size * Math.max(.2, p.life / p.maxLife));
      if (p.life <= 0) { this.scene.remove(p.mesh); p.mat.dispose(); this.particles.splice(i, 1); }
    }
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i]; r.t += dt;
      const p = r.t / r.duration;
      r.mesh.scale.setScalar(1 + p * r.radius);
      r.mat.opacity = Math.max(0, .85 * (1 - p));
      if (p >= 1) { this.scene.remove(r.mesh); r.mat.dispose(); this.rings.splice(i, 1); }
    }
    for (let i = this.arcs.length - 1; i >= 0; i--) {
      const a = this.arcs[i]; a.t += dt;
      const p = a.t / a.duration;
      a.mat.opacity = Math.max(0, .75 * (1 - p));
      a.mesh.scale.setScalar(a.range * (0.6 + p * .4));
      if (p >= 1) { this.scene.remove(a.mesh); a.mat.dispose(); this.arcs.splice(i, 1); }
    }
    for (let i = this.telegraphs.length - 1; i >= 0; i--) {
      const t = this.telegraphs[i]; t.t += dt;
      const p = Math.min(1, t.t / t.duration);
      t.disc.material.opacity = .12 + p * .22;
      t.ring.scale.setScalar(.86 + Math.sin(t.t * 12) * .03);
      t.ring.material.opacity = .5 + Math.sin(t.t * 10) * .3;
      if (p >= 1) {
        t.onDone?.();
        this.scene.remove(t.disc); this.scene.remove(t.ring);
        t.disc.geometry.dispose(); t.disc.material.dispose(); t.ring.geometry.dispose(); t.ring.material.dispose();
        this.telegraphs.splice(i, 1);
      }
    }
    for (let i = this.spikes.length - 1; i >= 0; i--) {
      const s = this.spikes[i]; s.t += dt;
      const p = Math.min(1, s.t / .2);
      s.mesh.scale.y = p * s.targetScale;
      if (s.t > s.duration) {
        s.mesh.position.y -= dt * 5;
        if (s.t > s.duration + .4) { this.scene.remove(s.mesh); s.mesh.geometry.dispose(); s.mesh.material.dispose(); this.spikes.splice(i, 1); }
      }
    }
  }
}

import * as THREE from 'three';
import { UI } from '../ui/ui.js';
import { Input } from '../core/input.js';
import { audio } from '../core/audio.js';
import { defaultState, loadState, saveState, hasSave, clearSave, saveSummary, loadSettings, saveSettings } from '../core/save.js';
import { buildRegion } from '../world/region1.js';
import { heightAt, ARENA, PATH } from '../world/terrain.js';
import { Player } from '../entities/player.js';
import { Enemy } from '../entities/enemy.js';
import { HollowWoodsman } from '../entities/boss.js';
import { NPC } from '../entities/npc.js';
import { IntroCinematic } from './intro.js';
import { Effects } from './effects.js';
import { WEAPONS, ARMOR, ITEMS, ENEMY_TYPES, ENDINGS, LORE, REGION_INFO } from './data.js';
import { clamp, lerp, damp, angleDelta, rand, choose, makeGlowSprite, formatTime } from '../core/utils.js';

export class Game {
  constructor(canvas) {
    this.canvas = canvas;
    this.audio = audio;
    this.input = new Input(canvas);
    this.ui = new UI(this);
    this.mode = 'loading';
    this.state = defaultState();
    this.uiBlocking = false;
    this.cinematic = false;
    this.bossIntro = null;
    this.bossIntroTime = 0;
    this.clock = new THREE.Clock();
    this.time = 0;
    this.playtime = 0;
    this.enemies = [];
    this.npcs = [];
    this.projectiles = [];
    this.lockTarget = null;
    this.lastInputX = 0; this.lastInputY = 0;
    this.hitstopTimer = 0;
    this.slowmoTimer = 0;
    this.slowmoScale = 1;
    this.shakeAmount = 0;
    this.combatLog = [];
    this.hasLocket = false;
    this.bloodstain = null;
    this.boss = null;
    this.intro = null;
    this.uiBlockingKind = null;
    this.attractTime = 0;
    this.settings = loadSettings();
    this.deathTimer = 0;
    this.deathScreenShown = false;
    this.rewardGiven = false;
    this.pendingRewards = [];
    this._lastPointerHint = 0;
    this.interactTarget = null;
    this.currentShrine = null;
    this.chapterEndingShown = false;
    this._hudHidden = false;
    this.resize = this.resize.bind(this);
    window.addEventListener('resize', this.resize);
    this.loop = this.loop.bind(this);
    this._lastTime = performance.now();
  }

  /* ============================================================
     INIT
  ============================================================ */
  async init() {
    this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true, powerPreference: 'high-performance', alpha: false });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.4));
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.12;
    this.renderer.shadowMap.enabled = false;

    this.scene = new THREE.Scene();
    this.scene.fog = new THREE.FogExp2(0x9aa49a, .0068);
    this.camera = new THREE.PerspectiveCamera(58, window.innerWidth / window.innerHeight, .08, 600);
    this.camera.position.set(0, 5, 100);

    const step = async (p, text, fn) => { this.ui.setLoading(p, text); await new Promise(r => setTimeout(r, 30)); fn?.(); };
    await step(.08, 'The kingdom remembers its shape…');
    await step(.22, 'Growing the First Grove…', () => { this.world = buildRegion(this.scene); });
    await step(.48, 'Casting the first shadows…', () => { this.effects = new Effects(this, this.scene); });
    await step(.62, 'Waking the hollow things…');
    // choose saved state for attract mode, but keep a pristine copy
    const saved = loadState();
    if (saved) this.state = saved;
    this.applyStateToPlayer(true);
    await step(.76, 'Lighting the shrines…', () => { this.resetActors(); });
    await step(.9, 'Sharpening the pipe…');
    await step(1, 'The crown is waiting.');
    this.ui.updateTitleSlot(hasSave(), saveSummary());
    this.ui.finishLoading();
    this.ui.showTitle();
    this.ui.hideHUD();
    this.mode = 'title';
    this.attractCamera = true;
    this.audio.setTheme('none');
    // expose for debugging / automated verification
    window.__HOLLOW_CROWN__ = this;
    requestAnimationFrame(this.loop);
  }

  resize() {
    if (!this.renderer) return;
    this.camera.aspect = window.innerWidth / window.innerHeight;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(window.innerWidth, window.innerHeight);
  }

  /* ============================================================
     STATE / PLAYER
  ============================================================ */
  applyStateToPlayer(fullHeal = true) {
    if (!this.player) {
      this.player = new Player(this, this.scene);
    }
    this.player.stats = this.state.player;
    this.player.setWeapon(this.state.player.equippedWeapon);
    this.player.setArmorVisual();
    this.player.recalcStats(fullHeal);
    if (!fullHeal) {
      this.player.hp = clamp(this.player.maxHp * (this.state.player.hpRatio ?? 1), this.player.maxHp * .25, this.player.maxHp);
      this.player.focus = this.player.maxFocus;
    }
    this.player.flaskUses = this.state.player.flaskUses ?? this.state.player.maxFlask;
    const pos = this.state.player.pos || { x: 7, z: 92 };
    this.player.pos.set(pos.x, heightAt(pos.x, pos.z), pos.z);
    this.player.yaw = this.state.player.yaw ?? Math.PI;
    this.player.pivot.rotation.set(0, 0, 0);
    this.player.root.position.copy(this.player.pos);
    this.player.root.rotation.y = this.player.yaw;
    this.ui.setMotes(this.state.player.motes);
    this.ui.setWeapon(WEAPONS[this.state.player.equippedWeapon]?.name || 'Metal Pipe');
    this.ui.setArmor(ARMOR[this.state.player.equippedArmor]?.name || 'Modern Hoodie');
    this.ui.setRegion(REGION_INFO.name, REGION_INFO.sub);
    this.ui.setObjective(this.objectiveText());
  }

  resetActors() {
    for (const e of this.enemies) e.dispose?.();
    this.enemies = [];
    if (this.boss) { this.boss.dispose?.(); this.boss = null; }
    for (const n of this.npcs) if (n.root?.parent) n.root.parent.remove(n.root);
    this.npcs = [];
    for (const p of this.projectiles) if (p.mesh.parent) p.mesh.parent.remove(p.mesh);
    this.projectiles = [];
    if (this.bloodstain?.mesh?.parent) this.bloodstain.mesh.parent.remove(this.bloodstain.mesh);
    this.bloodstain = null;
    this.lockTarget = null;
    this.hasLocket = false;

    // interactable states
    for (const c of this.world.chests) {
      const opened = this.state.openedChests?.includes(c.id);
      c.opened = !!opened;
      c.lid.rotation.x = opened ? -1.1 : -.08;
      c.glow.visible = !opened;
      c.group.userData.opened = !!opened;
    }
    for (const it of this.world.interactables) {
      if (it.kind === 'lore') {
        it.taken = this.state.lore.includes(it.id);
        it.group.visible = !it.taken;
      }
      if (it.kind === 'mote') {
        const idx = this.world.motes.indexOf(it);
        it.taken = this.state.collectedMotes?.includes('mote_' + idx);
        it.group.visible = !it.taken;
      }
    }
    for (let i = 0; i < this.world.motes.length; i++) {
      const m = this.world.motes[i];
      m.taken = this.state.collectedMotes?.includes('mote_' + i);
      m.group.visible = !m.taken;
    }
    this.world.locket.taken = this.hasLocket;
    this.world.locket.group.visible = this.state.quests.merchantQuest === 1 && !this.hasLocket;
    this.world.echo.group.visible = false;
    this.world.echo.taken = true;

    // enemies
    for (const sp of this.world.spawns) {
      if (sp.elite && this.state.flags.eliteDefeated) continue;
      this.spawnEnemy(sp.type, sp);
    }
    // boss
    if (!this.state.flags.bossDefeated) {
      this.boss = new HollowWoodsman(this);
      this.ui.hideBossBar();
      this.world.gate.group.visible = true;
      this.setGateColor(0xc7b6ff);
    } else {
      this.world.gate.group.visible = true;
      this.setGateColor(0x9fffe4);
    }
    // npcs
    for (const spot of this.world.npcSpots) this.npcs.push(new NPC(this, spot.id, spot.name, spot.x, spot.z, spot.yaw));
    if (this.state.flags.bossDefeated) this.createEcho();
    this.ui.setMotes(this.state.player.motes);
    if (this.bossIntro) { this.bossIntro = null; this.cinematic = false; this.ui.hideCinematic(); }
  }

  createEcho() {
    const echo = new NPC(this, 'echo', 'Malgraven, the Last Seer', 0, -98, 0);
    this.npcs.push(echo);
    this.echoNpc = echo;
    this.world.echo.group.visible = true;
  }

  setGateColor(color) {
    const g = this.world.gate;
    g.ring.material.color.setHex(color);
    g.glow.material.color.setHex(color);
    g.disc.material.color.setHex(color);
    g.group.children.forEach(c => { if (c.material?.color && c !== g.ring && c !== g.disc) c.material.color.setHex(color); });
  }

  /* ============================================================
     FLOW
  ============================================================ */
  startNewGame() {
    this.audio.init();
    this.audio.setTheme('title');
    this.state = defaultState();
    this.applyStateToPlayer(true);
    this.resetActors();
    this.mode = 'intro';
    this.ui.hideTitle();
    this.ui.showCinematic();
    this.ui.showCinematicTitle(true);
    this.ui.el['cinematic-title'].querySelector('p').textContent = 'Chapter I · The Forgotten Shire';
    this.ui.setCinematicLine('');
    this.intro = new IntroCinematic(this);
    this.introTime = 0;
    this.ui.el.fade.classList.add('on');
    this.ui.el.fade.style.opacity = '1';
    this.ui.setObjective('Find the First Shrine beneath the hollow tree.');
    this.player.respawn({ x: 7, z: 92 });
    this.player.invuln = 999;
    this.input.releaseLock();
    this.uiBlocking = false;
    this.cinematic = true;
    // hide title music overlay after 4s
    clearTimeout(this._titleTimer);
    this._titleTimer = setTimeout(() => this.ui.showCinematicTitle(false), 4200);
  }

  endIntro() {
    if (this.mode !== 'intro') return;
    clearTimeout(this._titleTimer);
    this.intro?.dispose();
    this.intro = null;
    this.mode = 'play';
    this.cinematic = false;
    this.ui.hideCinematic();
    this.ui.showHUD();
    this.ui.el.fade.classList.add('on');
    setTimeout(() => { this.ui.el.fade.classList.remove('on'); this.ui.el.fade.style.opacity = ''; }, 50);
    this.audio.setTheme('explore');
    this.state.flags.introSeen = true;
    this.player.invuln = 1.5;
    this.player.pos.set(7, heightAt(7, 92), 92);
    this.player.yaw = Math.PI;
    this.player.root.position.copy(this.player.pos);
    this.player.root.rotation.y = this.player.yaw;
    this.cameraRig.yaw = 0;
    this.cameraRig.pitch = .2;
    this.setCameraImmediate();
    this.ui.banner('THE FORGOTTEN SHIRE', 'Chapter I · Eldoria', 5200);
    this.ui.subtitle('You wake beneath a tree that was not there a moment ago. The rain has followed you.', 5);
    this.ui.setObjective(this.objectiveText());
    this.ui.hint('WASD to move · Mouse to look · Space to roll · Click to capture the mouse', 9);
    this.saveGame();
    this.updateTitleSlot();
  }

  continueGame() {
    const loaded = loadState();
    this.audio.init();
    if (loaded) this.state = loaded;
    else this.state = defaultState();
    this.ui.hideTitle();
    this.ui.showHUD();
    this.ui.el.fade.classList.add('on');
    setTimeout(() => { this.ui.el.fade.classList.remove('on'); }, 60);
    this.applyStateToPlayer(false);
    this.resetActors();
    this.mode = 'play';
    this.cinematic = false;
    this.uiBlocking = false;
    this.audio.setTheme('explore');
    const shrine = this.world.shrines.find(s => s.id === this.state.lastShrine) || this.world.shrines[0];
    if (shrine) {
      this.player.pos.set(shrine.x, heightAt(shrine.x, shrine.z + 3), shrine.z + 3);
      this.player.root.position.copy(this.player.pos);
    }
    this.cameraRig.yaw = this.player.yaw + Math.PI;
    this.cameraRig.pitch = .2;
    this.setCameraImmediate();
    this.ui.setObjective(this.objectiveText());
    this.ui.banner('THE FORGOTTEN SHIRE', 'You return to the last flame.', 4000);
    this.ui.hint('Click to capture the mouse', 5);
    this.setCameraImmediate();
    this.updateTitleSlot();
  }

  returnToTitle() {
    this.saveGame();
    this.mode = 'title';
    this.attractCamera = true;
    this.ui.showTitle();
    this.ui.hideHUD();
    this.ui.closeMenuUI();
    this.ui.hideEnding();
    this.uiBlocking = false;
    this.cinematic = false;
    this.input.releaseLock();
    this.audio.setTheme('title');
    this.lockTarget = null;
    this.updateTitleSlot();
    this.mode = 'title';
    this.player.respawn({ x: 7, z: 92 });
    this.player.invuln = 0;
  }

  updateTitleSlot() {
    this.ui.updateTitleSlot(hasSave(), saveSummary());
  }

  saveGame() {
    if (!this.player || this.mode === 'intro') return;
    this.state.player.pos = { x: this.player.pos.x, z: this.player.pos.z };
    this.state.player.yaw = this.player.yaw;
    this.state.player.hpRatio = clamp(this.player.hp / this.player.maxHp, .05, 1);
    this.state.player.flaskUses = this.player.stats.flaskUses;
    this.state.playtime = (this.state.playtime || 0) + this.playtime;
    this.playtime = 0;
    if (this.currentShrine) this.state.lastShrine = this.currentShrine;
    saveState(this.state);
  }

  saveAndQuit() {
    this.saveGame();
    this.returnToTitle();
    this.audio.ui();
  }

  /* ============================================================
     MAIN LOOP
  ============================================================ */
  loop(now) {
    requestAnimationFrame(this.loop);
    const raw = Math.min(.05, (now - this._lastTime) / 1000 || .016);
    this._lastTime = now;
    this.input.update();
    this.lastInputX = this.input.moveX; this.lastInputY = this.input.moveY;

    // real-time timers
    if (this.hitstopTimer > 0) this.hitstopTimer = Math.max(0, this.hitstopTimer - raw);
    if (this.slowmoTimer > 0) this.slowmoTimer = Math.max(0, this.slowmoTimer - raw);
    let dt = raw;
    if (this.hitstopTimer > 0) dt = raw * .03;
    else if (this.slowmoTimer > 0) dt = raw * this.slowmoScale;
    this.time += raw;

    if (this.mode === 'intro' && this.intro) {
      this.intro.update(raw);
      this.introTime += raw;
      if (this.input.skip && this.introTime > 1.2) this.intro.finish();
      this.ui.update(raw);
      this.renderer.render(this.intro.scene, this.intro.camera);
      this.input.endFrame();
      return;
    }

    if (this.mode === 'title') {
      this.updateTitleScene(raw);
      this.ui.update(raw);
      this.renderer.render(this.scene, this.camera);
      this.input.endFrame();
      return;
    }

    if (this.mode === 'ending') {
      this.updateSceneAmbient(raw);
      this.ui.update(raw);
      this.renderer.render(this.scene, this.camera);
      this.input.endFrame();
      return;
    }

    if (this.mode === 'dead') {
      this.deathTimer += raw;
      this.updateSceneAmbient(raw);
      if (this.boss && this.boss.active) this.boss.update(dt, this.player);
      this.player.updateDeath(raw);
      this.updateProjectiles(dt);
      this.effects.update(dt);
      this.updateCamera(dt);
      this.ui.update(raw);
      this.ui.updateEnemyBars(this.enemies);
      if (!this.deathScreenShown && this.deathTimer > 1.4) {
        this.deathScreenShown = true;
        const lost = this._lostMotes || 0;
        this.ui.showDeath(lost, this.deathLine());
      }
      this.renderer.render(this.scene, this.camera);
      this.input.endFrame();
      return;
    }

    // play / boss intro
    if (this.uiBlocking) {
      if (this.ui.currentMenu && (this.input.pause || this.input.confirm)) {
        if (this.input.pause) this.closeMenu();
      }
      this.updateSceneAmbient(raw);
      this.ui.update(raw);
      this.ui.updateEnemyBars(this.enemies);
      this.renderer.render(this.scene, this.camera);
      this.input.endFrame();
      return;
    }

    if (this.bossIntro) {
      this.updateBossIntro(raw);
      this.updateSceneAmbient(raw);
      this.boss?.update(raw, this.player);
      this.player.animTime += raw; this.player.animate(raw);
      this.ui.update(raw);
      this.renderer.render(this.scene, this.camera);
      this.input.endFrame();
      return;
    }

    if (this.cinematic) {
      this.updateSceneAmbient(raw);
      this.ui.update(raw);
      this.renderer.render(this.scene, this.camera);
      this.input.endFrame();
      return;
    }

    // handle pause quickly (player also handles, but this is reliable)
    if (this.input.pause) { this.openPause(); this.input.endFrame(); return; }

    this.playtime += raw;
    this.player.update(dt, this.input, this.cameraRig.yaw, this.ui);
    this.updateLock();
    for (const e of this.enemies) if (e.alive || e.deathTimer < 5.2) e.update(dt, this.player);
    if (this.boss) this.boss.update(dt, this.player);
    this.updateProjectiles(dt);
    this.effects.update(dt);
    this.world.update(this.time, raw);
    this.updatePickups();
    this.updateInteract();
    this.updateCamera(dt);
    this.updateBossTriggers();
    this.ui.update(raw);
    this.ui.updateVitals(this.player);
    this.ui.updateEnemyBars(this.enemies);
    this.ui.updateFloatTexts(raw);
    if (this.boss && this.boss.active) this.ui.updateBossBar();
    if (this.ui.eliteRef) this.ui.updateEliteBar();
    if (this.lockTarget) this.ui.showLock(this.lockTarget.pos.clone().add(new THREE.Vector3(0, this.lockTarget.isBoss ? 4 : 1.4, 0)));
    else this.ui.showLock(null);
    this.updateContextual();
    this.renderer.render(this.scene, this.camera);
    this.input.endFrame();
  }

  updateSceneAmbient(raw) {
    this.world.update(this.time, raw);
    for (const e of this.enemies) if (!e.alive) e.updateDeath(raw);
    if (this.boss && this.boss.dead) this.boss.updateDeath(raw);
    for (const n of this.npcs) n.update(raw, this.time);
    this.player.animTime += raw;
    if (this.mode !== 'dead') this.player.animate(raw);
    this.effects.update(raw);
  }

  updateTitleScene(raw) {
    this.attractTime += raw;
    this.world.update(this.time, raw);
    for (const n of this.npcs) n.update(raw, this.time);
    if (this.player) { this.player.animTime += raw; this.player.animate(raw); }
    const a = .35 + Math.sin(this.attractTime * .04) * .3;
    const target = new THREE.Vector3(-2, 2.4, 76);
    const r = 16;
    const x = target.x + Math.cos(a) * r;
    const z = target.z + Math.sin(a) * r;
    const y = 4.8 + Math.sin(this.attractTime * .15) * .5;
    this.camera.position.set(x, y, z);
    this.camera.lookAt(target);
    this.camera.fov = 52;
    this.camera.updateProjectionMatrix();
  }

  /* ============================================================
     CAMERA
  ============================================================ */
  get cameraRig() {
    if (!this._rig) this._rig = { yaw: 0, pitch: .2, distance: 5.9 };
    return this._rig;
  }

  updateCamera(dt) {
    if (this.intro) return;
    if (this.bossIntro) return;
    const rig = this.cameraRig;
    const p = this.player;
    if (!p) return;
    // mouse / stick look
    if (this.input.pointerLocked) {
      rig.yaw -= this.input.mouseDX * this.input.sensitivity * (this.settings.sensitivity || 1);
      rig.pitch += this.input.mouseDY * this.input.sensitivity * (this.settings.sensitivity || 1) * 1.1;
    }
    if (this.input.lookX) rig.yaw -= this.input.lookX * dt * 2.6;
    if (this.input.lookY) rig.pitch += this.input.lookY * dt * 1.6;
    rig.pitch = clamp(rig.pitch, .03, .72);

    const target = p.pos.clone().add(new THREE.Vector3(0, 1.62, 0));
    let dist = rig.distance;
    if (this.input.sprintHeld && (p.vel.x || p.vel.z) && !this.lockTarget) dist += .35;

    if (this.lockTarget && this.lockTarget.alive) {
      const t = this.lockTarget;
      const desired = Math.atan2(t.pos.x - p.pos.x, t.pos.z - p.pos.z) + Math.PI;
      rig.yaw = dampAngle(rig.yaw, desired, 5, dt);
      rig.pitch = damp(rig.pitch, t.isBoss ? .18 : .22, 3, dt);
      const targetPos = t.pos.clone().add(new THREE.Vector3(0, t.isBoss ? 4.2 : 1.1, 0));
      target.lerp(targetPos, .22);
    } else if (!this.input.pointerLocked && !p.sprinting && !(this.input.moveX || this.input.moveY)) {
      // gentle auto follow when idle without pointer lock
    }
    const horiz = Math.cos(rig.pitch) * dist;
    const off = new THREE.Vector3(Math.sin(rig.yaw) * horiz, Math.sin(rig.pitch) * dist + .35, Math.cos(rig.yaw) * horiz);
    let desiredPos = target.clone().add(off);
    // camera collision-ish
    const ground = heightAt(desiredPos.x, desiredPos.z);
    if (desiredPos.y < ground + .7) desiredPos.y = ground + .7;
    for (const c of this.world.colliders) {
      const dx = desiredPos.x - c.x, dz = desiredPos.z - c.z;
      if (Math.hypot(dx, dz) < c.r + .35) {
        const d = Math.hypot(dx, dz) || 1;
        desiredPos.x = c.x + dx / d * (c.r + .4);
        desiredPos.z = c.z + dz / d * (c.r + .4);
        desiredPos.y = Math.max(desiredPos.y, ground + 1.2);
      }
    }
    this.shakeAmount = Math.max(0, this.shakeAmount - dt * 2.5);
    if (this.shakeAmount > 0) {
      desiredPos.x += (Math.random() - .5) * this.shakeAmount;
      desiredPos.y += (Math.random() - .5) * this.shakeAmount;
      desiredPos.z += (Math.random() - .5) * this.shakeAmount;
    }
    this.camera.position.lerp(desiredPos, 1 - Math.exp(-10 * dt));
    const look = target.clone();
    if (this.lockTarget && this.lockTarget.alive) {
      look.lerp(this.lockTarget.pos.clone().add(new THREE.Vector3(0, this.lockTarget.isBoss ? 4.2 : 1.2, 0)), .55);
    }
    this.camera.lookAt(look);
    this.camera.fov = lerp(this.camera.fov, 58, 1 - Math.exp(-4 * dt));
    this.camera.updateProjectionMatrix();
    this.cameraRig.yaw = rig.yaw;
  }

  setCameraImmediate() {
    const rig = this.cameraRig;
    const p = this.player;
    if (!p) return;
    const target = p.pos.clone().add(new THREE.Vector3(0, 1.62, 0));
    const horiz = Math.cos(rig.pitch) * rig.distance;
    const off = new THREE.Vector3(Math.sin(rig.yaw) * horiz, Math.sin(rig.pitch) * rig.distance + .35, Math.cos(rig.yaw) * horiz);
    this.camera.position.copy(target.clone().add(off));
    this.camera.lookAt(target);
    this.camera.fov = 58; this.camera.updateProjectionMatrix();
  }

  shake(a) { this.shakeAmount = Math.max(this.shakeAmount, a); }
  hitstop(t) { this.hitstopTimer = Math.max(this.hitstopTimer, t); }
  slowmo(scale, dur) { this.slowmoScale = scale; this.slowmoTimer = dur; }

  /* ============================================================
     BOSS ENCOUNTER
  ============================================================ */
  updateBossTriggers() {
    if (!this.boss || this.state.flags.bossDefeated || this.bossIntro) return;
    const d = Math.hypot(this.player.pos.x - ARENA.x, this.player.pos.z - ARENA.z);
    if (d < ARENA.r - 1 || this.player.pos.z < -74) this.beginBossEncounter();
  }

  beginBossEncounter() {
    if (!this.boss || this.state.flags.bossDefeated || this.bossIntro) return;
    this.bossIntro = { t: 0 };
    this.bossIntro.t = 0;
    this.cinematic = true;
    this.input.releaseLock();
    this.lockTarget = null;
    this.boss.beginIntro();
    this.ui.showCinematic();
    this.ui.setCinematicLine('<span style="font-family:var(--serif);font-size:30px;letter-spacing:.18em;font-style:normal;color:#e7cd92">THE HOLLOW WOODSMAN</span><br><span style="font-size:12px;letter-spacing:.28em;color:#9d917b">KEEPER OF THE FIRST GROVE</span>');
    this.ui.setObjective('Defeat the Hollow Woodsman.');
    this.audio.setTheme('boss');
    this.audio.roar();
    this.shake(.4);
  }

  updateBossIntro(raw) {
    const bi = this.bossIntro;
    if (!bi) return;
    bi.t += raw;
    this.bossIntroTime = bi.t;
    const boss = this.boss;
    // camera orbit around the boss
    const t = bi.t;
    const k = clamp(t / 7.5, 0, 1);
    const angle = -0.55 + k * 1.35;
    const radius = 19 - k * 8;
    const pos = boss.pos.clone().add(new THREE.Vector3(Math.sin(angle) * radius, 5.5 + Math.sin(k * Math.PI) * 3, Math.cos(angle) * radius));
    pos.y = Math.max(pos.y, heightAt(pos.x, pos.z) + 1.2);
    this.camera.position.lerp(pos, 1 - Math.exp(-2.5 * raw));
    this.camera.lookAt(boss.pos.clone().add(new THREE.Vector3(0, 4.4, 0)));
    this.camera.fov = lerp(this.camera.fov, 46, 1 - Math.exp(-2 * raw));
    this.camera.updateProjectionMatrix();
    if (t > 4.9 && !boss.active) {
      boss.activate();
      this.ui.setCinematicLine('<span style="font-family:var(--serif);font-size:22px;letter-spacing:.2em;font-style:normal;color:#e7cd92">THE GROVE HAS NOT FORGOTTEN YOU.</span>');
      this.audio.roar();
      this.shake(.7);
    }
    if (t > 7.4 || (this.input.skip && t > 1)) {
      if (!boss.active) boss.activate();
      this.endBossIntro();
    }
  }

  endBossIntro() {
    this.bossIntro = null;
    this.cinematic = false;
    this.ui.hideCinematic();
    this.ui.showHUD();
    this.ui.setObjective('Defeat the Hollow Woodsman.');
    this.ui.hint('Lock on with Tab · Roll through his attacks · Punish after the tree flares', 7);
    this.cameraRig.yaw = Math.atan2(this.boss.pos.x - this.player.pos.x, this.boss.pos.z - this.player.pos.z) + Math.PI;
    this.setCameraImmediate();
    this.audio.setTheme('boss');
    this.input.requestLock();
  }

  /* ============================================================
     INTERACTION / PICKUPS
  ============================================================ */
  updatePickups() {
    const p = this.player;
    for (let i = 0; i < this.world.motes.length; i++) {
      const m = this.world.motes[i];
      if (m.taken) continue;
      if (Math.hypot(p.pos.x - m.x, p.pos.z - m.z) < 2.2) {
        m.taken = true; m.group.visible = false;
        if (!this.state.collectedMotes) this.state.collectedMotes = [];
        this.state.collectedMotes.push('mote_' + i);
        this.addMotes(m.amount, m.group.position);
        this.audio.pickup();
      }
    }
    if (this.world.locket && !this.world.locket.taken && this.state.quests.merchantQuest === 1) {
      const l = this.world.locket;
      if (Math.hypot(p.pos.x - l.x, p.pos.z - l.z) < 2.4) {
        l.taken = true; l.group.visible = false; this.hasLocket = true;
        this.state.quests.merchantQuest = 2;
        this.ui.toast('Wren\'s Locket recovered', 'gold');
        this.ui.floatText(l.group.position, 'WREN\'S LOCKET', 'item');
        this.audio.pickup();
      }
    }
    if (this.bloodstain) {
      const b = this.bloodstain;
      if (Math.hypot(p.pos.x - b.x, p.pos.z - b.z) < 2.4) {
        this.addMotes(b.amount, b.mesh.position);
        this.ui.toast(`Recovered ${b.amount} motes`, 'gold');
        this.audio.souls();
        if (b.mesh.parent) b.mesh.parent.remove(b.mesh);
        this.bloodstain = null;
      }
    }
  }

  updateInteract() {
    const p = this.player;
    let best = null, bd = 1e9;
    const consider = (obj, radius, text, action) => {
      const d = Math.hypot(p.pos.x - obj.x, p.pos.z - obj.z);
      if (d < radius && d < bd) { bd = d; best = { obj, text, action }; }
    };
    for (const n of this.npcs) consider(n, 3.2, `Speak with ${n.id === 'marrow' ? 'Marrow' : n.id === 'wisp' ? 'the Wisp' : 'the Seer\'s Echo'}`, () => this.openDialogue(n));
    for (const s of this.world.shrines) consider(s, 4.4, `Rest at ${s.name}`, () => this.openShrine(s));
    for (const c of this.world.chests) if (!c.opened) consider(c, 2.9, 'Open the chest', () => this.openChest(c));
    for (const l of this.world.interactables) if (l.kind === 'lore' && !l.taken) consider(l, 2.7, 'Read the recovered page', () => this.readLore(l));
    if (this.world.gate.group.visible) {
      const g = this.world.gate;
      consider(g, 4.8, this.state.flags.bossDefeated ? 'Touch the Weeping Gate' : 'Enter the First Grove', () => this.useGate());
    }
    if (this.bloodstain) consider(this.bloodstain, 2.8, 'Recover your lost motes', () => {
      this.addMotes(this.bloodstain.amount, this.bloodstain.mesh.position);
      this.audio.souls();
      if (this.bloodstain.mesh.parent) this.bloodstain.mesh.parent.remove(this.bloodstain.mesh);
      this.bloodstain = null;
    });
    this.interactTarget = best;
    this.ui.setInteract(best ? best.text : null);
    if (this.input.interact && best) { best.action(); this.input.consumePressed('KeyE'); this.input.consumePressed('GP2'); }
  }

  tryInteract() {
    if (this.interactTarget) this.interactTarget.action();
  }

  openChest(chest) {
    if (chest.opened) return;
    chest.opened = true;
    chest.lid.rotation.x = -1.1;
    chest.glow.visible = false;
    if (!this.state.openedChests) this.state.openedChests = [];
    this.state.openedChests.push(chest.id);
    this.audio.pickup();
    this.ui.toast('Chest opened', 'gold');
    const loot = {
      chest_sword: () => { this.addWeapon('rustySword'); this.addMotes(160); },
      chest_armor: () => { this.addArmor('leather'); this.addItem('emberBomb', 2); },
      chest_greatsword: () => { this.addWeapon('greatsword'); },
      chest_staff: () => { this.addWeapon('staff'); this.unlockSpell(); this.addItem('emberBomb', 1); },
    }[chest.id];
    loot?.();
  }

  readLore(obj) {
    if (obj.taken) return;
    obj.taken = true; obj.group.visible = false;
    if (!this.state.lore.includes(obj.id)) this.state.lore.push(obj.id);
    this.audio.pickup();
    const lore = LORE.find(l => l.id === obj.id);
    this.ui.toast(`Recovered: ${lore?.title || 'a torn page'}`, 'gold');
    this.ui.floatText(obj.group.position, 'PAGE RECOVERED', 'item');
    if (this.state.lore.length === 3) {
      this.ui.toast('The truth stirs. The Wisp will want to speak with you.', 'gold');
      this.ui.banner('THE VEIL THINS', 'Three pages of Eldoria\'s truth recovered. A third path is now visible.', 5000);
    }
    this.openLoreUI(obj.id);
  }

  openLoreUI(id) {
    this.uiBlocking = true;
    this.uiBlockingKind = 'menu';
    this.input.releaseLock();
    this.ui.showLore(id);
    this.ui.currentMenu = { title: 'LORE', lore: true };
  }

  openDialogue(npc) {
    this.uiBlocking = true;
    this.uiBlockingKind = 'dialogue';
    this.input.releaseLock();
    this.ui.openDialogue(npc);
    this.audio.ui();
  }
  closeDialogue() {
    this.uiBlocking = false;
    this.uiBlockingKind = null;
    this.ui.dialogueState = null;
    this.ui.el.dialogue.classList.add('hidden');
  }
  dialogueAction(action, npc) {
    if (action === 'close') { this.ui.closeDialogue(); return; }
    if (action === 'shop') { this.ui.closeDialogue(); this.openShop(); return; }
    if (action === 'quest_accept') {
      this.state.quests.merchantQuest = 1;
      this.world.locket.group.visible = true;
      this.ui.toast('Quest accepted: A Silver Bird', 'gold');
      this.ui.setObjective('Find Wren\'s locket by the graves west of the village.');
      this.saveGame();
      this.ui.closeDialogue(); return;
    }
    if (action === 'quest_complete') {
      if (!this.hasLocket) { this.ui.closeDialogue(); return; }
      this.state.quests.merchantQuest = 3;
      this.addMotes(600);
      this.addArmor('leather');
      this.ui.toast('Quest complete: A Silver Bird', 'gold');
      this.ui.toast('Received Traveler\'s Jerkin', 'gold');
      this.ui.banner('A SMALL KINDNESS', 'Marrow will remember this.', 4000);
      this.ui.setObjective(this.objectiveText());
      this.saveGame();
      this.ui.closeDialogue(); return;
    }
    if (action === 'endings') {
      this.ui.closeDialogue();
      this.openEndings();
      return;
    }
  }

  openShrine(shrine) {
    this.uiBlocking = true;
    this.uiBlockingKind = 'menu';
    this.input.releaseLock();
    this.currentShrine = shrine.id;
    const body = `
      <div class="menu-columns">
        <div>
          <div class="panel-title">${shrine.name.toUpperCase()}</div>
          <p style="font-size:14px;line-height:1.65;color:#a99e88;font-style:italic">The flame bends toward you. Somewhere beneath the ash, something old is listening.</p>
          <div class="stat-row" style="margin-top:16px"><span>Level</span><b>${this.state.player.level}</b></div>
          <div class="stat-row"><span>Motes</span><b>${Math.floor(this.state.player.motes).toLocaleString('en-US')}</b></div>
          <div class="stat-row"><span>Flask</span><b>${this.player?.stats.flaskUses ?? 0} / ${this.state.player.maxFlask}</b></div>
          <div class="stat-row"><span>Deaths</span><b>${this.state.deaths}</b></div>
          <div class="panel-title" style="margin-top:22px">REST</div>
          <p style="font-size:12px;line-height:1.6;color:#857d6d;font-style:italic">Resting restores health and flask charges, and calls the hollow things back to their places. All ordinary enemies will return.</p>
        </div>
        <div>
          <div class="panel-title">THE FLAME</div>
          <div class="shrine-actions">
            <button class="menu-btn primary" data-sh="rest">REST &amp; SAVE</button>
            <button class="menu-btn" data-sh="level">LEVEL UP</button>
            <button class="menu-btn" data-sh="leave">LEAVE</button>
          </div>
          <p class="shrine-note">“The shrine remembers. That is all a shrine can do.”</p>
        </div>
      </div>`;
    this.ui.openMenu(shrine.name.toUpperCase(), body, `<span>${this.objectiveText()}</span><span>E to close</span>`, true);
    this.ui.el['menu-body'].querySelector('[data-sh="rest"]').addEventListener('click', () => this.restAtShrine(shrine));
    this.ui.el['menu-body'].querySelector('[data-sh="level"]').addEventListener('click', () => { this.ui.showLevelUp(); });
    this.ui.el['menu-body'].querySelector('[data-sh="leave"]').addEventListener('click', () => this.closeMenu());
    this.audio.ui();
  }

  restAtShrine(shrine) {
    this.currentShrine = shrine.id;
    this.state.lastShrine = shrine.id;
    this.state.flags.firstShrine = true;
    this.player.hp = this.player.maxHp;
    this.player.stamina = this.player.maxStamina;
    this.player.focus = this.player.maxFocus;
    this.player.stats.flaskUses = this.state.player.maxFlask;
    this.state.player.hpRatio = 1;
    this.player.pos.set(shrine.x, heightAt(shrine.x, shrine.z + 3.3), shrine.z + 3.3);
    this.player.root.position.copy(this.player.pos);
    this.player.vel.set(0, 0, 0);
    this.resetEnemiesOnly();
    if (this.boss && !this.state.flags.bossDefeated) this.resetBoss();
    this.state.player.pos = { x: this.player.pos.x, z: this.player.pos.z };
    this.saveGame();
    this.ui.closeMenuUI();
    this.uiBlocking = false;
    this.uiBlockingKind = null;
    this.ui.banner(shrine.name.toUpperCase(), 'The flame is lit. You are restored.', 4000);
    this.ui.toast('Game saved', 'gold');
    this.audio.levelup();
    this.ui.setObjective(this.objectiveText());
    this.input.requestLock();
  }

  resetEnemiesOnly() {
    for (const e of this.enemies) e.dispose?.();
    this.enemies = [];
    for (const sp of this.world.spawns) {
      if (sp.elite && this.state.flags.eliteDefeated) continue;
      this.spawnEnemy(sp.type, sp);
    }
    this.ui.hideEliteBar();
  }

  levelUp(attr) {
    const cost = this.levelCost();
    const s = this.state.player;
    if (s.motes < cost) { this.ui.toast('Not enough motes', 'blood'); return false; }
    s.motes -= cost;
    s[attr]++;
    s.level++;
    this.player.recalcStats(false);
    this.player.hp = Math.min(this.player.maxHp, this.player.hp + this.player.maxHp * .18);
    this.ui.setMotes(s.motes);
    this.audio.levelup();
    this.ui.toast(`Level ${s.level} · ${attr.toUpperCase()} increased`, 'gold');
    this.saveGame();
