468:   drawMap(cv) {
469:     const g = this.game;
470:     const rect = cv.getBoundingClientRect();
471:     const dpr = Math.min(2, window.devicePixelRatio || 1);
472:     cv.width = rect.width * dpr; cv.height = rect.height * dpr;
473:     const ctx = cv.getContext('2d');
474:     ctx.scale(dpr, dpr);
475:     const w = rect.width, h = rect.height;
476:     const toMap = (x, z) => [w * .5 + x / 250 * w * .9, h * .5 + z / 250 * h * .9];
477:     // parchment bg
478:     const grad = ctx.createRadialGradient(w * .45, h * .4, 10, w * .5, h * .5, w * .7);
479:     grad.addColorStop(0, '#231f18'); grad.addColorStop(1, '#0c0b0d');
480:     ctx.fillStyle = grad; ctx.fillRect(0, 0, w, h);
481:     // noise
482:     for (let i = 0; i < 240; i++) { ctx.fillStyle = `rgba(201,164,92,${Math.random() * .035})`; ctx.fillRect(Math.random() * w, Math.random() * h, 1, 1); }
483:     // forest blobs
484:     ctx.fillStyle = 'rgba(52,68,45,.5)';
485:     for (const [cx, cz, r] of [[-48, 25, 36], [-60, -20, 32], [40, 10, 30], [55, 55, 26], [-40, 70, 22], [48, -45, 30]]) {
486:       const [x, y] = toMap(cx, cz);
487:       ctx.beginPath(); ctx.arc(x, y, r / 250 * w, 0, Math.PI * 2); ctx.fill();
488:     }
489:     // arena
490:     const [ax, ay] = toMap(ARENA.x, ARENA.z);
491:     ctx.strokeStyle = 'rgba(156,92,255,.4)'; ctx.lineWidth = 1;
492:     ctx.beginPath(); ctx.arc(ax, ay, ARENA.r / 250 * w, 0, Math.PI * 2); ctx.stroke();
493:     ctx.fillStyle = 'rgba(90,44,120,.18)'; ctx.fill();
494:     // path
495:     ctx.strokeStyle = 'rgba(201,164,92,.5)'; ctx.lineWidth = 2.2; ctx.setLineDash([5, 7]);
496:     ctx.beginPath();
497:     PATH.forEach(([x, z], i) => { const [mx, my] = toMap(x, z); i ? ctx.lineTo(mx, my) : ctx.moveTo(mx, my); });
498:     ctx.stroke(); ctx.setLineDash([]);
499:     // landmarks
500:     const dot = (x, z, color, r = 3, label = '') => {
501:       const [mx, my] = toMap(x, z);
502:       ctx.fillStyle = color; ctx.beginPath(); ctx.arc(mx, my, r, 0, Math.PI * 2); ctx.fill();
503:       if (label) { ctx.font = '9px Georgia'; ctx.fillStyle = 'rgba(220,210,190,.6)'; ctx.textAlign = 'center'; ctx.fillText(label, mx, my - 7); }
504:     };
505:     for (const sh of g.world.shrines) dot(sh.x, sh.z, '#c9a45c', 3.5, sh.id === 'tree' ? 'SHRINE' : '');
506:     for (const ch of g.world.chests) { const [mx, my] = toMap(ch.x, ch.z); ctx.fillStyle = '#b0733d'; ctx.fillRect(mx - 2, my - 2, 4, 4); }
507:     for (const npc of g.npcs) dot(npc.x, npc.z, '#8fb0d8', 2.5, npc.id === 'marrow' ? 'MARROW' : '');
508:     const [gx, gy] = toMap(0, -102); ctx.fillStyle = 'rgba(160,60,60,.9)'; ctx.font = '13px Georgia'; ctx.textAlign = 'center'; ctx.fillText('☠', gx, gy);
509:     // player
510:     const [px, py] = toMap(g.player.pos.x, g.player.pos.z);
511:     ctx.save(); ctx.translate(px, py); ctx.rotate(-g.player.yaw);
512:     ctx.fillStyle = '#f0e6d0'; ctx.beginPath(); ctx.moveTo(0, -7); ctx.lineTo(4.5, 5); ctx.lineTo(0, 3); ctx.lineTo(-4.5, 5); ctx.closePath(); ctx.fill();
513:     ctx.restore();
514:     ctx.strokeStyle = 'rgba(231,205,146,.35)'; ctx.beginPath(); ctx.arc(px, py, 10, 0, Math.PI * 2); ctx.stroke();
515:     // compass
516:     ctx.fillStyle = 'rgba(201,164,92,.65)'; ctx.font = '10px Georgia'; ctx.textAlign = 'center'; ctx.fillText('N', w / 2, 16);
517:     ctx.beginPath(); ctx.moveTo(w / 2, 20); ctx.lineTo(w / 2 - 3, 28); ctx.lineTo(w / 2 + 3, 28); ctx.closePath(); ctx.fill();
518:   }
