561:   openDialogue(npc) {
562:     const data = npc.dialogue();
563:     if (!data) return;
564:     this.dialogueState = { npc, data, node: data.nodes[data.startNode] };
565:     this.el.dialogue.classList.remove('hidden');
566:     this.el['dialogue-name'].textContent = npc.name;
567:     this.el['dialogue-portrait'].textContent = npc.id === 'marrow' ? '☾' : npc.id === 'wisp' ? '✦' : '◉';
568:     this.el['dialogue-hint'].textContent = '[E] continue · [1-4] choose · [ESC] leave';
569:     this.renderDialogue();
570:   }
571:   renderDialogue() {
572:     const st = this.dialogueState;
573:     if (!st) return;
574:     const node = st.node;
575:     this.el['dialogue-text'].textContent = node.text;
576:     const opts = this.el['dialogue-options'];
577:     opts.innerHTML = '';
578:     if (node.options && node.options.length) {
579:       node.options.forEach((o, i) => {
580:         if (o.condition && !o.condition()) return;
581:         const b = document.createElement('button');
582:         b.className = 'dialogue-option';
583:         b.textContent = `${i + 1}. ${o.label}`;
584:         b.addEventListener('click', () => this.chooseDialogue(o));
585:         opts.appendChild(b);
586:       });
587:     } else {
588:       const b = document.createElement('button');
589:       b.className = 'dialogue-option';
590:       b.textContent = 'Continue';
591:       b.addEventListener('click', () => this.closeDialogue());
592:       opts.appendChild(b);
593:     }
594:   }
595:   chooseDialogue(option) {
596:     const st = this.dialogueState;
597:     if (!st) return;
598:     this.game.audio.ui();
599:     if (option.next) { const n = st.data.nodes[option.next]; if (n) { st.node = n; this.renderDialogue(); return; } }
600:     if (option.action) { this.game.dialogueAction(option.action, st.npc); return; }
