298:     this.staggerTime = Math.max(0, this.staggerTime - dt);
299:     this.poiseBuildup = Math.max(0, this.poiseBuildup - dt * 8);
300: 
301:     const controls = !this.game.uiBlocking && !this.game.cinematic;
302:     this.blocking = false;
303: 
304:     if (this.staggerTime > 0) {
305:       this.state = 'stagger';
306:       this.applyPhysics(dt, 0, 0);
307:       this.animate(dt);
308:       this.updateMaterialFlash();
309:       return;
310:     }
311: 
312:     // actions
313:     if (controls) {
314:       if (input.pause) this.game.openPause();
315:       if (input.lockPressed) this.game.toggleLock();
316:       if (input.weaponNext) this.game.cycleWeapon(1);
317:       if (input.weaponPrev) this.game.cycleWeapon(-1);
318:       if (input.inventory) this.game.openInventory();
319:       if (input.map) this.game.openMap();
320:       if (input.interact) this.game.tryInteract();
321:       if (input.heal) this.tryHeal();
322:       if (input.spell) this.trySpell();
323:     }
324: 
325:     const canAct = !this.busy && this.state !== 'roll' && this.state !== 'heal' && this.state !== 'cast' && this.state !== 'crit' && this.state !== 'hit';
326: 
327:     if (controls && canAct) {
328:       if (input.attackLight) this.beginAttack('light');
329:       else if (input.attackHeavy) this.beginAttack('heavy');
330:       else if (input.critical) this.game.tryCritical();
331:       else if (input.dodge) this.beginRoll();
332:       else if (input.jump && this.grounded) this.jump();
333:       if (input.blockHeld) { this.blocking = true; if (input.blockPressed) this.parryWindow = .3; }
334:     } else if (controls && input.blockHeld && !this.busy) {
335:       this.blocking = true;
336:     }
337: 
338:     // movement
339:     let mx = input.moveX, my = input.moveY;
340:     let moveSpeed = 4.35 * this.speedMult;
341:     this.sprinting = false;
342:     if (input.sprintHeld && (mx || my) && this.stamina > 4 && !this.blocking && this.grounded) { moveSpeed = 7.75 * this.speedMult; this.sprinting = true; }
343: 
344:     if (this.state === 'idle' || this.state === 'move' || this.state === 'block') {
345:       this.state = (Math.abs(mx) + Math.abs(my) > .05) ? 'move' : 'idle';
346:     }
347: 
348:     if (this.state === 'attack') {
349:       this.updateAttack(dt);
350:       moveSpeed *= .18;
351:     } else if (this.state === 'roll') {
352:       this.updateRoll(dt);
353:       mx = 0; my = 0;
354:     } else if (this.state === 'heal') {
355:       this.updateHeal(dt);
356:       moveSpeed *= .25;
357:     } else if (this.state === 'cast') {
358:       this.updateCast(dt);
359:       moveSpeed *= .2;
360:     } else if (this.state === 'crit') {
361:       this.updateCrit(dt);
362:       moveSpeed *= .1;
363:     }
364:     if (this.blocking) moveSpeed *= .48;
365: 
366:     // sprint stamina
367:     if (this.sprinting && (mx || my)) {
368:       this.stamina = Math.max(0, this.stamina - 12 * dt);
369:       this.staminaDelay = .7;
370:     } else if (this.state !== 'roll' && this.state !== 'attack') {
371:       this.staminaDelay = Math.max(0, this.staminaDelay - dt);
372:       if (this.staminaDelay <= 0) {
373:         const regen = (16 + this.stats.endurance * .35) * (this.blocking ? .55 : 1) * (this.armor.weight > 2 ? .8 : 1);
374:         this.stamina = Math.min(this.maxStamina, this.stamina + regen * dt);
375:       }
376:     }
377:     // focus regen slowly
378:     this.focus = Math.min(this.maxFocus, this.focus + .6 * dt);
379: 
380:     // turning / movement direction
381:     let dirX = 0, dirZ = 0;
382:     if (mx || my) {
383:       const fwdX = -Math.sin(cameraYaw), fwdZ = -Math.cos(cameraYaw);
384:       const rightX = Math.cos(cameraYaw), rightZ = -Math.sin(cameraYaw);
385:       dirX = fwdX * my + rightX * mx;
386:       dirZ = fwdZ * my + rightZ * mx;
387:       const l = Math.hypot(dirX, dirZ) || 1; dirX /= l; dirZ /= l;
388:     }
389:     const lock = this.game.lockTarget;
390:     if (lock && lock.alive && !lock.isBoss) {
391:       const dx = lock.pos.x - this.pos.x, dz = lock.pos.z - this.pos.z;
392:       const targetYaw = Math.atan2(dx, dz);
393:       this.yaw = dampAngle(this.yaw, targetYaw, 8, dt);
394:     } else if ((mx || my) && this.state !== 'attack' && this.state !== 'roll' && this.state !== 'crit') {
395:       this.yaw = dampAngle(this.yaw, Math.atan2(dirX, dirZ), 12, dt);
396:     } else if (this.game.lockTarget && this.game.lockTarget.alive && !this.game.lockTarget.isBoss) {
397:       const dx = this.game.lockTarget.pos.x - this.pos.x, dz = this.game.lockTarget.pos.z - this.pos.z;
398:       this.yaw = dampAngle(this.yaw, Math.atan2(dx, dz), 8, dt);
399:     }
400: 
401:     if (this.state === 'roll') { dirX = this.rollDir.x; dirZ = this.rollDir.z; }
402:     this.applyPhysics(dt, dirX * moveSpeed, dirZ * moveSpeed);
403:     this.updateShadow();
404:     this.animate(dt);
405: 
406:     // footsteps
407:     const speed = Math.hypot(this.vel.x, this.vel.z);
408:     if (this.grounded && speed > 1.2) {
409:       this.footTimer -= dt * (this.sprinting ? 1.8 : 1);
410:       if (this.footTimer <= 0) { this.footTimer = .38; this.game.audio.step(); this.puffDust(); }
411:     }
412:     this.syncStats();
413:     this.updateMaterialFlash();
414:   }
415: 
416:   applyPhysics(dt, desiredX, desiredZ) {
417:     if (this.state === 'roll') {
418:       const speed = 11.5 * (1 - Math.min(1, this.stateTime / .52) * .75);
419:       this.vel.x = this.rollDir.x * speed;
420:       this.vel.z = this.rollDir.z * speed;
421:     } else {
422:       const accel = this.grounded ? 14 : 4;
423:       this.vel.x = damp(this.vel.x, desiredX, accel, dt);
424:       this.vel.z = damp(this.vel.z, desiredZ, accel, dt);
425:     }
426:     this.pos.x += this.vel.x * dt;
427:     this.pos.z += this.vel.z * dt;
428: 
429:     // world bounds
430:     const r = Math.hypot(this.pos.x, this.pos.z);
431:     if (r > PLAY_RADIUS) { this.pos.x *= PLAY_RADIUS / r; this.pos.z *= PLAY_RADIUS / r; }
432: 
433:     // colliders
434:     const pr = .38;
435:     for (const c of this.game.world.colliders) {
436:       const dx = this.pos.x - c.x, dz = this.pos.z - c.z;
437:       const d = Math.hypot(dx, dz);
438:       const min = pr + c.r;
439:       if (d < min && d > .0001) {
440:         const push = (min - d);
441:         this.pos.x += (dx / d) * push;
442:         this.pos.z += (dz / d) * push;
443:       }
444:     }
445:     // arena boundary during boss
446:     if (this.game.boss && this.game.boss.active && !this.game.boss.dead) {
447:       const dx = this.pos.x - this.game.boss.center.x, dz = this.pos.z - this.game.boss.center.z;
448:       const d = Math.hypot(dx, dz);
449:       const max = this.game.boss.arenaRadius - .5;
450:       if (d > max) { this.pos.x = this.game.boss.center.x + dx / d * max; this.pos.z = this.game.boss.center.z + dz / d * max; }
451:     }
452: 
453:     const ground = heightAt(this.pos.x, this.pos.z);
454:     if (!this.grounded) {
455:       this.vy -= 20 * dt;
456:       this.pos.y += this.vy * dt;
457:       if (this.pos.y <= ground) { this.pos.y = ground; this.vy = 0; this.grounded = true; this.game.audio.step(); this.game.shake(.1); }
458:     } else {
459:       this.pos.y = ground;
460:     }
461:     this.root.position.copy(this.pos);
462:     this.root.rotation.y = this.yaw;
463:   }
464: 
465:   updateShadow() {
466:     const ground = heightAt(this.pos.x, this.pos.z);
467:     this.shadow.position.y = ground - this.pos.y + .035;
468:     const h = clamp((this.pos.y - ground) / 3, 0, 1);
469:     this.shadow.material.opacity = .3 * (1 - h);
470:     this.shadow.scale.setScalar(1 - h * .5);
471:   }
472:   puffDust() {
473:     for (const d of this.dust) {
474:       if (d.material.opacity < .03) {
475:         d.material.opacity = .28;
476:         d.position.set((Math.random() - .5) * .4, .05, (Math.random() - .5) * .4);
477:         d.scale.setScalar(.5 + Math.random() * .5);
478:         d.userData.life = .35;
479:         break;
480:       }
481:     }
482:   }
483:   updateDust(dt) {
484:     for (const d of this.dust) {
485:       if (d.material.opacity > .01) {
486:         d.material.opacity -= dt * 1.2;
487:         d.scale.multiplyScalar(1 + dt * 1.8);
488:         d.position.y += dt * .3;
489:       }
490:     }
491:   }
492: 
493:   /* ================= ACTIONS ================= */
494:   beginAttack(kind) {
495:     if (this.busy || this.stamina <= 0) return;
496:     if (this.weapon.ranged) {
497:       if (kind === 'heavy') return;
498:       if (this.stamina < this.weapon.stamina) return;
499:       this.stamina -= this.weapon.stamina; this.staminaDelay = .8;
500:       this.state = 'attack'; this.stateTime = 0; this.busy = true;
501:       this.attack = { kind: 'ranged', duration: 1.05, fired: false, heavy: false };
502:       this.game.audio.swing(false);
503:       return;
504:     }
505:     const heavy = kind === 'heavy';
506:     const cost = heavy ? this.weapon.heavyStamina : this.weapon.stamina;
507:     if (this.stamina < cost * .6) { this.game.toast('Not enough stamina', 'blood'); return; }
508:     this.stamina = Math.max(0, this.stamina - cost); this.staminaDelay = .9;
509:     this.combo = heavy ? 0 : (this.combo % 3) + 1;
510:     this.comboTimer = 1.4;
511:     const speed = this.weapon.speed || 1;
512:     const duration = (heavy ? 1.1 : .72) / speed;
513:     this.state = 'attack'; this.stateTime = 0; this.busy = true;
514:     this.attack = { kind, duration, hit: false, heavy, dir: this.yaw, step: this.combo };
515:     this.hasHitThisSwing.clear();
516:     this.game.audio.swing(heavy || this.weapon.weight === 'Heavy');
517:     // small forward lunge
518:     const stepSpeed = heavy ? 2.4 : 1.4;
519:     this.vel.x += Math.sin(this.yaw) * stepSpeed;
520:     this.vel.z += Math.cos(this.yaw) * stepSpeed;
521:   }
522: 
523:   updateAttack(dt) {
524:     const a = this.attack;
525:     if (!a) { this.busy = false; this.state = 'idle'; return; }
526:     const p = this.stateTime / a.duration;
527:     if (!a.hit && p > (a.heavy ? .5 : .4)) {
528:       a.hit = true;
529:       if (a.kind === 'ranged') {
530:         if (this.weapon.spell) this.game.fireSpell();
531:         else this.game.fireArrow();
532:         a.fired = true;
533:       } else {
534:         this.game.playerMeleeHit(this, a.heavy, this.weapon);
535:       }
536:     }
537:     if (p >= 1) { this.busy = false; this.attack = null; this.state = 'idle'; }
538:   }
539:   updateRoll(dt) {
540:     if (this.stateTime > .55) { this.state = 'idle'; this.busy = false; this.vel.multiplyScalar(.5); }
541:   }
542:   beginRoll() {
543:     if (this.busy || this.stamina < 18 || !this.grounded) return;
544:     this.stamina -= 22; this.staminaDelay = .8;
545:     this.state = 'roll'; this.stateTime = 0; this.busy = true;
546:     this.invuln = .36;
547:     const mx = this.game.lastInputX || 0, my = this.game.lastInputY || 0;
548:     let dx = Math.sin(this.yaw), dz = Math.cos(this.yaw);
549:     if (mx || my) {
550:       const yaw = this.game.camera.yaw;
551:       dx = -Math.sin(yaw) * my + Math.cos(yaw) * mx;
552:       dz = -Math.cos(yaw) * my - Math.sin(yaw) * mx;
553:       const l = Math.hypot(dx, dz); dx /= l; dz /= l;
554:       this.yaw = Math.atan2(dx, dz);
555:     }
556:     this.rollDir.set(dx, 0, dz);
557:     this.game.audio.dodge();
558:   }
559:   jump() {
560:     if (this.busy || this.stamina < 8) return;
561:     this.stamina -= 8; this.staminaDelay = .6;
562:     this.vy = 6.9; this.grounded = false;
563:     this.state = 'jump'; this.busy = false;
564:     this.game.audio.jump();
565:     setTimeout(() => { if (this.state === 'jump') this.state = 'idle'; }, 300);
566:   }
567:   tryHeal() {
568:     if (this.busy || this.stats.flaskUses <= 0 || this.hp >= this.maxHp) {
569:       if (this.stats.flaskUses <= 0) this.game.toast('The Ashen Flask is empty', 'blood');
570:       return;
571:     }
572:     this.stats.flaskUses--;
573:     this.state = 'heal'; this.stateTime = 0; this.busy = true; this.healUsed = false;
574:     this.game.audio.heal();
575:   }
576:   updateHeal(dt) {
577:     if (!this.healUsed && this.stateTime > .55) {
578:       this.healUsed = true;
579:       const amt = Math.round(this.maxHp * .46);
580:       this.hp = Math.min(this.maxHp, this.hp + amt);
581:       this.game.spawnHealBurst(this.pos);
582:       this.game.floatText(this.pos, `+${amt}`, 'heal');
583:       this.game.audio.souls();
584:     }
585:     if (this.stateTime > 1.15) { this.state = 'idle'; this.busy = false; }
586:   }
587:   trySpell() {
588:     if (!this.stats.spellUnlocked) { this.game.toast('You have not learned any incantations', 'blood'); return; }
589:     if (this.busy || this.focus < 25) { if (this.focus < 25) this.game.toast('Not enough focus', 'blood'); return; }
590:     this.focus -= 25;
591:     this.state = 'cast'; this.stateTime = 0; this.busy = true; this.castFired = false;
592:     this.game.audio.spell();
593:   }
594:   updateCast(dt) {
595:     if (!this.castFired && this.stateTime > .45) {
596:       this.castFired = true;
597:       this.game.fireSpell(true);
598:     }
599:     if (this.stateTime > .95) { this.state = 'idle'; this.busy = false; }
600:   }
601:   startCritical(target) {
602:     if (this.busy || !target) return;
603:     this.state = 'crit'; this.stateTime = 0; this.busy = true;
604:     this.critTarget = target;
605:     this.game.audio.swing(true);
606:   }
607:   updateCrit(dt) {
608:     if (!this.critApplied && this.stateTime > .45 && this.critTarget) {
609:       this.critApplied = true;
610:       const t = this.critTarget;
611:       if (t && t.alive) {
612:         const dmg = this.critPower;
613:         t.takeDamage(dmg, this.pos, { critical: true, source: this });
614:         this.game.spawnBloodBurst(t.pos, 18);
615:         this.game.audio.hit(t.armorType === 'metal');
616:         this.game.shake(.35);
617:         this.game.hitstop(.09);
618:       }
619:     }
620:     if (this.stateTime > 1.15) { this.state = 'idle'; this.busy = false; this.critApplied = false; this.critTarget = null; }
621:   }
622: 
623:   /* ================= DAMAGE ================= */
624:   takeDamage(amount, fromPos, opts = {}) {
625:     if (this.dead) return false;
626:     if (this.invuln > 0) {
627:       if (this.state === 'roll' && this.stateTime > .04 && this.stateTime < .38 && !opts.aoe) {
628:         this.perfectDodges++;
629:         this.focus = Math.min(this.maxFocus, this.focus + 12);
630:         this.game.onPerfectDodge();
631:       }
632:       return false;
633:     }
634:     const dx = fromPos ? this.pos.x - fromPos.x : 0;
635:     const dz = fromPos ? this.pos.z - fromPos.z : 0;
636:     const facing = Math.sin(this.yaw) * dx + Math.cos(this.yaw) * dz;
637:     const front = facing >= -0.25;
638: 
639:     if (this.blocking && front && !opts.unblockable) {
640:       if (this.parryWindow > 0 && !opts.aoe) {
641:         this.parryWindow = 0;
642:         this.game.onParry(opts.source);
643:         this.game.audio.parry();
644:         this.stamina = Math.min(this.maxStamina, this.stamina + 15);
645:         return false;
646:       }
647:       const staminaCost = amount * (this.weapon.category === 'Greatsword' ? 1.05 : .9) / (1 + this.stats.endurance * .015);
648:       if (this.stamina >= staminaCost * .5) {
649:         this.stamina = Math.max(0, this.stamina - staminaCost);
650:         this.staminaDelay = 1.1;
651:         const chip = amount * .12;
652:         this.hp -= chip;
653:         this.game.audio.block();
654:         this.game.shake(.16);
655:         this.game.spawnSparkBurst(fromPos || this.pos, 6);
656:         this.game.floatText(this.pos, 'BLOCKED', 'block');
657:         if (this.stamina <= 0) { this.staggerTime = .6; this.game.toast('GUARD BROKEN', 'blood'); }
658:         if (this.hp <= 0) this.die();
659:         return false;
660:       } else {
661:         this.stamina = 0; this.staggerTime = .8;
662:         this.game.toast('GUARD BROKEN', 'blood');
663:         amount *= .7;
664:       }
665:     }
666: 
667:     const reduced = amount * (1 - Math.min(.55, this.defense * .018));
668:     this.hp -= reduced;
669:     this.poiseBuildup += amount * .7;
670:     this.hitFlash = .2;
671:     this.game.onPlayerHurt(reduced, fromPos);
672:     this.game.audio.hit(false);
673:     this.game.floatText(this.pos, Math.round(reduced), 'damage');
674:     if (this.poiseBuildup > this.poise) { this.staggerTime = .5; this.poiseBuildup = 0; }
675:     else if (!opts.noStun) { this.staggerTime = .22; this.state = 'hit'; }
676:     if (this.hp <= 0) { this.hp = 0; this.die(); return true; }
677:     return true;
678:   }
679: 
680:   die() {
681:     if (this.dead) return;
682:     this.dead = true; this.deathTime = 0; this.state = 'dead'; this.busy = true;
683:     this.game.onPlayerDeath();
684:     this.game.audio.death();
685:   }
686:   updateDeath(dt) {
687:     this.deathTime += dt;
688:     const p = Math.min(1, this.deathTime / 1.0);
689:     this.pivot.rotation.z = lerp(0, -1.35, p);
690:     this.pivot.position.y = lerp(0, -.45, p);
691:     this.armR.shoulder.rotation.x = lerp(this.armR.shoulder.rotation.x, -.4, p);
692:   }
693:   respawn(pos, shrine) {
694:     this.dead = false; this.hp = this.maxHp; this.stamina = this.maxStamina; this.focus = this.maxFocus;
695:     this.stats.flaskUses = this.stats.maxFlask;
696:     this.poiseBuildup = 0; this.staggerTime = 0; this.invuln = 1.0;
697:     this.pivot.rotation.set(0, 0, 0); this.pivot.position.y = 0;
698:     const p = pos || { x: 3.5, z: 81 };
699:     this.pos.set(p.x, heightAt(p.x, p.z), p.z);
700:     this.vel.set(0, 0, 0); this.vy = 0; this.grounded = true;
701:     this.root.position.copy(this.pos);
702:     this.state = 'idle'; this.busy = false; this.attack = null;
703:     this.syncStats();
704:   }
705: 
706:   /* ================= ANIMATION ================= */
707:   animate(dt) {
708:     const t = this.animTime;
709:     const speed = Math.hypot(this.vel.x, this.vel.z);
710:     const moving = speed > .5 && this.grounded;
711:     const run = clamp(speed / 7.5, 0, 1.2);
712:     let legSwing = 0, armSwing = 0, bob = 0;
713: 
714:     // reset base every frame toward neutral
715:     const neutral = (obj, x, y, z, lambda = 12) => {
716:       obj.rotation.x = damp(obj.rotation.x, x, lambda, dt);
717:       obj.rotation.y = damp(obj.rotation.y, y, lambda, dt);
718:       obj.rotation.z = damp(obj.rotation.z, z, lambda, dt);
719:     };
720: 
721:     if (this.state === 'roll') {
722:       const p = clamp(this.stateTime / .55, 0, 1);
723:       this.pivot.rotation.x = p * Math.PI * 2;
724:       this.pivot.position.y = Math.sin(p * Math.PI) * .38;
725:       this.armL.shoulder.rotation.x = -1.4; this.armR.shoulder.rotation.x = -1.2;
726:       this.legL.hip.rotation.x = -1.5; this.legR.hip.rotation.x = -1.3;
727:       this.legL.knee.rotation.x = 1.8; this.legR.knee.rotation.x = 1.6;
728:       this.torso.rotation.x = .5;
729:       return;
730:     } else {
731:       this.pivot.rotation.x = damp(this.pivot.rotation.x, 0, 14, dt);
732:       this.pivot.position.y = damp(this.pivot.position.y, 0, 14, dt);
733:     }
734: 
735:     if (this.state === 'attack' && this.attack) {
736:       const a = this.attack;
737:       const p = clamp(this.stateTime / a.duration, 0, 1);
738:       const wind = a.heavy ? .42 : .32;
739:       let sw = 0;
740:       if (p < wind) sw = p / wind;
741:       else sw = 1 - (p - wind) / (1 - wind);
742:       if (a.step === 2) {
743:         // rising diagonal
744:         this.armR.shoulder.rotation.x = damp(this.armR.shoulder.rotation.x, -1.9 + p * 1.0, 22, dt);
745:         this.armR.shoulder.rotation.z = damp(this.armR.shoulder.rotation.z, .5 - p * .4, 22, dt);
746:         this.torso.rotation.y = damp(this.torso.rotation.y, .5 - p * .9, 18, dt);
747:         this.torso.rotation.x = damp(this.torso.rotation.x, -.1, 12, dt);
