249:   /* ==================== UPDATE ==================== */
250:   update(dt, player) {
251:     if (!this.alive) { this.updateDeath(dt); return; }
252:     this.stateTime += dt;
253:     this.attackCooldown = Math.max(0, this.attackCooldown - dt);
254:     this.rangedCooldown = Math.max(0, this.rangedCooldown - dt);
255:     this.hitFlash = Math.max(0, this.hitFlash - dt);
256:     this.poise = Math.min(this.maxPoise, this.poise + dt * 9);
257:     if (this.alertIcon.visible && this.stateTime > 1.1) this.alertIcon.visible = false;
258: 
259:     const dist = Math.hypot(player.pos.x - this.pos.x, player.pos.z - this.pos.z);
260:     const dx = player.pos.x - this.pos.x, dz = player.pos.z - this.pos.z;
261:     const angToPlayer = Math.atan2(dx, dz);
262:     this.distToPlayer = dist;
263: 
264:     if (player.dead) { this.aggro = false; if (this.state !== 'return' && this.state !== 'patrol') this.setState('return'); }
265: 
266:     // detection
267:     if (!this.aggro && !player.dead && this.state !== 'stagger') {
268:       const facing = Math.cos(angleDelta(this.yaw, angToPlayer));
269:       const heard = player.sprinting && dist < 24;
270:       if ((dist < this.def.aggro && (dist < 4.5 || facing > .15 || player.sprinting)) || heard) {
271:         this.alert(player);
272:       }
273:     }
274:     this.alertLevel = this.aggro ? 1 : 0;
275: 
276:     switch (this.state) {
277:       case 'patrol': this.updatePatrol(dt); break;
278:       case 'idle': this.updateIdle(dt); break;
279:       case 'chase': this.updateChase(dt, player, dist, angToPlayer); break;
280:       case 'attack': this.updateAttack(dt, player, dist, angToPlayer); break;
281:       case 'stagger': this.updateStagger(dt); break;
282:       case 'return': this.updateReturn(dt); break;
283:     }
284: 
285:     // physics / collisions / ground
286:     this.pos.x += this.vel.x * dt;
287:     this.pos.z += this.vel.z * dt;
288:     this.vel.x = damp(this.vel.x, 0, 6, dt); this.vel.z = damp(this.vel.z, 0, 6, dt);
289:     this.resolveCollisions();
290:     this.pos.y = heightAt(this.pos.x, this.pos.z);
291:     this.root.position.copy(this.pos);
292:     this.root.rotation.y = this.yaw;
293:     this.updateAnimation(dt);
294:   }
295: 
296:   setState(s) { this.state = s; this.stateTime = 0; }
297: 
298:   alert(player) {
299:     if (this.aggro) return;
300:     this.aggro = true;
301:     this.setState('chase');
302:     this.alertIcon.visible = true;
303:     this.stateTime = 0;
304:     this.game.audio.roar?.(); // maybe not for all; use soft sting
305:     if (!this.def.elite) this.game.audio.tone?.({ freq: 180, type: 'triangle', dur: .25, gain: .025 });
306:     else this.game.audio.roar();
307:     if (this.isElite) this.game.showEliteBar(this);
308:     // alert nearby allies
309:     for (const e of this.game.enemies) {
310:       if (e === this || !e.alive || e.aggro) continue;
311:       if (e.pos.distanceTo(this.pos) < 12) { e.aggro = true; e.setState('chase'); }
312:     }
313:   }
314: 
315:   updatePatrol(dt) {
316:     if (this.patrolWait > 0) { this.patrolWait -= dt; return; }
317:     const dx = this.patrolTarget.x - this.pos.x, dz = this.patrolTarget.z - this.pos.z;
318:     const d = Math.hypot(dx, dz);
319:     if (d < .7) {
320:       this.patrolWait = rand(1.2, 3.4);
321:       this.patrolTarget = this.pickPatrol();
322:       return;
323:     }
324:     const sp = this.def.speed * .34;
325:     this.vel.x = (dx / d) * sp; this.vel.z = (dz / d) * sp;
326:     this.yaw = dampAngle(this.yaw, Math.atan2(dx, dz), 5, dt);
327:   }
328:   updateIdle(dt) {
329:     if (this.stateTime > 2) { this.setState('patrol'); this.patrolTarget = this.pickPatrol(); }
330:   }
331:   updateChase(dt, player, dist, angToPlayer) {
332:     const leashD = Math.hypot(this.pos.x - this.spawn.x, this.pos.z - this.spawn.z);
333:     if (leashD > this.leash || player.dead) { this.aggro = false; this.setState('return'); if (this.isElite) this.game.hideEliteBar(); return; }
334:     if (this.def.ranged) { this.updateArcherChase(dt, player, dist, angToPlayer); return; }
335:     this.yaw = dampAngle(this.yaw, angToPlayer, 6, dt);
336:     const attackRange = this.def.attackRange;
337:     if (dist > attackRange * .9) {
338:       const sp = this.def.speed * (dist > 8 ? 1.15 : 1);
339:       this.vel.x = (Math.sin(angToPlayer) * sp);
340:       this.vel.z = (Math.cos(angToPlayer) * sp);
341:     } else {
342:       // circle strafe / wait for opening
343:       const side = Math.sin(this.game.time * .8 + this.spawn.x) > 0 ? 1 : -1;
344:       this.vel.x = Math.cos(angToPlayer) * this.def.speed * .28 * side;
345:       this.vel.z = -Math.sin(angToPlayer) * this.def.speed * .28 * side;
346:       if (this.attackCooldown <= 0 && this.game.canEnemyAttack(this)) this.startAttack();
347:     }
348:     // separation
349:     this.separation();
350:   }
351:   updateArcherChase(dt, player, dist, angToPlayer) {
352:     this.yaw = dampAngle(this.yaw, angToPlayer, 6, dt);
353:     if (dist < 5) {
354:       this.vel.x = -Math.sin(angToPlayer) * this.def.speed; this.vel.z = -Math.cos(angToPlayer) * this.def.speed;
355:     } else if (dist > 16) {
356:       this.vel.x = Math.sin(angToPlayer) * this.def.speed; this.vel.z = Math.cos(angToPlayer) * this.def.speed;
357:     } else if (this.rangedCooldown <= 0 && this.game.canEnemyAttack(this)) {
358:       this.startAttack('ranged');
359:     }
360:     this.separation();
361:   }
362:   separation() {
363:     for (const e of this.game.enemies) {
364:       if (e === this || !e.alive) continue;
365:       const dx = this.pos.x - e.pos.x, dz = this.pos.z - e.pos.z;
366:       const d = Math.hypot(dx, dz);
367:       if (d < 1.3 && d > .01) { this.vel.x += dx / d * .8; this.vel.z += dz / d * .8; }
368:     }
369:   }
