371:   startAttack(kind = 'melee') {
372:     this.state = 'attack'; this.stateTime = 0;
373:     this.attackCooldown = this.def.attackCooldown + rand(0, .5);
374:     const ranged = kind === 'ranged';
375:     const elite = this.def.elite;
376:     const atk = {
377:       kind,
378:       windup: ranged ? 1.15 : (elite ? .85 : (this.defId === 'knight' ? .9 : this.defId === 'goblin' ? .35 : .55)),
379:       active: ranged ? .1 : .18,
380:       recover: ranged ? .7 : (elite ? .75 : .55),
381:       damage: this.def.damage * (elite ? 1.15 : 1),
382:       range: ranged ? 30 : (elite ? 4.2 : this.def.attackRange + .55),
383:       cone: ranged ? .9 : (elite ? .95 : .72),
384:       fired: false,
385:       lunging: this.defId === 'hound' || (elite && kind === 'melee'),
386:     };
387:     if (elite && chance(.4)) { atk.kind = 'aoe'; atk.windup = 1.0; atk.damage = this.def.damage * 1.3; atk.range = 5.0; }
388:     this.attack = atk;
389:     this.faceLocked = this.yaw;
390:     this.game.audio.swing?.(elite);
391:     this.telegraph.visible = true;
392:     this.telegraph.material.opacity = 0;
393:     this.telegraph.scale.setScalar(.6);
394:     this.alertIcon.visible = false;
395:   }
