397:   updateAttack(dt, player, dist, angToPlayer) {
398:     const a = this.attack;
399:     if (!a) { this.setState('chase'); return; }
400:     const t = this.stateTime;
401:     if (a.kind !== 'ranged') this.yaw = dampAngle(this.yaw, angToPlayer, 3.2, dt);
402:     // telegraph build
403:     if (t < a.windup) {
404:       const p = t / a.windup;
405:       this.telegraph.material.opacity = .18 + p * .55;
406:       const sc = .5 + p * (a.range / 1.4);
407:       this.telegraph.scale.setScalar(sc);
408:       this.telegraph.material.color.setHex(a.kind === 'aoe' ? 0xb44cff : 0xff4a2a);
409:       if (a.lunging) this.attackLunge = true;
410:     } else if (!a.fired) {
411:       a.fired = true;
412:       this.telegraph.material.opacity = 0;
413:       this.telegraph.visible = false;
414:       if (a.kind === 'ranged') {
415:         this.game.enemyFireArrow(this, player);
416:       } else if (a.kind === 'aoe') {
417:         this.game.enemyAoe(this, a);
