13: export function distToPath(x, z) {
14:   let best = 999, bx = 0, bz = 0, bt = 0;
15:   for (let i = 0; i < PATH.length - 1; i++) {
16:     const [ax, az] = PATH[i], [ex, ez] = PATH[i + 1];
17:     const dx = ex - ax, dz = ez - az;
18:     const l2 = dx * dx + dz * dz;
19:     let t = ((x - ax) * dx + (z - az) * dz) / l2;
20:     t = clamp(t, 0, 1);
21:     const px = ax + dx * t, pz = az + dz * t;
22:     const d = Math.hypot(x - px, z - pz);
23:     if (d < best) { best = d; bx = px; bz = pz; bt = i + t; }
24:   }
25:   return { d: best, x: bx, z: bz, t: bt };
26: }
