696: export function createFireflies(scene) {
697:   const rnd = seededRandom(19);
698:   const count = 340;
699:   const base = [];
700:   const pos = new Float32Array(count * 3);
701:   const phase = new Float32Array(count);
702:   for (let i = 0; i < count; i++) {
703:     const x = (rnd() * 2 - 1) * 100, z = (rnd() * 2 - 1) * 100;
704:     base.push([x, heightAt(x, z), z]);
705:     pos[i * 3] = x; pos[i * 3 + 1] = heightAt(x, z) + 1 + rnd() * 9; pos[i * 3 + 2] = z;
706:     phase[i] = rnd() * 6.28;
707:   }
708:   const geo = new THREE.BufferGeometry();
709:   geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
710:   const mat = new THREE.PointsMaterial({ color: 0xffd98a, size: .11, transparent: true, opacity: .85, blending: THREE.AdditiveBlending, depthWrite: false });
711:   const pts = new THREE.Points(geo, mat); scene.add(pts);
712:   return { pts, phase, base, update(t) {
713:     const p = pts.geometry.attributes.position;
714:     for (let i = 0; i < count; i++) {
715:       const [x, y, z] = base[i];
716:       p.setX(i, x + Math.sin(t * .3 + phase[i]) * 2.2);
717:       p.setY(i, y + 1.4 + Math.sin(t * .55 + phase[i] * 1.7) * 1.2 + (i % 5) * 1.2);
718:       p.setZ(i, z + Math.cos(t * .27 + phase[i]) * 2.2);
719:     }
720:     p.needsUpdate = true;
721:   } };
722: }
