724: export function createDriftingPetals(scene) {
725:   const rnd = seededRandom(44);
726:   const count = 180;
727:   const pos = new Float32Array(count * 3);
728:   const phase = new Float32Array(count);
729:   for (let i = 0; i < count; i++) {
730:     pos[i * 3] = (rnd() * 2 - 1) * 80;
731:     pos[i * 3 + 1] = 2 + rnd() * 14;
732:     pos[i * 3 + 2] = (rnd() * 2 - 1) * 80;
733:     phase[i] = rnd() * 100;
734:   }
735:   const geo = new THREE.BufferGeometry();
736:   geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
737:   const mat = new THREE.PointsMaterial({ color: 0xf3c7d9, size: .13, transparent: true, opacity: .55, depthWrite: false });
738:   const pts = new THREE.Points(geo, mat); scene.add(pts);
739:   return { pts, phase, update(t) {
740:     const p = pts.geometry.attributes.position;
741:     for (let i = 0; i < count; i++) {
742:       const x = pos[i * 3] + Math.sin(t * .18 + phase[i]) * 3;
743:       const z = pos[i * 3 + 2] + t * .22 % 160 - 80;
744:       p.setX(i, x); p.setZ(i, z); p.setY(i, 2 + ((pos[i * 3 + 1] + t * .35 + phase[i]) % 16));
745:     }
746:     p.needsUpdate = true;
747:   } };
748: }

