import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(30000);
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR', e.message); });
page.on('console', (m) => { if (m.type() === 'error') { errors.push(m.text()); console.log('CONSOLE', m.text()); } });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForFunction(() => window.__HOLLOW_CROWN__?.mode === 'title', null, { timeout: 30000 });
await page.screenshot({ path: join(out, '01-title.png') });
console.log('title ready');

await page.click('#btn-new');
await page.waitForTimeout(2500);
await page.screenshot({ path: join(out, '02-intro-rain.png') });
await page.waitForTimeout(7500);
await page.screenshot({ path: join(out, '03-intro-rift.png') });
const introState = await page.evaluate(() => ({ mode: window.__HOLLOW_CROWN__.mode, introTime: window.__HOLLOW_CROWN__.introTime }));
console.log('intro', introState);
await page.keyboard.press('Escape');
await page.waitForTimeout(1200);
await page.screenshot({ path: join(out, '04-gameplay.png') });
console.log('play', await page.evaluate(() => ({ mode: window.__HOLLOW_CROWN__.mode, pos: window.__HOLLOW_CROWN__.player.pos.toArray(), enemies: window.__HOLLOW_CROWN__.enemies.length, ui: window.__HOLLOW_CROWN__.uiBlocking })));

// Walk toward the village for a moment.
await page.keyboard.down('w');
await page.waitForTimeout(1600);
await page.keyboard.up('w');
await page.waitForTimeout(250);
await page.screenshot({ path: join(out, '05-walk.png') });
console.log('walk', await page.evaluate(() => window.__HOLLOW_CROWN__.player.pos.toArray()));

// Teleport next to a villager and fight it.
await page.evaluate(() => {
  const g = window.__HOLLOW_CROWN__;
  const e = g.enemies.find(x => x.defId === 'villager');
  g.player.pos.set(e.pos.x, 0, e.pos.z + 3.2);
  g.player.root.position.copy(g.player.pos);
  g.player.yaw = Math.PI;
  g.player.invuln = 3;
  g.cameraRig.yaw = 0;
  g.setCameraImmediate();
  window.__TEST_ENEMY__ = e;
});
await page.waitForTimeout(700);
const hpBefore = await page.evaluate(() => window.__TEST_ENEMY__.health);
await page.keyboard.press('Tab');
await page.waitForTimeout(250);
await page.keyboard.press('j');
await page.waitForTimeout(600);
const hpAfter = await page.evaluate(() => window.__TEST_ENEMY__.health);
await page.screenshot({ path: join(out, '06-combat.png') });
console.log('combat hp', hpBefore, '->', hpAfter);

// Open inventory, then map.
await page.keyboard.press('i');
await page.waitForTimeout(600);
await page.screenshot({ path: join(out, '07-inventory.png') });
console.log('inv', await page.evaluate(() => window.__HOLLOW_CROWN__.ui.currentMenu?.title));
await page.keyboard.press('Escape');
await page.waitForTimeout(300);
await page.keyboard.press('m');
await page.waitForTimeout(600);
await page.screenshot({ path: join(out, '08-map.png') });
console.log('map', await page.evaluate(() => window.__HOLLOW_CROWN__.ui.currentMenu?.title));
await page.keyboard.press('Escape');
await page.waitForTimeout(300);

// Boss intro.
await page.evaluate(() => {
  const g = window.__HOLLOW_CROWN__;
  g.player.pos.set(0, 0, -82);
  g.player.root.position.copy(g.player.pos);
  g.player.yaw = Math.PI;
  g.player.invuln = 999;
  g.player.hp = g.player.maxHp;
  g.cameraRig.yaw = 0;
  g.setCameraImmediate();
});
await page.waitForTimeout(1500);
await page.screenshot({ path: join(out, '09-boss-intro.png') });
console.log('boss intro', await page.evaluate(() => ({ intro: !!window.__HOLLOW_CROWN__.bossIntro, active: window.__HOLLOW_CROWN__.boss?.active })));
await page.keyboard.press('Escape');
await page.waitForTimeout(1000);
await page.screenshot({ path: join(out, '10-boss-fight.png') });
console.log('boss fight', await page.evaluate(() => ({ intro: !!window.__HOLLOW_CROWN__.bossIntro, active: window.__HOLLOW_CROWN__.boss?.active, state: window.__HOLLOW_CROWN__.boss?.state })));

// Kill boss for the reward / chapter gate flow.
await page.evaluate(() => { const g = window.__HOLLOW_CROWN__; g.boss.takeDamage(99999, g.player.pos, {}); });
await page.waitForTimeout(1000);
await page.screenshot({ path: join(out, '11-boss-death.png') });
console.log('boss dead', await page.evaluate(() => ({ dead: window.__HOLLOW_CROWN__.boss?.dead, flags: window.__HOLLOW_CROWN__.state.flags, motes: window.__HOLLOW_CROWN__.state.player.motes })));

// Open the chapter gate panel.
await page.evaluate(() => window.__HOLLOW_CROWN__.openChapterEnd());
await page.waitForTimeout(500);
await page.screenshot({ path: join(out, '12-chapter-end.png') });
console.log('chapter', await page.evaluate(() => window.__HOLLOW_CROWN__.ui.currentMenu?.title));

// Endings menu + ending screen.
await page.evaluate(() => window.__HOLLOW_CROWN__.openEndings());
await page.waitForTimeout(500);
await page.screenshot({ path: join(out, '13-endings.png') });
await page.evaluate(() => window.__HOLLOW_CROWN__.chooseEnding('dawn'));
await page.waitForTimeout(500);
await page.screenshot({ path: join(out, '14-ending-dawn.png') });
console.log('ending', await page.evaluate(() => ({ mode: window.__HOLLOW_CROWN__.mode, ending: window.__HOLLOW_CROWN__.state.ending })));

console.log('ERRORS', errors.length);
await browser.close();

