Now add the methods. Insert before `/* ==================== misc ==================== */`. Need write robust. Let's craft.

```
  /* ==================== CONTROLLER UI ==================== */
  updateGamepadUI(dt) {
    const input = this.game.input;
    if (!input) return;
    if (input.lastDevice !== this.lastDevice) {
      this.lastDevice = input.lastDevice;
      this.refreshInputHints();
    }
    const pad = input.lastDevice === 'gamepad';
    if (!pad) { this.clearGpFocus(); return; }
    const ctx = this.gpContext();
    if (!ctx) { this.clearGpFocus(); return; }
    const changed = ctx.key !== this.gpContextKey;
    if (changed) {
      this.gpContextKey = ctx.key;
      this.gpContextSig = ctx.sig;
      this.gpFocusEls = this.gpCollect(ctx.el, ctx.selector);
      this.gpFocusIndex = 0;
      this.gpNavDir = 0;
      this.gpRepeatTimer = 0.35;
      this.applyGpFocus();
      // The same A press that opened a shrine/dialogue must not also pick
      // its first option. On the title screen, however, A should start.
      const openedByGameplay = this.game.uiBlocking || this.dialogueState;
      this.gpConfirmLocked = ctx.key !== 'title' && openedByGameplay;
      if (this.gpConfirmLocked) return;
    } else {
      if (ctx.sig !== this.gpContextSig) {
        this.gpContextSig = ctx.sig;
        const old = this.gpFocusEls[this.gpFocusIndex];
        this.gpFocusEls = this.gpCollect(ctx.el, ctx.selector);
        const keep = this.gpFocusEls.indexOf(old);
        this.gpFocusIndex = keep >= 0 ? keep : Math.min(this.gpFocusIndex, this.gpFocusEls.length - 1);
        if (this.gpFocusIndex < 0) this.gpFocusIndex = 0;
        this.applyGpFocus();
      }
    }

    if (this.gpConfirmLocked) { this.gpConfirmLocked = false; return; }

    // Cancel with B.
    if (input.navCancel) {
      if (ctx.cancel) { ctx.cancel(); this.clearGpFocus(true); return; }
    }

    // Confirm with A.
    if (input.navConfirm) {
      this.activateGpFocus();
      return;
    }

    // Move the focus with D-pad or left stick, with hold-to-repeat.
    const y = input.navY, x = input.navX;
    let dir = 0;
    if (input.wasPressed('GP12') || input.wasPressed('GP14')) dir = -1;
    else if (input.wasPressed('GP13') || input.wasPressed('GP15')) dir = 1;
