import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(30000);
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR', e.message); });
page.on('console', (m) => { if (m.type() === 'error') { errors.push(m.text()); console.log('CONSOLE', m.text()); } });

// Install a fake Xbox standard-mapping pad before the app starts.
await page.addInitScript(() => {
  const pad = {
    id: 'Xbox Wireless Controller (STANDARD GAMEPAD)',
    index: 0,
    connected: true,
    mapping: 'standard',
    timestamp: 0,
    axes: [0, 0, 0, 0],
    buttons: Array.from({ length: 17 }, () => ({ pressed: false, value: 0, touched: false })),
    vibrationActuator: {
      playEffect: () => { window.__RUMBLE_COUNT__ = (window.__RUMBLE_COUNT__ || 0) + 1; return Promise.resolve('complete'); },
      reset: () => Promise.resolve('complete'),
    },
  };
  window.__PAD__ = pad;
  window.__RUMBLE_COUNT__ = 0;
  Object.defineProperty(navigator, 'getGamepads', { value: () => [pad], configurable: true });
  window.addEventListener('load', () => {
    window.dispatchEvent(new GamepadEvent('gamepadconnected', { gamepad: pad }));
  });
});

const frame = (ms = 160) => page.waitForTimeout(ms);
