import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(30000);
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR', e.message); });
page.on('console', (m) => { if (m.type() === 'error') { errors.push(m.text()); console.log('CONSOLE', m.text()); } });

await page.clock.install();

await page.addInitScript(() => {
  const pad = {
    id: 'Xbox Wireless Controller (STANDARD GAMEPAD)',
    index: 0,
    connected: true,
    mapping: 'standard',
    timestamp: 0,
    axes: [0, 0, 0, 0],
    buttons: Array.from({ length: 17 }, () => ({ pressed: false, value: 0, touched: false })),
    vibrationActuator: {
      playEffect: () => { window.__RUMBLE_COUNT__ = (window.__RUMBLE_COUNT__ || 0) + 1; return Promise.resolve('complete'); },
      reset: () => Promise.resolve('complete'),
    },
  };
  window.__PAD__ = pad;
  window.__RUMBLE_COUNT__ = 0;
  Object.defineProperty(navigator, 'getGamepads', { value: () => [pad], configurable: true });
});

const frame = (ms = 160) => page.clock.runFor(ms);
const shot = (name) => page.screenshot({ path: join(out, name) });
const padSet = (axes, buttons) => page.evaluate(({ axes, buttons }) => {
  if (axes) window.__PAD__.axes = axes;
  if (buttons) {
    for (const [i, down] of Object.entries(buttons)) {
      window.__PAD__.buttons[+i].pressed = !!down;
      window.__PAD__.buttons[+i].value = down ? 1 : 0;
    }
  }
  window.__PAD__.timestamp = performance.now();
}, { axes, buttons });
const tap = async (i, hold = 110) => {
  await padSet(null, { [i]: true });
  await frame(hold);
  await padSet(null, { [i]: false });
  await frame(180);
};
const state = () => page.evaluate(() => {
  const g = window.__HOLLOW_CROWN__;
  const focus = document.querySelector('.gp-focused');
  return {
    mode: g.mode,
    uiBlocking: g.uiBlocking,
    menu: g.ui.currentMenu?.title || null,
    dialogue: g.ui.dialogueState ? (g.ui.dialogueState.node?.text || '').slice(0, 40) : null,
    focus: focus ? (focus.textContent || '').trim().replace(/\s+/g, ' ').slice(0, 44) : null,
    pos: g.player.pos.toArray().map(n => +n.toFixed(2)),
    yaw: +g.cameraRig.yaw.toFixed(3),
    pad: g.input.gpConnected,
    device: g.input.lastDevice,
    rumbles: window.__RUMBLE_COUNT__,
  };
});

await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForFunction(() => window.__HOLLOW_CROWN__?.mode === 'title', null, { timeout: 30000 });
await frame(500);
console.log('TITLE', await state());
await shot('c01-title-pad.png');

// A starts the game from the title.
await tap(0);
await frame(500);
console.log('AFTER A', await state());
await shot('c02-intro-pad.png');

// Let the intro breathe, then B skips it.
await frame(1800);
await tap(1);
await frame(900);
console.log('PLAY', await state());
await shot('c03-play-pad.png');

// Left stick movement.
const beforeMove = (await state()).pos;
await padSet([0, -1, 0, 0]);
await frame(1100);
await padSet([0, 0, 0, 0]);
await frame(250);
const afterMove = (await state()).pos;
console.log('MOVE', beforeMove, '->', afterMove);

// Right stick camera look.
const yawBefore = (await state()).yaw;
await padSet([0, 0, 1, 0]);
await frame(700);
await padSet([0, 0, 0, 0]);
await frame(200);
const yawAfter = (await state()).yaw;
console.log('LOOK', yawBefore, '->', yawAfter);

// Pause with Start, navigate with D-pad, confirm with A.
await tap(9);
await frame(400);
console.log('PAUSE', await state());
await shot('c04-pause-focus.png');
await tap(13); // down
await frame(250);
console.log('PAUSE NAV', await state());
await tap(0); // select Inventory
await frame(500);
console.log('INVENTORY', await state());
await shot('c05-inventory-focus.png');
await tap(1); // B closes
await frame(500);
console.log('CLOSED', await state());

// D-pad down opens map.
await tap(13);
await frame(500);
console.log('MAP', await state());
await shot('c06-map-focus.png');
await tap(1);
await frame(400);

// Dialogue with Marrow. Teleport next to them and press A.
await page.evaluate(() => {
  const g = window.__HOLLOW_CROWN__;
  const n = g.npcs.find(n => n.id === 'marrow');
  g.player.pos.set(n.x, 0, n.z + 1.2);
  g.player.root.position.copy(g.player.pos);
  g.player.invuln = 30;
  g.setCameraImmediate();
});
await frame(500);
await tap(0);
await frame(500);
console.log('DIALOGUE OPEN', await state());
await shot('c07-dialogue-focus.png');
console.log('DIALOGUE NOT AUTO-SELECTED', await page.evaluate(() => {
  const g = window.__HOLLOW_CROWN__;
  return !!g.ui.dialogueState && g.ui.dialogueState.node?.text === g.ui.dialogueState.data.nodes[g.ui.dialogueState.data.startNode]?.text;
}));
const dialogueFocus0 = (await state()).focus;
await tap(13);
await frame(250);
const dialogueFocus1 = (await state()).focus;
console.log('DIALOGUE NAV', dialogueFocus0, '->', dialogueFocus1);
await tap(1);
await frame(400);
console.log('DIALOGUE CLOSED', await state());

// Shrine interaction: A opens; must not auto-rest.
await page.evaluate(() => {
  const g = window.__HOLLOW_CROWN__;
  const s = g.world.shrines[0];
  g.player.pos.set(s.x, 0, s.z + 1.2);
  g.player.root.position.copy(g.player.pos);
  g.player.invuln = 30;
  g.setCameraImmediate();
});
await frame(500);
await tap(0);
await frame(500);
console.log('SHRINE', await state());
await shot('c08-shrine-focus.png');
await tap(1);
await frame(400);

// Combat: teleport to a villager, lock with Y, attack with RB.
await page.evaluate(() => {
  const g = window.__HOLLOW_CROWN__;
  const e = g.enemies.find(x => x.defId === 'villager' && x.alive);
  g.player.pos.set(e.pos.x, 0, e.pos.z + 2.8);
  g.player.root.position.copy(g.player.pos);
  g.player.yaw = Math.PI;
  g.player.invuln = 30;
  g.cameraRig.yaw = 0;
  g.setCameraImmediate();
  window.__E__ = e;
});
await frame(600);
const hp0 = await page.evaluate(() => window.__E__.health);
await tap(3); // lock on
await frame(300);
await tap(5); // light attack
await frame(900);
const hp1 = await page.evaluate(() => window.__E__.health);
console.log('COMBAT', hp0, '->', hp1, 'locked', await page.evaluate(() => !!window.__HOLLOW_CROWN__.lockTarget));
await shot('c09-combat-pad.png');

// Damage rumble check.
await page.evaluate(() => {
  const g = window.__HOLLOW_CROWN__;
  g.player.invuln = 0;
  g.player.takeDamage(30, g.player.pos.clone().add({ x: 0, y: 0, z: 1 }));
});
await frame(300);
console.log('RUMBLES', await page.evaluate(() => window.__RUMBLE_COUNT__));

console.log('ERRORS', errors.length);
await browser.close();

