import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.clock.install();
await page.goto('http://localhost:3002', { waitUntil:'load' });
await page.waitForFunction(() => window.__HOLLOW_CROWN__?.mode === 'title');
await page.clock.runFor(200);
console.log(await page.evaluate(() => {
  const g = __HOLLOW_CROWN__;
  const out = {};
  for (const child of g.scene.children) {
    let meshes = 0, inst = 0, tri = 0;
    child.traverse(o => {
      if (o.isInstancedMesh) { inst++; meshes++; }
      else if (o.isMesh) meshes++;
      if (o.isMesh) {
        const pos = o.geometry?.attributes?.position;
        if (pos) tri += (o.geometry.index ? o.geometry.index.count : pos.count) / 3 * (o.isInstancedMesh ? o.count : 1);
      }
    });
    if (meshes) out[child.name || child.type] = { meshes, inst, tri: Math.round(tri) };
  }
  // enemies
  const ecounts = g.enemies.map(e => {
    let m=0; e.root.traverse(o=>{ if(o.isMesh)m++; }); return { id:e.defId, m };
  });
  return { top: out, enemies: ecounts, totalMeshes: (()=>{let n=0;g.scene.traverse(o=>{if(o.isMesh)n++;});return n;})(), npcMeshes: (()=>{let n=0;g.npcs.forEach(npc=>npc.root.traverse(o=>{if(o.isMesh)n++;}));return n;})(), playerMeshes: (()=>{let n=0;g.player.root.traverse(o=>{if(o.isMesh)n++;});return n;})() };
}));
await browser.close();

